  (function(){
    var GENERIC_CTA = ' This is general information only - for a personalized review it\'s best to talk to Tal.';
    var categories = [
      { key:'invest', label:'📈 Wealth Management & Investments', items:[
        { q:'What is comprehensive financial planning?', kw:['comprehensive financial planning','asset mapping'],
          a:'Mapping your assets, income, and expenses to build a strategy for reaching your financial goals - including return optimization, risk diversification, and tax savings.' + GENERIC_CTA },
        { q:'How can I reduce the cost of managing my money?', kw:['reduce costs','management fees'],
          a:'A comprehensive review of your management fees against market alternatives can lower costs and improve your profit potential.' + GENERIC_CTA },
        { q:'Which investment vehicles do you specialize in?', kw:['investment vehicles','what you specialize in'],
          a:'Investment-track provident funds, savings policies, and study funds - each vehicle is matched to your risk level and time horizon (short/medium/long term).' + GENERIC_CTA },
        { q:'What is risk diversification in an investment portfolio?', kw:['diversification','risk','portfolio'],
          a:'The principle of not putting all your money in one vehicle - splitting between stocks, bonds, real estate, and different countries, so the portfolio isn\'t badly hurt by a decline in a single asset class.' },
        { q:'What is the difference between a savings policy and an investment-track provident fund?', kw:['savings policy','provident fund','investment'],
          a:'Investment-track provident fund: an annual deposit ceiling (about NIS 79,000) and tax exemption at retirement. Savings policy: no deposit ceiling, and you can switch tracks without triggering a tax event.' + GENERIC_CTA },
        { q:'How does inflation affect savings that aren\'t invested?', kw:['inflation','checking account','deposit'],
          a:'Money sitting in a checking account or a low-interest deposit loses purchasing power over time. Managed investment preserves the real value of your capital.' },
        { q:'Is it worth taking a loan against my study fund or pension?', kw:['loan','study fund','loan against savings'],
          a:'This is usually a relatively cheap way to raise credit (lower interest than banks), and the money keeps working in its original track - but it depends on the managing institution\'s terms.' + GENERIC_CTA },
        { q:'Why is a study fund worthwhile?', kw:['study fund','why'],
          a:'Full exemption from capital gains tax after 6 years - it is the only medium-term vehicle that remains completely tax-exempt.' },
        { q:'Equity track versus age-dependent track?', kw:['equity track','age-dependent','track'],
          a:'Equity track: high volatility, suited for the long term. Age-dependent track: risk automatically decreases as you approach retirement.' + GENERIC_CTA },
        { q:'Can I transfer a study fund between companies?', kw:['transfer study fund','moving funds'],
          a:'Yes, the transfer is completely free, with no cost and no tax event - seniority and the exemption are fully preserved.' },
        { q:'What are alternative investments?', kw:['alternative investments','real estate','p2p'],
          a:'Investments not traded on the stock exchange (real estate funds, P2P loans, debt funds) - low correlation to stock market fluctuations, but lower liquidity.' + GENERIC_CTA },
        { q:'What is an eligible investor?', kw:['eligible investor','accredited investor'],
          a:'A legal definition for someone with high liquid capital, which opens the door to exclusive investments such as hedge funds closed to the general public.' + GENERIC_CTA },
        { q:'An investment apartment or a financial portfolio in the capital market?', kw:['investment apartment','real estate','financial portfolio'],
          a:'Real estate: stable, allows leverage, but requires hands-on involvement and isn\'t liquid. Financial portfolio: fully liquid and globally diversified. The right combination depends on your capital and your preferences.' + GENERIC_CTA },
        { q:'How does the tax exemption on rental income work?', kw:['rental exemption','residential apartment'],
          a:'There is a monthly exemption threshold (around NIS 5,600); above the threshold, different tax tracks are available to choose from.' },
        { q:'Is there an inheritance tax in Israel?', kw:['inheritance tax','estate tax'],
          a:'As of today there is no inheritance tax in Israel, but selling real estate received as inheritance may trigger betterment tax, and pension/provident fund money passes to beneficiaries under special tax rules.' + GENERIC_CTA },
        { q:'What is the difference between the S&P 500 index and the TA-125?', kw:['s&p 500','tel aviv 125','index'],
          a:'The S&P 500 tracks the 500 largest companies in the US; the TA-125 tracks the 125 leading companies on the Tel Aviv Stock Exchange. Combining them properly creates geographic and currency diversification.' },
        { q:'What is compound interest?', kw:['compound interest'],
          a:'A situation where you earn a return both on the principal and on the profits already accumulated - the earlier you start, the more dramatic the long-term effect.' },
        { q:'I\'m a returning resident/new immigrant - what does it mean financially?', kw:['returning resident','new immigrant'],
          a:'Eligibility for significant tax benefits, including an exemption on income from outside Israel for a defined period - it\'s important to plan ahead so as not to lose these benefits.' + GENERIC_CTA },
        { q:'Should I refinance my mortgage?', kw:['mortgage refinance','refinancing'],
          a:'It depends on current interest rates versus the rates on your existing mortgage, and on early-exit penalties - the right refinancing can save tens to hundreds of thousands of shekels.' + GENERIC_CTA },
        { q:'What is a mortgage mix?', kw:['mortgage mix','loan tracks'],
          a:'Splitting the loan across different tracks (prime, fixed, variable) - to hedge against interest rate fluctuations and balance the monthly payment.' + GENERIC_CTA },
        { q:'What is structure insurance for a mortgage?', kw:['structure insurance','building insurance'],
          a:'Insurance that protects the property\'s value in the event of catastrophic damage (fire, earthquake) - the bank requires it to protect its collateral.' + GENERIC_CTA },
        { q:'Why should I invest with you instead of on my own through the bank\'s app?', kw:['why with you','on my own','bank app'],
          a:'The bank charges very expensive management fees and buy/sell commissions, and doesn\'t provide personalized, active guidance. With us you get a holistic view and a tax strategy.' + GENERIC_CTA },
        { q:'Is my money liquid in a financial savings policy?', kw:['liquid','savings policy'],
          a:'Yes, completely. The money is liquid on any business day, and withdrawal to your bank account typically takes just a few business days.' },
        { q:'What is the S&P 500 index and why does everyone talk about it?', kw:['s&p 500','index','united states'],
          a:'An index comprising the 500 largest companies in the US. Historically it has delivered very attractive long-term returns, but it is volatile and requires patience.' },
        { q:'How do you protect my money during sharp declines in the stock market?', kw:['downturns','protection','falling market'],
          a:'We build an asset mix in advance, diversified across stocks, bonds, and alternative assets, matched to your risk level, so you don\'t have to act under pressure during downturns.' + GENERIC_CTA },
        { q:'Are there kosher or halachic investment tracks?', kw:['kosher','halachic','track'],
          a:'Yes, absolutely. All the major companies offer investment tracks approved by a halacha committee, operating according to Jewish law.' },
        { q:'What happens to my profits if the index falls and inflation rises?', kw:['inflation','falling index'],
          a:'Inflation erodes the purchasing power of money. Investing in real or equity-based tracks for the long term is the best way to outpace inflation.' },
        { q:'What is the minimum amount needed to open a savings policy?', kw:['minimum','opening','savings policy'],
          a:'You can start with a monthly deposit of just a few hundred shekels, or with a one-time deposit (usually starting from NIS 10,000-20,000, depending on the company).' },
        { q:'Do you also help with mortgage review or refinancing?', kw:['mortgage review','refinancing'],
          a:'As part of holistic financial planning, Tal reviews your mortgage to see if the tracks can be improved, interest rates lowered, and to save you tens of thousands of shekels.' + GENERIC_CTA },
        { q:'Should I take a loan from my pension to cover a bank overdraft?', kw:['loan from pension','overdraft'],
          a:'Loans from pension bodies are usually the cheapest in the market. However, this should be done as part of a financial recovery plan so as not to create new debt.' + GENERIC_CTA },
        { q:'How does the Bank of Israel interest rate affect my money?', kw:['bank of israel interest rate'],
          a:'When the rate rises, loans and mortgages become more expensive, but on the other hand bank deposits and money-market funds offer higher returns. Tal helps you navigate this.' },
        { q:'What is a money-market fund and why is everyone moving money there from their checking account?', kw:['money market fund'],
          a:'This is a very conservative savings vehicle in the capital market that serves as an excellent alternative to a bank deposit. It is fully liquid and yields a return close to the Bank of Israel rate.' },
        { q:'What\'s best to do with NIS 100,000 available right now?', kw:['available cash','what to do'],
          a:'The answer depends on the purpose of the money and the time horizon. Short term - a money-market fund or deposit. Medium-to-long term - a savings policy or a managed investment portfolio. Tal will help you decide.' + GENERIC_CTA },
        { q:'How do you determine what risk level suits me?', kw:['risk level','needs assessment'],
          a:'We run a process called a "needs assessment" that examines your savings horizon, goals, and your psychological and financial ability to handle market fluctuations.' },
        { q:'What are ESG or green investments?', kw:['esg','green investing'],
          a:'These are investment tracks that select companies based on environmental, social justice, and corporate governance criteria. Such tracks exist at all the major companies.' },
        { q:'Is it better to invest in individual stocks or stock indices?', kw:['individual stocks','index funds'],
          a:'For most people, investing in indices (such as ETFs tracking stock indices) is preferable because it creates broad diversification and reduces the risk of a single company\'s collapse.' },
        { q:'What is the difference between a tradeable investment on the exchange and a non-tradeable investment?', kw:['tradeable','non-tradeable'],
          a:'A tradeable investment changes every second and can be sold immediately. A non-tradeable investment (such as real estate or debt funds) is less liquid, but more stable and doesn\'t experience daily volatility.' },
        { q:'How can I invest abroad without opening a foreign bank account?', kw:['invest abroad','foreign account'],
          a:'Through Israeli savings vehicles (provident funds, savings policies) you can easily gain full exposure to foreign markets, foreign currency, and global indices.' },
        { q:'Do you have investment solutions for businesses and companies too (holding companies)?', kw:['holding company','business investments'],
          a:'Absolutely. Tal manages investment portfolios and savings policies tailored for limited companies, enabling management of surplus cash flow and generating returns for the company.' + GENERIC_CTA },
        { q:'I\'m afraid of losing all my money in the stock market, what would you tell me?', kw:['afraid of losing money','stock market'],
          a:'The fear is natural. The key is proper diversification and building a conservative track suited to your character. Historically, those who stayed the course long-term and didn\'t act out of panic came out ahead.' + GENERIC_CTA },
        { q:'I own a company - is it better to draw a high salary or leave profits in the company and invest them?', kw:['business owner','salary','company profits'],
          a:'This is a classic tax planning question. Tal examines it together with your accountant, and offers solutions such as corporate savings policies or alternative investments.' + GENERIC_CTA },
        { q:'What is financial leverage and how do people use their pension to buy an apartment?', kw:['financial leverage','buying an apartment'],
          a:'This is a process of taking a low-interest loan against your savings (such as a study fund), and using that money as equity to purchase an asset that yields a higher return than the cost of the loan.' + GENERIC_CTA },
        { q:'How does a loan from a study fund affect the fund\'s return?', kw:['loan','fund return'],
          a:'It doesn\'t affect it at all. All your money in the study fund keeps working in the capital market and accruing the full return, as if you never took a loan.' },
        { q:'Which is better: a loan from the pension fund or a loan from the bank?', kw:['loan from pension','from the bank'],
          a:'In the vast majority of cases, a loan from a pension or provident fund will be much cheaper and at a better rate than the bank, because your money serves as excellent collateral for them.' },
        { q:'What is the prime interest rate and why did my mortgage go up because of it?', kw:['prime interest rate','mortgage went up'],
          a:'The prime rate is derived directly from the Bank of Israel rate (plus a fixed 1.5%). When the Bank of Israel raises rates to fight inflation, the prime track in your mortgage becomes more expensive immediately.' },
        { q:'Is a reverse mortgage worthwhile for seniors?', kw:['reverse mortgage','seniors'],
          a:'This is an excellent solution for retirees who own a property but lack monthly cash flow. Tal examines whether this move is worthwhile against other alternatives and together with family members.' + GENERIC_CTA },
        { q:'What is the difference between nominal tax and real tax on investments?', kw:['nominal tax','real tax'],
          a:'Real tax (25%) is calculated on the profit beyond inflation (the consumer price index). Nominal tax (15%, as in Amendment 190) is calculated on the total profit, regardless of inflation.' },
        { q:'Is there a capital gains tax exemption for older people?', kw:['capital gains tax exemption','section 125d'],
          a:'Yes, Section 125d of the Income Tax Ordinance grants an annual exemption from capital gains tax on certain deposits and savings plans for those born before 1948 (or their spouses).' },
        { q:'What is an Altshuler-style index or an index-tracking fund?', kw:['index fund','passive investing'],
          a:'This refers to passive investments that precisely track leading indices (such as the S&P 500 or the TA-125 index) instead of trying to guess which specific stocks will rise.' },
        { q:'How does the dollar exchange rate affect my pension savings?', kw:['dollar exchange rate','savings'],
          a:'A large portion of pension companies\' investments is abroad and managed in dollars. So when the dollar strengthens against the shekel, it usually boosts the value of your savings (and vice versa).' },
        { q:'Should a young person open an investment-track provident fund or just buy Bitcoin?', kw:['bitcoin','investment provident fund'],
          a:'Bitcoin is a very volatile and risky asset. An investment-track provident fund spreads the risk across hundreds of leading global companies and is managed by professionals. A solid combination is a sounder foundation.' + GENERIC_CTA },
        { q:'I want to save money for a big trip or for studies - where\'s the best place to put it?', kw:['saving for a trip','for studies'],
          a:'For the short term (one to two years) it\'s better to use a money-market fund or deposit to avoid the risk of a decline. Tal will match you to the right vehicle based on the timing of your trip or studies.' + GENERIC_CTA },
        { q:'Why does everyone say to put all your money in the S&P 500?', kw:['everyone says','s&p 500'],
          a:'Because this index has historically shown phenomenal performance over time. At the same time, it exposes you 100% to the US economy and the dollar. Tal will examine whether it\'s right to combine it with additional indices for you.' + GENERIC_CTA },
        { q:'What is the difference between the S&P 500 index and the MSCI World global index?', kw:['msci world','global index'],
          a:'The S&P 500 invests only in the 500 largest US companies. A global index spreads the investment across thousands of companies in various developed countries (such as Europe and Japan), creating broader diversification.' },
        { q:'Is an S&P 500 index-tracking track in a pension fund suitable for people approaching retirement?', kw:['approaching retirement','volatile equity track'],
          a:'It\'s generally not recommended for someone approaching retirement to be 100% in a volatile equity track, because a sharp market decline right before retirement could cut into their pension.' + GENERIC_CTA },
        { q:'What is the Nasdaq index and how does it differ from the S&P 500?', kw:['nasdaq'],
          a:'The Nasdaq focuses mainly on technology and science companies. It tends to rise very strongly during boom periods, but also to fall more sharply during crisis periods compared to the more diversified S&P 500.' },
        { q:'Is there currency risk (dollar/shekel) when investing in American indices?', kw:['currency risk','dollar shekel'],
          a:'Yes. Since the index is denominated in dollars, changes in the dollar-shekel exchange rate can affect your return back home. There are also currency-hedged tracks, and Tal will explain the differences to you.' + GENERIC_CTA },
        { q:'How does a generic equity track work compared to an index-tracking track?', kw:['generic equity track','active management'],
          a:'A generic equity track is managed by the company\'s investment managers who try to pick winning stocks (active management). An index-tracking track simply follows a fixed formula automatically (passive management).' },
        { q:'Are management fees lower in index-tracking tracks?', kw:['management fees','index tracking'],
          a:'In many cases yes, since the management is automatic and doesn\'t require an expensive team of analysts reviewing each stock individually. Tal makes sure to secure the most competitive terms.' + GENERIC_CTA },
        { q:'What happens to dividend profits in the S&P 500 index?', kw:['dividends','s&p 500'],
          a:'In Israeli savings and pension products, the dividends companies distribute are automatically reinvested back into the fund (accumulation), which further increases your compound interest effect.' },
        { q:'What is a financial crisis in the stock market and how often does it happen?', kw:['financial crisis','how often'],
          a:'This is a state of sharp declines in stock exchanges around the world (such as in 2008 or 2020). Historically, such crises happen every few years, but the market always corrects, grows, and reaches new highs afterward.' },
        { q:'What is the TA-35 index and should my pension be invested mainly in Israel?', kw:['ta-35'],
          a:'This is an index of the 35 largest companies on the Tel Aviv Stock Exchange. Today, most institutions prefer global diversification (both in Israel and abroad) so as not to depend solely on the local economy.' },
        { q:'How does taxation on capital market profits work if I don\'t withdraw the money?', kw:['taxation without withdrawal','tax withheld at source'],
          a:'As long as the money stays inside the savings plan (such as a savings policy or provident fund) and the profits are reinvested, no tax is paid. Tax is paid only on the day you withdraw money to your bank account.' },
        { q:'What is the difference between a fixed interest rate and a variable interest rate on loans?', kw:['fixed interest rate','variable interest rate'],
          a:'A fixed interest rate stays the same throughout the loan period and provides stability. A variable interest rate changes periodically (for example every year or every 5 years) based on indices or the Bank of Israel rate.' },
        { q:'What are investment management expenses and why are they charged in addition to the management fee?', kw:['investment management expenses'],
          a:'These are direct costs that management companies pay to external parties (such as buy/sell commissions for securities abroad). They are capped by law and reflected in the fund\'s return.' },
        { q:'Are there savings products where the insurance company guarantees I won\'t have losses?', kw:['no losses','guaranteed return'],
          a:'Currently there are no new products with an absolute guaranteed return in the free market. The only way to protect money from losses is to choose very conservative tracks (such as a short-term shekel or money-market track).' },
        { q:'How does Tal make sure I\'m not paying maximum management fees without noticing?', kw:['maximum management fees'],
          a:'As part of ongoing service, Tal\'s systems flag jumps in management fees (for example when changing jobs) and the team acts immediately with the company to restore the discount.' + GENERIC_CTA },
        { q:'What happens to money in a study fund if 6 years have passed and I haven\'t withdrawn it?', kw:['haven\'t withdrawn','6 years'],
          a:'It keeps accruing returns in the capital market and retains the full capital gains tax exemption. There is no obligation to withdraw it - the longer it stays, the more the tax-exempt compound interest effect works in your favor.' },
        { q:'What is a feeder fund (a managed alternative investment)?', kw:['feeder fund'],
          a:'This is a product that allows private Israeli investors to access major investments abroad (such as global real estate or tech funds) with relatively low entry amounts, through a local wrapper.' },
        { q:'Should I switch the insurance company on my mortgage in the middle of the term?', kw:['switch mortgage insurance'],
          a:'Yes, quite easily. You can port the life and structure insurance on your mortgage at any time. Tal will check for you whether the premium can be lowered to save you money each month.' + GENERIC_CTA },
        { q:'What is the Spitzer repayment schedule that shows up on my mortgage?', kw:['spitzer schedule','repayment schedule'],
          a:'This is the most common method for loan repayment, in which the total monthly payment stays constant (assuming the interest rate and index don\'t change), while the principal portion increases and the interest portion decreases over time.' },
        { q:'What is a fixed interest rate linked to the index (K"tz) and when is it risky?', kw:['index-linked fixed rate','k"tz'],
          a:'In this track the base interest rate is fixed, but your outstanding balance rises each month according to the consumer price index (inflation). In periods of high inflation, the debt can grow instead of shrinking.' + GENERIC_CTA },
        { q:'What is repayment capacity and how does the bank determine how much mortgage I\'m allowed to take?', kw:['repayment capacity'],
          a:'The bank requires that the monthly mortgage payment not exceed 35% to 40% of the household\'s net disposable income, to make sure you can safely keep up with the payments.' },
        { q:'What does grace period (payment deferral) mean on a loan?', kw:['grace period','payment deferral'],
          a:'This is an option to start paying the loan only after a certain period (for example six months). During the grace period you usually pay only the interest, or it accrues onto the overall debt.' },
        { q:'The stock market is crashing right now in the news, should I move everything to a conservative track immediately?', kw:['market crashing','move to conservative'],
          a:'This is usually the biggest mistake. Moving money during a downturn locks in the losses in practice and prevents you from benefiting from the quick correction that follows. A deep breath and a conversation with Tal are the solution.' + GENERIC_CTA },
        { q:'What is herd effect in the capital market and why is it dangerous for my savings?', kw:['herd effect'],
          a:'This is the situation where everyone rushes to buy a certain asset just because everyone else is buying (when the price is at its peak), or sells everything in a panic (when the price is at its lowest). Professional management prevents such emotional actions.' + GENERIC_CTA },
        { q:'What is the VIX volatility index and what does it say about the state of the market?', kw:['vix','fear index'],
          a:'The VIX index is known as the "fear index." The higher it is, the more it means there are sharp fluctuations and uncertainty in the markets. When it\'s low, the market is calm and stable.' },
        { q:'What is the difference between growth stocks and value stocks in an investment portfolio?', kw:['growth stocks','value stocks'],
          a:'Growth stocks are companies (usually tech) that reinvest all their profits into rapid growth. Value stocks are established, stable companies (such as banks or energy) that offer stability and pay dividends.' },
        { q:'What is the difference between a mutual fund and a financial savings policy?', kw:['mutual fund','savings policy'],
          a:'A mutual fund is bought through your bank account and involves buy/sell commissions and expensive custody fees to the bank. A savings policy is managed outside the bank, with no checking-account commissions and with tax deferral when switching tracks.' + GENERIC_CTA },
        { q:'What is an investor profile and how do I change it if I\'ve become more cautious?', kw:['investor profile'],
          a:'An investor profile defines the permitted risk level in your portfolio. If something has changed in your character or time horizon, Tal adjusts the asset mix accordingly and simply.' + GENERIC_CTA },
        { q:'Why is the capital market considered the best vehicle for savings of over 5 years?', kw:['over 5 years','best vehicle'],
          a:'Because over a history of more than 100 years, the capital market has always shown a positive, attractive average return for anyone with a time horizon of several years who showed patience.' },
        { q:'What is the Tel Aviv Tech-Elite index and is it suitable for long-term savings?', kw:['tech-elite index'],
          a:'This is an index comprising the largest tech and biomed companies traded on the Tel Aviv Stock Exchange. It is very volatile and offers concentrated exposure to the Israeli technology sector.' },
        { q:'What is a buy/sell commission at the bank and why doesn\'t a savings policy have one?', kw:['buy sell commission'],
          a:'Banks charge a commission on every trading action you carry out in the account. In products such as savings policies or provident funds, these commissions are built into the management fee and there is no separate charge per transaction.' },
        { q:'What is the difference between a government bond and a corporate bond?', kw:['government bond','corporate bond'],
          a:'A government bond is a loan you give to the state (considered the safest and most conservative). A corporate bond is a loan to a business (offers higher interest but carries the risk of the company collapsing).' },
        { q:'Is it worth investing in a money-market fund if interest rates in the economy start to fall?', kw:['money market fund','falling interest rates'],
          a:'When interest rates fall, the return on the money-market fund will fall accordingly. In that case, Tal will recommend shifting to vehicles that can lock in longer-term rates, or to bond and equity tracks.' + GENERIC_CTA },
        { q:'How does Tal make sure the insurance company doesn\'t change my investment track without approval?', kw:['track change','without approval'],
          a:'Insurance companies are not allowed to change a specific investment track without your explicit signature. Tal monitors and makes sure your money sits exactly in the track you approved in the needs assessment.' + GENERIC_CTA },
        { q:'What happens to my money in a savings policy if I stop making the monthly payment?', kw:['stop depositing'],
          a:'Nothing bad - the existing money stays in, continues to accrue full returns, and keeps its terms. New money simply isn\'t added, and there\'s no penalty or sanction.' },
        { q:'Is it worth using money from an open study fund to pay off an expensive bank loan?', kw:['pay off expensive loan'],
          a:'If the bank loan carries a very high interest rate (such as credit cards or an overdraft), it can sometimes be worthwhile. But the first step Tal checks is taking a cheap loan against the fund instead of closing it.' + GENERIC_CTA },
        { q:'I have company shares and options (RSUs) in tech - how does that relate to my financial planning?', kw:['rsu','stock options','company shares'],
          a:'This is a critical part of your capital. Tal examines your share-realization strategy (Section 102) and integrates them into the overall asset mix to prevent overexposure to a single company.' + GENERIC_CTA },
        { q:'What is a private credit fund and why is it considered a good alternative investment?', kw:['private credit','debt fund'],
          a:'This is a fund that provides loans directly to companies or real estate projects (outside the banking system). It generates a stable interest rate and isn\'t affected by the daily fluctuations of the stock exchange.' },
        { q:'What is dividend yield, and is it worth building a portfolio based only on dividend-paying stocks?', kw:['dividend yield'],
          a:'This is the percentage of profit a company distributes to shareholders in cash. A dividend-based portfolio suits someone who needs ongoing cash flow, but Tal recommends combining it so as not to hurt overall capital growth.' + GENERIC_CTA },
        { q:'What is duration (average lifespan) in bonds and why is it critical when interest rates change?', kw:['duration','average lifespan'],
          a:'Duration represents a bond\'s sensitivity to interest rate changes. A bond with long duration is more volatile, while short duration is more stable. Tal matches the portfolio\'s duration to the interest rate environment.' + GENERIC_CTA },
        { q:'What is a company\'s credit rating (like AAA) and how does it protect my investment?', kw:['credit rating'],
          a:'The rating determines a company\'s stability level and its ability to repay debt. Highly rated companies are the safest (low interest), and lower-rated companies offer higher risk (and higher interest).' },
        { q:'Are there investment tracks focused on artificial intelligence and future technology within savings policies?', kw:['artificial intelligence','future technology'],
          a:'Yes, there are sector-specific tracks focused on global technology that invest in AI and chip giants. Tal will help you incorporate them in the right dose so as not to endanger your entire portfolio.' + GENERIC_CTA },
        { q:'What are real assets in a pension fund (such as roads and power plants)?', kw:['real assets','infrastructure'],
          a:'These are pension fund investments in long-term national infrastructure. Their advantage is that they generate stable, index-linked cash flow, completely independent of stock market declines.' },
        { q:'What is the difference between a hedge fund and a regular mutual fund?', kw:['hedge fund','mutual fund'],
          a:'A mutual fund is open to the general public and heavily regulated. A hedge fund is usually intended for eligible investors or high-net-worth individuals, and uses complex strategies to profit even when the market falls.' },
        { q:'How does taxation work on foreign securities compared to Israeli securities?', kw:['foreign securities'],
          a:'In both cases the capital gains tax is 25% real. The difference is that with foreign securities you must account for currency exchange rate changes, and Tal manages these tax reports for you.' + GENERIC_CTA },
        { q:'What is a real estate investment trust (REIT) and is it liquid?', kw:['reit'],
          a:'This is a company that buys and manages income-producing real estate (offices, malls) and is required to distribute most of its profits as dividends. REITs traded on the exchange are fully liquid and can be sold any day.' },
        { q:'What is internal leverage by investment managers and how does it increase my return?', kw:['internal leverage'],
          a:'Institutional bodies use their bargaining power and scale to take out cheap loans and invest them in income-producing assets, which increases the overall fund\'s return without any effort on your part.' },
        { q:'What is negative inflation (deflation) and how does it affect my savings?', kw:['deflation','negative inflation'],
          a:'Deflation is a situation where prices in the economy fall. It\'s good for cash purchasing power in the short term, but it signals an economic slowdown that could hurt company profits on the exchange. Tal balances the portfolio for such situations.' + GENERIC_CTA },
        { q:'What is a structured deposit at the bank and is it better than a savings policy?', kw:['structured deposit'],
          a:'This is a deposit that guarantees the principal and offers a return conditional on the rise of a certain index or stock. The downside is that the money is locked in for many years, and the return is usually very limited compared to a flexible savings policy.' + GENERIC_CTA },
        { q:'What are dividend aristocrat stocks and why do investors love them?', kw:['dividend aristocrats'],
          a:'These are giant companies (mostly in the US) that have increased their dividend distribution every year in a row for at least 25 years. They are considered among the most stable anchors in any long-term investment portfolio.' },
        { q:'What is index-linking in savings plans and bonds?', kw:['index-linking','cpi linkage'],
          a:'It means that your money (the principal and profits) automatically grows in line with the rise in the consumer price index, ensuring the real value of your money is never eroded.' },
        { q:'What is the difference between active investment management and passive investment management?', kw:['active management','passive management'],
          a:'Active management tries to "beat the market" by having the portfolio manager pick specific stocks. Passive management simply tracks the general index (such as the S&P 500). Tal combines the two according to your needs.' + GENERIC_CTA },
        { q:'What is a bear market versus a bull market?', kw:['bear market','bull market'],
          a:'A bull market is a period of rising prices and optimism on the exchange. A bear market is a period of sustained declines and fear.' },
        { q:'What is a private equity fund and how can I access it through my savings?', kw:['private equity'],
          a:'These are funds that buy private companies, improve them, and sell them at a profit. The major insurance companies invest part of your pension and policy funds in these funds, generating you a return in the style of leading private equity funds.' },
        { q:'How does the State of Israel\'s credit rating affect my pension?', kw:['sovereign credit rating'],
          a:'If the country\'s rating falls, the cost of the government raising debt rises and the local stock exchange may experience declines. Thanks to the global diversification Tal builds for you, your portfolio is protected and a large portion of the money is invested abroad.' + GENERIC_CTA },
        { q:'What is the difference between a shekel money-market fund and a dollar money-market fund?', kw:['dollar money market fund'],
          a:'A shekel money-market fund tracks the Bank of Israel rate and suits those living in shekels. A dollar money-market fund tracks the US Fed rate and suits those with dollar needs or who want dollar protection.' + GENERIC_CTA },
        { q:'What is the most important psychological key to long-term investment success?', kw:['psychological key','investment success'],
          a:'The key is "filtering out background noise" - not being scared by frightening media headlines, sticking to the strategy Tal built for you, and remembering that time in the market always beats attempts to time the market.' },
        { q:'What investment tracks exist within savings policies?', kw:['investment tracks in a policy'],
          a:'A variety of tracks by risk level (general, equity, bonds, indices) with the option to switch between them without a tax event.' },
        { q:'Are there management fees on savings policies?', kw:['management fees on a policy'],
          a:'Yes. Unlike a bank-managed portfolio, there are no custody fees, but a monthly management fee is paid to the insurance company from the accumulated balance.' + GENERIC_CTA },
        { q:'Who is a savings policy suitable for?', kw:['who is a policy suitable for'],
          a:'For anyone interested in liquid savings and looking for an alternative to managing investments through the bank, with broader diversification.' + GENERIC_CTA },
        { q:'Can I receive an annuity from a savings policy?', kw:['annuity from savings policy'],
          a:'Yes, some policies allow withdrawal as a fixed monthly annuity upon retirement, sometimes with preferential tax planning.' + GENERIC_CTA },
        { q:'What happens if you withdraw money from a savings policy before retirement age?', kw:['withdrawal before retirement'],
          a:'Withdrawing the money isn\'t a penalty, but it does require paying capital gains tax of 25% on the real profit.' }
      ]},
      { key:'retire', label:'👵 Retirement Planning & Taxation', items:[
        { q:'When is the right time to start retirement planning?', kw:['when to start retirement','retirement planning timing'],
          a:'At least 3-5 years before your retirement date - some tax-saving moves require lead time, and this can significantly increase your net monthly pension.' + GENERIC_CTA },
        { q:'How can I reduce the tax on severance pay and pension?', kw:['reduce tax','severance pay','pension tax'],
          a:'Through smart tax planning - using exemptions, spreading tax liability over several years, and combining Amendment 190 - to keep the maximum net amount in your pocket.' + GENERIC_CTA },
        { q:'What is Amendment 190?', kw:['Amendment 190','tikun 190'],
          a:'A tax benefit for pension holders aged 60 and up, allowing investment in the capital market through a provident fund with a reduced capital gains tax (15% instead of 25%), with withdrawal as a lump sum or a tax-exempt pension.' + GENERIC_CTA },
        { q:'What is fixation of rights?', kw:['fixation of rights','kibua zchuyot'],
          a:'A process with the Tax Authority at retirement age to choose how to use your tax exemption (on the pension or on severance pay). This is an irreversible move - it should be planned carefully and not decided on your own.' + GENERIC_CTA },
        { q:'What is the difference between a recognized pension and an eligible pension?', kw:['recognized pension','eligible pension'],
          a:'Different tax classifications: eligible pension - funds that received a tax benefit on deposit. Recognized pension - exempt funds, and therefore completely exempt from income tax.' + GENERIC_CTA },
        { q:'Can I keep working after retirement age and still receive a pension?', kw:['keep working after retirement','work and pension'],
          a:'Yes, this is a common combination - but it may push you into a higher income tax bracket, so tax coordination and integrated retirement planning are important.' + GENERIC_CTA },
        { q:'What happens to my pension savings if I pass away?', kw:['pass away','death','survivors'],
          a:'The funds are protected and pass to your survivors/beneficiaries - a monthly pension from a pension fund, a lump sum from a provident fund. It is important to update your beneficiaries every few years.' + GENERIC_CTA },
        { q:'Is it worth withdrawing severance pay or leaving it for retirement?', kw:['severance pay','withdraw severance'],
          a:'It is usually better to leave it - withdrawing severance pay can reduce your old-age pension by about 40% and harm the tax exemption on your future pension. There are exceptional cases worth checking individually.' + GENERIC_CTA },
        { q:'What happens to my pension if my employer goes bankrupt?', kw:['employer bankruptcy','company goes bankrupt'],
          a:'Your money is fully protected - it is deposited in a separate account in your name at the managing company, not part of the employer\'s assets.' + GENERIC_CTA },
        { q:'What is the minimum pension threshold?', kw:['minimum pension','minimum threshold'],
          a:'A legal pension threshold (about NIS 5,000) above which you are allowed to withdraw other capital funds tax-exempt.' + GENERIC_CTA },
        { q:'How do divorce or a second marriage affect my pension?', kw:['divorce','marital status','remarriage pension'],
          a:'A significant effect on the division of the pension and rights - in a divorce, a note can be registered in favor of the ex-spouse, and at retirement the survivor pension is set for the current spouse.' + GENERIC_CTA },
        { q:'Is it worth transferring an old executive insurance policy to a pension fund?', kw:['transfer executive insurance','old executive insurance'],
          a:'A decision that requires review - pension funds have lower management fees; old executive insurance policies sometimes have a guaranteed conversion rate. An incorrect transfer can harm your rights irreversibly.' + GENERIC_CTA },
        { q:'What is a pension conversion rate?', kw:['conversion rate','pension coefficient'],
          a:'The number by which your accumulated savings are divided to determine your monthly pension - the lower the rate, the higher the pension.' },
        { q:'What is the difference between a pension fund and executive insurance?', kw:['difference','pension fund','executive insurance'],
          a:'A pension fund is based on mutual guarantee and bylaws that can change. Executive insurance is a personal, fixed contract, usually with higher management fees. Today a pension fund is usually preferable.' },
        { q:'Where is the best place for me to open a pension fund?', kw:['where to open','pension fund'],
          a:'There is no single company that is right for everyone. The choice depends on your age, investment track, management fees, and health status. Tal will match you with the most precise fund for you in a meeting.' + GENERIC_CTA },
        { q:'Why are my pension management fees so high and how can I lower them?', kw:['management fees','high fees','lower fees'],
          a:'Management fees are set based on the amount accumulated and deposited. You can negotiate with the companies or transfer the money. We would be happy to check whether they can be reduced for you.' + GENERIC_CTA },
        { q:'How can I find out how much money I have accumulated at all?', kw:['how much accumulated','pension clearinghouse'],
          a:'The best way is to produce a data consolidation report from the pension clearinghouse. We do this for our clients as part of the financial mapping process.' },
        { q:'What happens to my pension if the managing company goes bankrupt?', kw:['managing company','bankruptcy'],
          a:'Your money does not belong to the managing company but is registered in your name in trust. If the company collapses, another company will simply take over management of the fund. The money is protected.' },
        { q:'How is income tax calculated on my pension payments?', kw:['income tax','pension payments'],
          a:'A pension payment is considered earned income and is subject to the Income Tax Ordinance, but there are significant exemptions (such as fixation of rights) that reduce the tax to a minimum.' + GENERIC_CTA },
        { q:'What is the difference between "simulated" retirement and regular retirement?', kw:['simulated retirement'],
          a:'Simulated retirement lets you continue working as usual while simultaneously starting to receive a partial or full pension, taking advantage of unique tax benefits.' + GENERIC_CTA },
        { q:'Can I withdraw my entire pension as a single lump sum?', kw:['withdraw everything','lump sum'],
          a:'Only if you have a guaranteed minimum pension (currently around NIS 5,000 per month). Beyond that amount, you can carry out a pension commutation subject to Tax Authority approval.' + GENERIC_CTA },
        { q:'What is better for a retiree: an investment portfolio or a savings policy with Amendment 190?', kw:['retiree','Amendment 190','investment portfolio'],
          a:'For those over age 60, Amendment 190 is usually the most cost-effective option thanks to a reduced capital gains tax of just 15% nominal (instead of 25% real) and the option of a tax-exempt pension.' + GENERIC_CTA },
        { q:'Is my National Insurance old-age allowance affected if I have a high pension?', kw:['old-age allowance','National Insurance'],
          a:'No. The National Insurance old-age allowance is not affected by the amount of your mandatory pension, but it may be reduced if you have high income from work at the conditional retirement age.' },
        { q:'How does a retirement grant (severance pay from the employer) affect the pension tax exemption?', kw:['retirement grant','combination formula'],
          a:'Withdrawing tax-exempt severance pay in the 32 years preceding retirement creates a "combination formula" that reduces the exemption you can receive on your monthly pension payment.' + GENERIC_CTA },
        { q:'I am self-employed, how much am I required by law to deposit into a pension?', kw:['self-employed','mandatory deposit'],
          a:'The mandatory pension law for the self-employed requires a deposit based on percentages of your statutory income (up to the average wage ceiling in the economy). Beyond the requirement, it is very worthwhile tax-wise.' + GENERIC_CTA },
        { q:'How do I check how much I am actually being charged in management fees?', kw:['check management fees'],
          a:'You can see this in the annual or quarterly report sent to you, or simply contact us and we will be happy to produce the exact figures for you and check whether they are too high.' },
        { q:'I feel like I\'m being bled dry by pension management fees, what can I do?', kw:['high management fees','being overcharged'],
          a:'Tal knows how to run a tender against the major companies. In many cases, transferring the fund or increasing deposits allows us to significantly lower the management fees.' },
        { q:'If I switch companies, does my previous pension fund get closed?', kw:['switching companies','previous fund'],
          a:'No, the old money is simply merged automatically into the new fund, together with all the seniority and rights you have accumulated.' },
        { q:'What happens to my old executive insurance if I stop depositing into it?', kw:['old executive insurance','frozen policy'],
          a:'It becomes "frozen" (inactive) status. The money will continue to accumulate returns, but the management fees taken from the balance may rise to the maximum. It\'s worth having Tal review it.' + GENERIC_CTA },
        { q:'Am I required to have a pension fund, or can I save independently in the bank for retirement?', kw:['mandatory pension','saving in the bank'],
          a:'Under Israeli law there is a mandatory pension savings requirement. Beyond that, saving in the bank does not provide the tax benefits or insurance coverage that a pension does.' },
        { q:'What is better, an age-based track or a fixed equity track?', kw:['age-based track','lifecycle fund'],
          a:'The age-based track (the "Chilean model") automatically reduces risk as you get older. A fixed equity track suits someone who wants high exposure regardless of age.' + GENERIC_CTA },
        { q:'How does the mandatory pension affect my net salary?', kw:['mandatory pension','net salary'],
          a:'The pension deposit slightly reduces your current net pay, but the law grants you a tax credit on these deposits, so part of the money comes back to you immediately.' },
        { q:'Does a pension fund generate better returns than a bank savings plan?', kw:['pension fund','bank savings plan'],
          a:'Historically, the capital market through pension funds has shown far higher returns over time compared to the low interest rates and sub-par returns of bank savings plans.' },
        { q:'What is actuarial balancing in a pension fund and why does it cost me money?', kw:['actuarial balancing','actuarial deficit'],
          a:'This is a mutual balancing mechanism among fund members. If in a given year more claims (disability or survivors) were paid out than expected, the fund charges everyone a small deficit levy, and vice versa.' },
        { q:'Can I decide who will receive my pension if I die?', kw:['beneficiaries','who receives it'],
          a:'In a pension fund, survivors (spouse and children) have legal priority. If there are no survivors, the money goes to the beneficiaries named in the fund\'s beneficiary form.' },
        { q:'I want to retire at age 55, is that financially feasible?', kw:['early retirement','age 55'],
          a:'To retire early you need to build a strategy of liquid capital that will sustain you until the age at which you can draw your official pension. We would be happy to build such a model for you.' + GENERIC_CTA },
        { q:'What is the difference between mandatory retirement age and eligibility retirement age?', kw:['mandatory retirement age','eligibility age'],
          a:'Eligibility age (62-65 for women, 67 for men) is the age from which you can begin receiving a pension and allowances. Mandatory age (67 for everyone) is the age at which an employer can require you to retire.' },
        { q:'What do I do with Form 161 and how is it related to a retirement grant?', kw:['Form 161'],
          a:'This is the employer\'s notice-of-retirement form detailing the severance pay owed to you. It is critical for calculating tax exemptions - it is important not to sign it before Tal reviews it.' },
        { q:'I heard about Amendment 190, how does it help me save on tax?', kw:['Amendment 190','save on tax'],
          a:'It allows you to deposit a lump sum into a provident fund, benefit from professional management in the capital market, and withdraw the money from age 60 at only 15% nominal tax or as a tax-exempt pension.' + GENERIC_CTA },
        { q:'What is severance pay continuity and why is it beneficial?', kw:['severance pay continuity'],
          a:'Leaving severance funds in the fund when moving between jobs without paying tax on them now, in order to preserve the option to merge them with severance pay from future employers.' },
        { q:'What is pension continuity at retirement?', kw:['pension continuity'],
          a:'A declaration that you are leaving your severance funds inside your pension savings so that they will be paid to you in the future as part of a monthly pension, thereby deferring or canceling the tax liability on them.' },
        { q:'How can grandparents transfer money to grandchildren in a financially smart way?', kw:['grandparents','grandchildren'],
          a:'You can open an investment provident fund in the grandchildren\'s name or use a savings policy that allows smooth intergenerational transfer, exempt from estate tax and with control over the withdrawal timing.' + GENERIC_CTA },
        { q:'Is there inheritance tax on savings policies and provident funds in Israel?', kw:['inheritance tax','savings policies','provident funds'],
          a:'As of today, there is no inheritance tax in Israel. The beneficiaries named in the funds or policies will receive the money, but in certain products capital gains tax will be paid upon withdrawal.' + GENERIC_CTA },
        { q:'What happens to the survivor pension if the spouse remarries?', kw:['survivor pension','remarriage'],
          a:'It depends on the specific pension fund\'s bylaws. In most newer funds, the survivor pension for a spouse continues to be paid even if they remarry.' + GENERIC_CTA },
        { q:'How do I combine a monthly pension payment with rental income in retirement?', kw:['rental income','pension payment'],
          a:'Residential rental income (up to the exemption ceiling) is tax-exempt and is not counted together with your pension payment, which allows for very efficient cash-flow planning in retirement.' + GENERIC_CTA },
        { q:'As a self-employed person, how much can I deposit into a study fund to get the maximum tax exemption?', kw:['self-employed','study fund','maximum exemption'],
          a:'The ceiling for a tax-advantaged deposit changes every year. Tal will calculate the exact deposit percentage of your income for you so you don\'t miss out on a single shekel of tax exemption.' + GENERIC_CTA },
        { q:'If I open a new business, am I required to continue the pension from my previous job as a salaried employee?', kw:['new business','continuity of rights'],
          a:'It is highly recommended to maintain continuity of rights so as not to lose insurance coverage (such as disability and survivors). Tal will help you convert the fund from an employee pension to a self-employed pension.' + GENERIC_CTA },
        { q:'Should a self-employed person deposit into an investment provident fund or a pension fund?', kw:['self-employed','provident fund or pension'],
          a:'A pension fund provides immediate tax benefits (deduction and credit) on the deposit. An investment provident fund is more flexible but does not give a tax benefit on deposit. Combining the two is usually the solution.' + GENERIC_CTA },
        { q:'How can a self-employed person withdraw money from the business for personal savings without paying too much tax?', kw:['withdraw from business','high tax'],
          a:'There are advanced financial tools that allow tax-recognized deposits. Tal will build a strategy with you that leaves more money with you and less with the Tax Authority.' + GENERIC_CTA },
        { q:'What happens to the business\'s study fund if I close my sole proprietorship?', kw:['closing sole proprietorship'],
          a:'The fund remains entirely yours. It will continue to accumulate returns and retain the capital gains tax exemption, you just won\'t be able to deposit into it anymore as self-employed.' },
        { q:'Is the mandatory pension law for the self-employed actually enforced, with fines?', kw:['enforced','fines for self-employed'],
          a:'Yes, the Tax Authority sends warnings and fines to self-employed people who have not deposited the legally required minimum. Beyond the legal requirement, it simply pays off financially.' },
        { q:'What is "determining salary" for a self-employed person\'s pension?', kw:['determining salary'],
          a:'This is the average of your taxable income (the business\'s net profit) by which your deposit percentages and insurance coverage in the event of disability are calculated.' },
        { q:'I earn a lot as self-employed, is there a limit on how much money I can put into a pension?', kw:['deposit limit','high earner'],
          a:'There is a monthly deposit ceiling that receives protection from designated bonds/guaranteed return. Beyond this ceiling, the money is directed to a "supplementary pension" under the same management terms.' + GENERIC_CTA },
        { q:'How is the pension divided in the event of a divorce?', kw:['divorce','pension division'],
          a:'Under the pension savings division law, an ex-spouse may be entitled to part of the balance accumulated during the marriage. Tal helps sort things out and calculate the exact amount according to the court ruling.' + GENERIC_CTA },
        { q:'I was laid off, how long does my pension fund stay active?', kw:['laid off','insurance extension period'],
          a:'The fund remains automatically active for 5 months (the insurance extension period). To avoid losing coverage after that, you need to arrange "temporary risk coverage" or continue depositing independently.' + GENERIC_CTA },
        { q:'A relative passed away, how do I find out if they had insurance policies or pensions we didn\'t know about?', kw:['passed away','locating funds'],
          a:'You produce a dedicated report for the deceased through the "Har HaBituach" and pension clearinghouse websites. Tal accompanies families in locating these funds and filing claims with the companies.' + GENERIC_CTA },
        { q:'I got sick and can\'t work, who do I claim money from - National Insurance or the pension fund?', kw:['got sick','disability claim'],
          a:'You can and should claim from both simultaneously. The pension fund (disability component) will pay you a monthly allowance, offset by what you receive from National Insurance, up to a ceiling of 75% of your salary.' + GENERIC_CTA },
        { q:'My husband passed away, when should I contact his pension fund to receive a survivor pension?', kw:['husband passed away','survivor pension'],
          a:'As soon as possible. The pension is paid retroactively, but submitting the documents requires accuracy (death certificate, inheritance order or probate order). Tal is here to help you through the process.' + GENERIC_CTA },
        { q:'If I withdraw money early from my pension due to a difficult financial situation, is there a way to avoid the 35% tax?', kw:['low income','avoiding tax'],
          a:'In certain cases of low income or a high medical disability rating of the saver or a relative, a tax exemption can be obtained by submitting a special request to the tax assessor. Tal will review this for you.' + GENERIC_CTA },
        { q:'What happens to my pension payment if I decide to move abroad after retirement?', kw:['living abroad','pension abroad'],
          a:'The pension will continue to be paid into your bank account in Israel (or abroad, under certain restrictions). However, it is important to review the tax treaties between Israel and the destination country.' + GENERIC_CTA },
        { q:'What is a tax-exempt pension commutation and how does it help me get a large lump sum at once?', kw:['tax-exempt commutation'],
          a:'This is a legal option to receive part of your future pension as a one-time tax-exempt lump sum, provided you retain a minimum monthly pension as required by law.' + GENERIC_CTA },
        { q:'If I have a medical disability, am I entitled to a tax exemption on my pension payment?', kw:['medical disability','tax exemption'],
          a:'Yes. People with a high, stable medical disability rating (under section 9(5) of the Ordinance) are entitled to significant income tax exemptions, both on the retirement pension and on capital gains.' + GENERIC_CTA },
        { q:'What is the difference between an old-age pension and a disability pension within the fund?', kw:['old-age pension','disability pension'],
          a:'A disability pension is paid if you lose your working capacity before retirement age. An old-age pension is the regular payment you receive for the rest of your life starting from retirement age.' },
        { q:'How do unemployment benefits at an older age affect my pension?', kw:['unemployment benefits'],
          a:'Unemployment benefits are considered taxable income but do not harm the pension rights you have accumulated. You can receive unemployment benefits before you start drawing your old-age pension.' },
        { q:'What is the significance of the new Form 161 issued in recent years?', kw:['new Form 161'],
          a:'This is a unified form that simplifies reporting on retirement grants and severance pay. It requires absolute precision from the employer so that you don\'t mistakenly pay excess tax.' + GENERIC_CTA },
        { q:'Is the pension fund\'s survivor pension also paid to adopted or stepchildren?', kw:['adopted children','stepchildren'],
          a:'Yes, a stepchild or adopted child who was under the insured person\'s care and support is considered a survivor for all purposes and is entitled to a pension until age 21 (in most funds).' },
        { q:'What is a "guaranteed annuity" track in an old executive insurance policy?', kw:['guaranteed annuity track','old executive insurance'],
          a:'These are policies from the 1990s and early 2000s that guaranteed a fixed, low conversion rate, which produces a relatively high pension. These policies must not be touched or transferred without a careful review by Tal.' + GENERIC_CTA },
        { q:'How does a provident fund under Amendment 190 protect me from sharp capital-market fluctuations at an older age?', kw:['Amendment 190','protection at older age'],
          a:'It allows exposure to non-tradable alternative assets (infrastructure, income-producing real estate) that insurance companies invest in, which creates greater portfolio stability compared to the stock market.' + GENERIC_CTA },
        { q:'What is a taxable pension commutation and how does it affect taxation at retirement?', kw:['taxable commutation'],
          a:'This is a procedure in which a lump sum subject to tax is withdrawn (as opposed to a tax-exempt commutation). Tal will calculate whether this move is worthwhile to make sure you don\'t jump into too high a tax bracket.' + GENERIC_CTA },
        { q:'Is it worth transferring financial assets into my children\'s names to reduce tax liability?', kw:['assets in children\'s names'],
          a:'In certain cases this is possible (for example, in an investment provident fund), but you must take into account the loss of control over the money. Tal will help you weigh the pros and cons.' + GENERIC_CTA },
        { q:'How does rising life expectancy affect my pension?', kw:['life expectancy'],
          a:'As life expectancy rises, pension companies are forced to raise the conversion rate (dividing the sum over more months), which reduces the monthly pension. That is why it is important to increase your savings as early as possible.' + GENERIC_CTA },
        { q:'What is a tax-exempt retirement grant and what is its current ceiling?', kw:['tax-exempt retirement grant','ceiling'],
          a:'This is the portion of severance funds that may be withdrawn without paying income tax when leaving a job. The ceiling is updated every year and stands at a fixed amount per year of employment.' },
        { q:'Can a retiree get a loan against their monthly pension payment?', kw:['loan against pension'],
          a:'In some of the veteran or newer pension funds, you can get loans on excellent terms that are offset directly from the monthly pension. Tal will check this option for you.' + GENERIC_CTA },
        { q:'What are pension fund bylaws and why is it said they can change to my disadvantage?', kw:['pension fund bylaws'],
          a:'A pension fund is based on dynamic bylaws (rather than a fixed contract). If there are demographic or economic changes in the economy, the state and the fund can update the bylaws in order to maintain the fund\'s stability.' },
        { q:'Is it worth combining a savings policy together with an investment provident fund in the same family portfolio?', kw:['combining policy and provident fund'],
          a:'Yes, this is a common combination. The provident fund is limited by an annual deposit ceiling but offers the option of a tax-exempt pension. The savings policy allows unlimited deposits and full liquidity.' + GENERIC_CTA },
        { q:'How does Tal help me choose the right retirement track out of dozens of options in the fund?', kw:['retirement track'],
          a:'At retirement age you need to choose a pension track (for example: with guaranteed payments to the spouse, or protection for children). Tal analyzes your family and health situation and recommends the track that maximizes the money for your family.' + GENERIC_CTA },
        { q:'What is a "bridging pension" and who is entitled to receive it?', kw:['bridging pension'],
          a:'This is an allowance paid by the employer (usually in public-sector or security-related bodies) from the time of early retirement until reaching the statutory retirement age at which the pension from the fund begins.' },
        { q:'Is it worth using tax-exempt severance funds to pay off small debts?', kw:['pay off debts','tax-exempt severance'],
          a:'Generally not. Withdrawing severance pay severely harms your future pension and reduces the tax exemption at retirement. It is better to find other, cheaper credit solutions.' + GENERIC_CTA },
        { q:'I\'m only 23, why should I think about a pension now?', kw:['age 23','young'],
          a:'Precisely because of your young age - every shekel you deposit now will compound over 40 years and become a substantial sum at retirement. Those who start early work less hard later on.' },
        { q:'I work occasional jobs as a student, is my employer required to make pension contributions for me?', kw:['student','occasional jobs'],
          a:'Yes, absolutely. The mandatory pension law applies to every employee from age 21 for men and 20 for women, after 6 months of employment (or 3 months if you already have an active fund).' },
        { q:'I have no money to save, I can barely make ends meet each month, how can I invest at all?', kw:['no money to save'],
          a:'You can start very small. A savings policy or an investment provident fund allows deposits starting from NIS 100 or 200 per month. Tal will help you build a proper savings habit.' + GENERIC_CTA },
        { q:'What is a default pension fund and why was one opened for me without my being asked?', kw:['default fund'],
          a:'These are funds selected by the state that offer reduced management fees for those who did not choose a fund themselves. They are a good solution, but it is still important for Tal to check whether the investment track suits your age.' + GENERIC_CTA },
        { q:'I\'ve already changed jobs 4 times this year, what happens to all the pension funds that were opened for me?', kw:['changed jobs','scattered funds'],
          a:'You likely have money scattered across several places. The old funds may be accumulating maximum management fees. Tal will sort everything out for you and consolidate it all under one cost-effective roof.' + GENERIC_CTA },
        { q:'How do I open a study fund if my employer refuses to open one for me?', kw:['employer refuses','study fund'],
          a:'A salaried employee cannot open a study fund without the employer\'s consent (it is a benefit, not a legal requirement). Tal can offer you excellent savings alternatives such as a financial savings policy.' + GENERIC_CTA },
        { q:'What happens if I don\'t do a fixation of rights at retirement age?', kw:['without fixation of rights'],
          a:'You may simply end up paying full, high income tax on your pension payment, and miss out on legal exemptions worth hundreds of thousands of shekels that the state grants you.' + GENERIC_CTA },
        { q:'What is tax coordination and when must a retiree do it?', kw:['tax coordination'],
          a:'If you have two different pension payments, or if you receive a pension while continuing to work, you must do tax coordination so that maximum tax isn\'t automatically deducted from you.' + GENERIC_CTA },
        { q:'What is Form 161 and who is supposed to give it to me, the employer or the Tax Authority?', kw:['Form 161','who provides it'],
          a:'Your employer is legally required to provide you with Form 161 when your employment ends. This form details all the severance funds accumulated in your favor.' },
        { q:'What is the difference between an annuity-based exemption and a capital-based exemption?', kw:['annuity exemption','capital exemption'],
          a:'An annuity-based exemption reduces the tax on your monthly pension payment. A capital-based exemption allows you to withdraw a tax-exempt lump sum. Tal balances between them based on your needs.' + GENERIC_CTA },
        { q:'How is a financial savings policy taxed when you withdraw only part of the money?', kw:['partial withdrawal','policy taxation'],
          a:'The tax (25% real) is paid only on the proportional profit component within the amount you withdrew (partial redemption), not on the entire principal you deposited.' },
        { q:'What is a recognized pension for someone who saves money independently beyond the mandatory pension?', kw:['recognized pension','independent savings'],
          a:'This is a mechanism that ensures money you deposited without a tax benefit on deposit will be paid to you at retirement as a pension completely exempt from income tax (Amendment 3).' },
        { q:'Am I allowed to deposit into an investment provident fund for my children and enjoy tax benefits?', kw:['investment provident fund for children'],
          a:'There is no tax benefit on deposit into an investment provident fund, but the great advantage is that if the children keep the money until age 60, they will be able to withdraw it as a pension completely exempt from tax.' + GENERIC_CTA },
        { q:'What is the tax on funds of deceased savers in provident funds?', kw:['funds of deceased savers','death tax'],
          a:'If a saver dies before age 75, their beneficiaries are entitled to withdraw the provident fund money fully exempt from capital gains tax. If they die after age 75, a 15% nominal tax will be paid.' },
        { q:'How does Tal help me deal with the tax assessor without getting into trouble?', kw:['tax assessor'],
          a:'Tal prepares the entire package of forms and optimal calculations for you (such as Form 161d), and guides you exactly on what to submit in order to receive the maximum exemption approvals.' + GENERIC_CTA },
        { q:'What is a "developing disability" pension within the pension fund?', kw:['developing disability'],
          a:'This is a mechanism that ensures that while you are receiving a disability pension (loss of working capacity), the pension fund continues to deposit money on your behalf toward your future old-age savings, so that your pension is not harmed.' },
        { q:'Is there a limit on withdrawing money from an investment provident fund after age 60?', kw:['withdrawal after 60'],
          a:'There is no limit at all. From age 60 and up you get a huge bonus: the option to convert all the money into a monthly pension completely exempt from income tax and from capital gains tax.' + GENERIC_CTA },
        { q:'What is the difference between legal heirs and survivors in terms of priority order in a pension?', kw:['legal heirs','survivors'],
          a:'Survivors (spouse and children) take precedence over everyone and receive a mandatory monthly pension. Legal heirs (per a will or inheritance) receive a capital sum only if there are no surviving survivors.' },
        { q:'What is a rights-continuity agreement between veteran and new pension funds?', kw:['rights continuity'],
          a:'This is a legal agreement that allows a saver who moved during their lifetime from a veteran fund to a new fund to preserve their seniority and rights in both worlds for the purpose of calculating the final pension.' },
        { q:'How does a retirement grant I received in cash from my employer affect my fixation of rights?', kw:['combination formula','cash grant'],
          a:'Withdrawing a tax-exempt severance grant creates a 1.35x reduction in the amount of exemption you can receive on your monthly pension payment (the combination formula). Tal will calculate whether it\'s worthwhile.' + GENERIC_CTA },
        { q:'Can a retiree open a new study fund independently?', kw:['retiree','new study fund'],
          a:'A study fund can only be opened against income from work (as self-employed or salaried). A retiree who is not working cannot open a new fund, but can continue managing existing tax-exempt funds.' },
        { q:'What happens to severance pay funds that remained in the old fund and were not withdrawn for over 20 years?', kw:['20 years','old severance funds'],
          a:'They continue working, accumulating returns, and enjoying full tax deferral. On the day of retirement, Tal will incorporate them into the fixation process so you can withdraw them at minimum tax.' + GENERIC_CTA },
{ q:'What is early retirement for health reasons and how does it affect taxation?', kw:['health-related retirement','disability retirement tax'],
  a:'If retirement was caused by disability or a serious medical condition, the Tax Authority grants much broader exemptions (up to a full tax exemption under higher ceilings). Tal will guide you through the process with them.' + GENERIC_CTA },
{ q:'How does Tal build a cash flow plan from liquid assets in retirement?', kw:['retirement cash flow','withdrawal plan'],
  a:'Tal takes all the liquid capital you have accumulated (policies, portfolios) and calculates an optimal monthly withdrawal model that guarantees you a steady "salary" throughout your retirement years without eroding the principal.' + GENERIC_CTA },
{ q:'I\'m retiring from the IDF or police with a budgetary pension - can Tal help me with the taxation?', kw:['budgetary pension','IDF or police retirement'],
  a:'Absolutely. Budgetary pensions involve very complex tax rules and unique retirement grants. Tal specializes in maximizing exemptions and tax benefits for security-sector retirees.' + GENERIC_CTA },
{ q:'What is the difference between a budgetary pension and an accumulating pension?', kw:['budgetary pension','accumulating pension'],
  a:'A budgetary pension is paid directly from the employer\'s budget and is based on your final salary and seniority (independent of capital markets). An accumulating pension is based on the money you actually saved in the fund.' },
{ q:'I\'m a teacher with the Ministry of Education - how is my pension calculated when I go on sabbatical?', kw:['teacher','sabbatical year'],
  a:'During a sabbatical year, pension contributions stop or change according to the terms of the teachers\' study fund. Tal will help make sure you don\'t lose rights or insurance coverage during this period.' + GENERIC_CTA },
{ q:'What is pension capitalization for state employees and when is it worthwhile?', kw:['pension capitalization','government employees'],
  a:'This is the option to give up part of your monthly annuity for a number of years in exchange for a large lump sum immediately upon retirement. Tal will calculate whether the move is worthwhile and its tax implications.' + GENERIC_CTA },
{ q:'Is a budgetary pension protected against actuarial deficits in the capital market?', kw:['actuarial deficit','budgetary pension'],
  a:'Yes, completely. Since it is not affected by stock market performance but is paid by law or collective agreement directly from the state, it does not suffer from these deficits.' },
{ q:'I\'m retiring from a government company and received an increased severance package - how do I avoid paying half of it to the Tax Authority?', kw:['increased severance package','voluntary retirement'],
  a:'Voluntary retirement or increased severance packages require careful tax planning (tax spreading, annuity continuity, or exempt severance). Don\'t sign any document before Tal has reviewed it.' + GENERIC_CTA },
{ q:'Am I allowed to work in the private sector after retiring from public service with a monthly annuity?', kw:['private sector','working after retirement'],
  a:'Yes, in most cases there is no legal obstacle to working in the private sector, but you will need to coordinate tax between your new salary and your retirement annuity to avoid maximum tax withholding.' + GENERIC_CTA },
{ q:'What happens to my budgetary pension if I pass away, God forbid? Is my family protected?', kw:['budgetary pension','death of pensioner'],
  a:'Yes. The spouse and children (up to age 21 in most bodies) are entitled to a survivors\' pension at fixed percentages of the annuity you would have received, according to the government body\'s regulations.' },
{ q:'What is the "Chief of Staff supplement" to a pension and how does it affect taxation?', kw:['Chief of Staff supplement'],
  a:'This is a percentage addition to the annuity granted at discretion. It is considered part of taxable income, and Tal will incorporate it into your rights-fixation calculations at retirement.' + GENERIC_CTA },
{ q:'I\'m a municipal employee with a veteran pension - is there a cap on the salary from which contributions are deducted?', kw:['municipal employee','salary cap'],
  a:'In veteran funds and collective agreements there are rigid salary caps for contributions. Salary above this cap is usually directed to supplementary provident funds, and Tal will make sure everything is managed correctly.' + GENERIC_CTA },
{ q:'What is Section 14 of the Severance Pay Law and why is it mandatory for every tech employee?', kw:['Section 14'],
  a:'This section ensures that the severance funds deposited each month belong to you under any circumstances (even if you resign voluntarily), and the employer does not need to retroactively complete severance for salary increases.' },
{ q:'I earn NIS 40,000 a month - why doesn\'t my regular pension fund cover my full salary?', kw:['high salary','pension contribution cap'],
  a:'Because there is a legal contribution cap for a comprehensive pension fund (currently about 20.5% of twice the average wage in the economy). The rest of the money is directed to a complementary pension or executive insurance, and Tal will handle the optimization.' + GENERIC_CTA },
{ q:'What is a complementary pension and when must a high earner use it?', kw:['complementary pension'],
  a:'This is a fund that receives contributions beyond the comprehensive pension cap. It does not include state-guaranteed designated bonds and its terms differ. Tal will make sure the management fees on it are not at the maximum.' + GENERIC_CTA },
{ q:'Should I take advantage of my high salary to deposit independently beyond what my employer contributes?', kw:['Section 47','depositing independently'],
  a:'Yes, there are tax benefits (Section 47) that allow employees too to deposit independently and receive tax refunds directly to their bank account. Tal will calculate the exact amount worth depositing.' + GENERIC_CTA },
{ q:'What is car value or salary imputation on a payslip and how does it affect my pension savings?', kw:['car value','salary imputation'],
  a:'These are non-pensionable components that increase the tax you pay net but don\'t generate pension savings for you. Tal will help you understand your true pensionable salary (base salary).' + GENERIC_CTA },
{ q:'I receive large annual bonuses and sales commissions - is my employer required to contribute to my pension on them?', kw:['bonuses','contribution obligation'],
  a:'By law, the contribution obligation applies to base salary only (excluding overtime, bonuses, and car allowances), unless otherwise stipulated in your personal contract. Tal will check how to protect these components.' + GENERIC_CTA },
{ q:'What happens to my severance funds in tech if the company closes down or goes through a merger?', kw:['merger','company closing'],
  a:'Your money is fully protected because it is registered in your name with the insurance and pension companies and does not sit in the company\'s bank account. In a merger, your rights continue as usual.' },
{ q:'Should a young tech employee choose executive insurance for the immunity of its terms?', kw:['young tech employee','executive insurance'],
  a:'In the vast majority of cases today - no. Management fees on new executive insurance policies are very expensive and offer no advantage over a modern, profitable pension fund. Tal will show you the numbers.' + GENERIC_CTA },
{ q:'How does the gross-net method of the study fund affect high earners?', kw:['gross-net method','high salary study fund'],
  a:'Above the recognized salary ceiling (currently about NIS 15,712), employer contributions to the study fund are considered positive net taxable income, and profits above the ceiling will be subject to capital gains tax. Tal will sort out the calculation for you.' + GENERIC_CTA },
{ q:'How do I write a financial will so my children don\'t fight over the money in my pension and insurance policies?', kw:['financial will','beneficiary designation'],
  a:'Money in provident funds, pension funds, and life insurance is paid according to the "beneficiary designation" form, not according to the will. Tal will make sure to update the exact beneficiaries with you in every fund to prevent legal complications.' + GENERIC_CTA },
{ q:'If I don\'t have a will, who receives the money sitting in my savings policy?', kw:['no will','savings policy heirs'],
  a:'If you have not designated specific beneficiaries in the policy, the money will go directly to your estate and be divided among the legal heirs according to a state inheritance order (or probate order).' },
{ q:'What happens to the money in a deceased person\'s study fund? Is it still tax-exempt for the heirs?', kw:['study fund deceased'],
  a:'Yes. The money in the study fund passes to the beneficiaries as a lump sum, and it retains the full exemption from capital gains tax accrued until the day of withdrawal by the beneficiaries.' },
{ q:'Can grandchildren withdraw money from their deceased grandfather\'s provident fund without paying tax?', kw:['grandchildren','grandfather\'s provident fund'],
  a:'If the grandfather passed away before age 75, the grandchildren (if designated as beneficiaries) will receive all the money fully exempt from capital gains tax. If he passed away after age 75, they will pay 15% nominal tax on the profits.' },
{ q:'What is smooth generational transfer through a savings policy?', kw:['smooth generational transfer'],
  a:'This is a mechanism that allows a policy to designate beneficiaries who will receive the money directly to their bank account within a few days of the death, without needing to wait months for an inheritance order from the registrar.' },
{ q:'I heard there\'s a hidden inheritance tax on financial assets in the US - does it affect me as an Israeli resident?', kw:['US estate tax','estate tax'],
  a:'Yes, if you hold American stocks directly (like Apple or Tesla) above a certain amount, US estate tax law may apply to the estate. Tal builds portfolios that safely avoid this risk.' + GENERIC_CTA },
{ q:'Can a couple open a joint savings policy with a longevity (second-to-die) clause?', kw:['longevity clause','joint policy'],
  a:'Yes, a joint savings policy allows you to specify that upon the death of one spouse, full ownership of the portfolio automatically transfers to the surviving spouse with no taxable event and without halting the portfolio.' + GENERIC_CTA },
{ q:'How does Tal help families with comprehensive family wealth planning?', kw:['family wealth planning'],
  a:'Tal looks at all the assets of parents and children (real estate, savings, companies) and builds a strategy that maximizes family tax exemptions, insurance protection, and proper transfer to the next generation.' + GENERIC_CTA },
{ q:'What happens to money a minor inherits from a pension or insurance policy? Who manages it for them?', kw:['minor inherits','legal guardian'],
  a:'The money is managed by their legal guardian (usually the other parent) or under supervised trusteeship, until the child turns 18 and can gain full access to the account. Tal helps arrange the process.' },
{ q:'What happens if I start receiving a pension while also redeeming accrued sick or vacation days from my employer?', kw:['vacation day redemption','sick day redemption'],
  a:'Redeeming vacation or sick days is considered ordinary employment income and is taxable. Combining such a redemption with a pension annuity requires precise tax planning by Tal to prevent a high tax liability.' + GENERIC_CTA },
{ q:'What is an increased survivors\' pension in the veteran funds and how does it protect a spouse?', kw:['increased survivors\' pension'],
  a:'Some veteran funds have tracks that allow increasing the percentage of the annuity the spouse will receive after the saver\'s death (up to 100% of the annuity), subject to an adjustment of the current annuity.' + GENERIC_CTA },
{ q:'Is there tax on the old-age allowance from National Insurance?', kw:['old-age allowance tax'],
  a:'No, the old-age allowance (senior citizen allowance) from National Insurance is fully exempt from income tax and is not counted when calculating your pension\'s tax brackets.' },
{ q:'What is the difference between the legal retirement age and the biological retirement age in financial planning?', kw:['biological age','legal retirement age'],
  a:'The legal age is the age at which the state grants benefits and exemptions (67 for men). The biological/personal age is the age at which your body or your will dictates that you stop working. Tal plans according to the age that suits you.' + GENERIC_CTA },
{ q:'What is pension capitalization for housing purposes, and can a retiree use it to pay off a mortgage?', kw:['pension capitalization for housing'],
  a:'In certain cases and under strict Tax Authority conditions, part of the pension can be withdrawn as a defined lump sum for paying off housing debts. Tal will examine the financial viability against the alternatives.' + GENERIC_CTA },
{ q:'How does deemed retirement affect the accrual of new severance seniority?', kw:['deemed retirement','new seniority'],
  a:'If you continue working for the same employer while receiving a pension, you begin a "new employment relationship" for severance purposes, and your previous seniority is closed out and settled for tax purposes. Tal will sort out the paperwork for you.' + GENERIC_CTA },
{ q:'What is the Tax Authority\'s "combination formula" and who does it give a headache to in retirement?', kw:['combination formula'],
  a:'This is the formula that links exempt severance pay you withdrew in the past to the exemption you\'ll receive on your retirement annuity. It is indeed very complex, but Tal cracks it for you and shows you the net bottom line.' + GENERIC_CTA },
{ q:'Can a retiree transfer their pension fund to another company after they are already receiving a monthly annuity?', kw:['transferring after starting annuity'],
  a:'No. From the moment you start receiving a monthly old-age annuity from a pension fund, the money is "locked" in that fund and cannot be transferred to another company. That\'s why it\'s critical to optimize with Tal before signing off on retirement.' + GENERIC_CTA },
{ q:'What is a conditional old-age allowance from National Insurance and when do you lose it?', kw:['conditional old-age allowance'],
  a:'This is the situation between the conditional retirement age (62-65 for women, 67 for men) and the absolute eligibility age (70 for everyone). During this period, if you have high income from work, National Insurance may delay or reduce your allowance.' + GENERIC_CTA },
{ q:'How does Tal build a liquidity anchor strategy for retirees so they don\'t have to sell stocks during downturns?', kw:['liquidity anchor'],
  a:'Tal makes sure that during retirement you have a reserve of cash or conservative assets (a liquidity anchor) sufficient to cover two to three years of living expenses, so that during a capital market crisis you don\'t touch your equity portfolio and give it time to recover.' + GENERIC_CTA },
{ q:'What happens if I filed Form 161d with the Tax Authority and, a year later, changed my mind and want to change the rights fixation?', kw:['changed my mind','rights fixation'],
  a:'Generally, the rights-fixation process becomes irreversible once 120 days have passed from its filing. That\'s why it\'s critically important to do the calculations professionally and accurately with Tal before submitting it to the assessing officer.' + GENERIC_CTA },
{ q:'What is a linked pension and how does it affect the taxation of couples in retirement?', kw:['linked pension','spouse income pension'],
  a:'This is a situation where the retirement annuity is affected by the spouse\'s income, or where there are transfers of tax rights between them. Tal examines both spouses as a single economic unit in order to maximize joint exemptions.' + GENERIC_CTA },
// TRANSLATOR NOTE: verify term "linked pension" for "פנסיית זיקה" - this is an uncertain rendering of a specific Israeli tax-law term describing pension/rights linkage between spouses; please confirm the precise English equivalent used elsewhere on the site, if any.
{ q:'Can a retiree who receives a monthly annuity open an investment provident fund and deposit money into it?', kw:['retiree','investment provident fund'],
  a:'Yes, absolutely. An investment provident fund is open to any age and any status. It\'s an excellent vehicle for retirees who want to keep liquid capital in the market with the option of easy transfer to their children.' + GENERIC_CTA },
{ q:'What is the difference between partial capitalization and full capitalization in old executive insurance policies?', kw:['partial capitalization','full capitalization'],
  a:'Partial capitalization leaves you with a reduced annuity and gives you a cash sum. Full capitalization converts the entire policy into a lump-sum benefit (permitted only under strict legal conditions). Tal will check what your specific policy allows.' + GENERIC_CTA },
{ q:'How does the Consumer Price Index affect the amount of the monthly pension I\'m already receiving?', kw:['Consumer Price Index','pension indexation'],
  a:'In most modern pension funds, the monthly annuity is linked to the Consumer Price Index and updated once or twice a year, so that your money keeps its purchasing power against rising prices in the economy.' },
{ q:'What is an "excess years grant" in a veteran pension fund and who is entitled to receive it in cash?', kw:['excess years grant'],
  a:'A saver in a veteran fund who has reached the maximum annuity percentage (70%) and continued contributing is entitled to a cash refund (excess years grant) on their retirement date. Tal will handle receiving the money for you.' + GENERIC_CTA },
{ q:'Is there a tax exemption on capital gains from selling a single residential apartment at retirement age?', kw:['betterment tax exemption','single apartment'],
  a:'Yes, the Real Estate Taxation Law grants an exemption from betterment tax on the sale of a single apartment (under the ceilings set by law), regardless of age, but Tal will incorporate this capital into your overall retirement cash-flow plan.' + GENERIC_CTA },
{ q:'What is Section 190 (not Amendment 190) and how is it related to employer pension contributions?', kw:['Section 190'],
  a:'This section regulates the contribution ceilings recognized for tax purposes for the employer. Tal makes sure your employer does not exceed these ceilings, which could otherwise create an unnecessary tax liability on your payslip.' + GENERIC_CTA },
{ q:'Is a retiree automatically entitled to discounts on property tax, transportation, and electricity upon reaching retirement age?', kw:['retiree discounts','senior citizen'],
  a:'Some discounts are given automatically via the "senior citizen" card, while others depend on your total income level. Tal will guide you on how to claim these rights.' + GENERIC_CTA },
{ q:'Is an exempt dealer (osek patur) required to contribute to a pension?', kw:['exempt dealer','pension contribution obligation'],
  a:'Under the Mandatory Pension Law for the self-employed, an exempt dealer is required to make a monthly or annual deposit into pension savings.' },
{ q:'What happens if an exempt dealer doesn\'t deposit into a pension?', kw:['not depositing','fines'],
  a:'The dealer is liable to fines and financial sanctions in accordance with National Insurance Institute and Tax Authority guidelines.' },
{ q:'Is a Ltd. company required to contribute pension for its controlling shareholder?', kw:['controlling shareholder','Ltd. company'],
  a:'Not as an ordinary self-employed person, but it is required to contribute as an employer for the company\'s employees, and must also maintain social benefits for the controlling shareholder employed there as a salaried worker.' + GENERIC_CTA },
{ q:'How is the minimum pension contribution amount calculated for an exempt dealer?', kw:['minimum amount','exempt dealer'],
  a:'The amount is set as graduated percentages of taxable income, up to a ceiling of half the average wage in the economy, and beyond that - additional percentages apply.' + GENERIC_CTA },
{ q:'Is a pension contribution recognized as a deductible business expense for an exempt dealer?', kw:['recognized expense'],
  a:'Yes, part of the contributions to pension savings, as well as payments for loss-of-working-capacity insurance, qualify for a deduction and credit on income tax.' },
{ q:'What is the pension advantage of establishing a Ltd. company compared to being an exempt dealer?', kw:['Ltd. company advantage'],
  a:'A Ltd. company allows for higher pension contributions that are recognized as an expense, such as a study fund for managers and executive insurance policies that include a severance component.' + GENERIC_CTA },
{ q:'What percentage can an exempt dealer deposit into a pension and receive tax benefits?', kw:['contribution percentage exempt dealer'],
  a:'The total contributions eligible for deduction and credit to a self-employed pension fund currently stand at about 16.5% of qualifying income, up to an annual income ceiling.' + GENERIC_CTA },
{ q:'What is the difference in taxation of pension withdrawals for an exempt dealer versus a company?', kw:['withdrawal taxation','exempt dealer vs. company'],
  a:'Pension funds are taxed the same way for both when withdrawn as an annuity under the Income Tax Ordinance, but the withdrawal planning and the sources from which the funds are drawn differ.' + GENERIC_CTA },
{ q:'Is it better for an exempt dealer to pay pension monthly or annually?', kw:['monthly or annual deposit'],
  a:'You can make ongoing monthly deposits or a single annual deposit. Monthly deposits help with cash-flow management and ensure continuity of insurance coverage.' + GENERIC_CTA },
{ q:'How is income calculated to determine the pension amount for an exempt dealer?', kw:['income for pension calculation'],
  a:'Income is calculated based on the business\'s net profit, as it appears in the annual Tax Authority assessment.' },
{ q:'Are a controlling shareholder\'s pension funds in a Ltd. company protected in the event of bankruptcy?', kw:['bankruptcy controlling shareholder'],
  a:'Yes, the controlling shareholder\'s provident and pension funds are protected against creditors, except for certain exceptions in the law.' },
{ q:'Who pays the management fees on an exempt dealer\'s pension?', kw:['management fees exempt dealer'],
  a:'The saver themselves pays the management fees, directly out of the savings accumulated in the fund.' },
{ q:'Can an exempt dealer who opens a Ltd. company transfer their pension?', kw:['transferring pension to a company'],
  a:'Yes, you can preserve the seniority and rights in the pension fund and simply change the paying entity\'s status from the individual dealer to the company.' + GENERIC_CTA },
{ q:'How does the retirement grant work when moving from an exempt dealer to a company?', kw:['retirement grant','exempt dealer to company'],
  a:'In a Ltd. company, tax-exempt severance funds can be designated upon retirement, whereas an exempt dealer has no "employer" contributing severance unless they deposited it themselves under self-employed-as-employee status.' + GENERIC_CTA },
{ q:'Can a controlling shareholder withdraw severance funds upon retirement?', kw:['controlling shareholder severance withdrawal'],
  a:'Yes, they can withdraw the severance funds deposited on their behalf up to the exemption ceiling set by law, or leave them designated for annuity purposes.' + GENERIC_CTA },
{ q:'How is the tax deduction ceiling calculated on pension contributions for the self-employed?', kw:['deduction ceiling self-employed'],
  a:'The deduction and credit are calculated as percentages of qualifying income, where qualifying income itself is capped at an annual ceiling set by law.' },
{ q:'Why do businesses move from being an exempt dealer to a Ltd. company from a pension standpoint?', kw:['switching to a Ltd. company'],
  a:'Because a company can deposit larger amounts into pension savings, which are recognized as an expense and reduce the liability for corporate tax and the owner\'s marginal income tax.' + GENERIC_CTA },
{ q:'Can a Ltd. company insure itself against the controlling shareholder\'s disability?', kw:['disability insurance controlling shareholder'],
  a:'The company can purchase a loss-of-working-capacity policy that pays it compensation recognized as an expense.' + GENERIC_CTA },
{ q:'Can an exempt dealer set aside severance pay for their own pension?', kw:['severance pay exempt dealer'],
  a:'A self-employed person can deposit into a severance component, but will not receive the same exemptions available to a salaried employee at a Ltd. company.' },
{ q:'What annuity insurance is recommended for an exempt dealer?', kw:['recommended annuity insurance'],
  a:'A comprehensive pension fund (or executive insurance) combining savings for retirement age, survivors coverage, and disability coverage.' + GENERIC_CTA },
{ q:'How does an exempt dealer handle the pension obligation in years when the business operates at a loss?', kw:['loss years'],
  a:'A self-employed person is not required to deposit into a pension in years with no taxable income, or when they are already insured through another primary workplace as a salaried employee.' },
{ q:'What happens to accumulated benefit funds for an exempt dealer upon leaving the profession?', kw:['benefit funds leaving profession'],
  a:'The funds remain in the fund and can be withdrawn upon retirement, or in certain cases transferred to other vehicles, sometimes subject to tax.' },
{ q:'Is a business partnership required to make pension contributions?', kw:['business partnership'],
  a:'Yes, every partner in a venture is required to make pension contributions as a self-employed person, similar to an exempt dealer.' },
{ q:'What is the "self-employed with employee status" procedure for company shareholders?', kw:['self-employed with employee status'],
  a:'A controlling shareholder employed by the company sometimes contributes part of their pension deposits as a regular salaried employee of the company they own.' },
{ q:'How much corporate tax does a Ltd. company pay compared to the income tax an exempt dealer pays?', kw:['corporate tax','income tax exempt dealer'],
  a:'A Ltd. company pays a fixed corporate tax rate of 23%, while an exempt dealer pays marginal income tax that climbs up to 50% depending on income level.' },
{ q:'Is it worthwhile for every exempt dealer to become a Ltd. company to save tax on their pension?', kw:['worth becoming a Ltd. company'],
  a:'Not necessarily. The transition requires higher bookkeeping expenses, and is generally worthwhile only above a sufficiently high income and profit threshold.' + GENERIC_CTA },
{ q:'What is the difference between an investment provident fund and a pension fund for an exempt dealer?', kw:['investment provident fund','pension fund exempt dealer'],
  a:'An investment provident fund is not intended for a retirement annuity and provides full liquidity, whereas a pension fund pays a fixed annuity and is intended for retirement age.' },
{ q:'Is a Ltd. company required to pay National Insurance for its controlling shareholder?', kw:['National Insurance controlling shareholder'],
  a:'Yes, the company must pay National Insurance contributions as an employer for shareholders employed within it.' },
{ q:'How do National Insurance payments affect an exempt dealer\'s pension?', kw:['National Insurance payments'],
  a:'Paying National Insurance contributions on time grants the dealer future rights to an old-age allowance from the state.' },
{ q:'Is an executive insurance policy preferable to a pension fund for an exempt dealer?', kw:['executive insurance vs. pension'],
  a:'As a general rule, a comprehensive pension fund offers a guaranteed annuity conversion rate and designated bonds. Executive insurance usually includes higher insurance components and more flexible, negotiable management-fee terms.' + GENERIC_CTA },
{ q:'Can I get an early pension if I was an exempt dealer?', kw:['early pension exempt dealer'],
  a:'Yes, pension funds can be withdrawn starting at age 60, subject to the fund\'s regulations and the insurance company\'s approval.' + GENERIC_CTA },
{ q:'How is an exempt dealer protected against a decline in income approaching retirement?', kw:['decline in income'],
  a:'They should carry out orderly retirement planning, accumulate additional savings such as investment provident funds, and make sure to maximize contributions to the pension fund.' + GENERIC_CTA },
{ q:'Can a controlling shareholder withdraw dividends as part of their pension savings?', kw:['dividends pension savings'],
  a:'No, withdrawing dividends is a withdrawal of the company\'s profits taxed as dividend tax, and is not considered a pension contribution eligible for tax benefits.' + GENERIC_CTA },
{ q:'What is the qualifying income ceiling for a tax credit for an exempt dealer?', kw:['qualifying income ceiling'],
  a:'This is a ceiling updated every year by the Tax Authority. Tal checks the updated ceiling against your annual assessment.' + GENERIC_CTA },
{ q:'Should an exempt dealer pay the maximum into a pension or also spread savings into an investment provident fund?', kw:['spreading into a provident fund'],
  a:'Spreading savings across vehicles depends on your personal situation, but contributing to a pension fund guarantees protection for survivors and disability in addition to the old-age annuity.' + GENERIC_CTA },
{ q:'Is a Ltd. company required to pay severance to the controlling shareholder when the business closes?', kw:['severance pay business closing'],
  a:'Yes, if the controlling shareholder is dismissed and stops working, in accordance with Tax Authority rules regarding tax-exempt severance withdrawal.' + GENERIC_CTA },
{ q:'Can I open a pension for an exempt dealer above age 60?', kw:['pension above age 60'],
  a:'Yes, you can continue depositing into pension savings and enjoy tax benefits even at an advanced age.' },
{ q:'What is "qualifying income" in the pension context?', kw:['qualifying income'],
  a:'Qualifying income is the annual income, before deductions and exemptions, on which the tax benefits for pension contributions are calculated.' },
{ q:'What is the difference between a deduction and a credit in pension taxation for the self-employed?', kw:['deduction vs. credit'],
  a:'A deduction reduces the taxable income on which tax is calculated, while a credit is a direct reduction of the tax amount owed.' },
{ q:'Does paying into a pension reduce National Insurance payments for an exempt dealer?', kw:['reducing National Insurance'],
  a:'No, National Insurance payments are owed regardless of the amounts contributed to the pension fund.' },
{ q:'What are Israel\'s tax brackets and how do they work?', kw:['tax brackets','marginal tax'],
  a:'Israel\'s tax system is progressive - every additional shekel earned is taxed according to the bracket it falls into only, not all income at the highest bracket you\'ve reached.' },
{ q:'What is the additional tax (surtax) and who is liable for it?', kw:['additional tax','surtax'],
  a:'An additional tax imposed on especially high annual income, above a ceiling that is updated every year. Tal will check with you whether you cross the ceiling and how to plan for it properly.' + GENERIC_CTA },
{ q:'What are tax credit points?', kw:['tax credit points'],
  a:'A fixed amount deducted directly from the monthly tax you owe, according to your personal circumstances - for example children, residence in a certain area, or being a new immigrant.' },
{ q:'How do tax credit points affect my net salary?', kw:['tax credit points','net salary'],
  a:'The more tax credit points you have, the less tax is deducted from each payslip, and the higher the net salary that reaches your account.' },
{ q:'What is tax coordination and who needs it?', kw:['tax coordination'],
  a:'A document that divides among several workplaces how much tax to withhold from each one, so that you don\'t have too much tax withheld at source if you work at more than one workplace.' + GENERIC_CTA },
{ q:'What is the difference between tax withheld at source and the actual tax owed?', kw:['tax withheld at source'],
  a:'Tax withheld at source is essentially an advance payment toward your annual tax liability, and at the end of the year a reconciliation is made against the actual assessment - which can result in a refund or an additional payment.' },
{ q:'Is a salaried employee required to file an annual report with the Tax Authority?', kw:['annual report employee'],
  a:'In most cases, an employee with a single workplace is not required to file an annual report, but it\'s worth checking eligibility for a tax refund even when there is no formal obligation.' + GENERIC_CTA },
{ q:'What is a capital declaration and when is it required of me?', kw:['capital declaration'],
  a:'A report detailing all your assets and liabilities at a given date, which the Tax Authority may require in order to verify that your reported income matches your rate of capital growth.' },
{ q:'How is "Israeli resident for tax purposes" status determined?', kw:['tax resident status'],
  a:'The determination is based mainly on the number of days you spent in Israel during the tax year and the two preceding years, not merely on citizenship or a registered address.' },
{ q:'What is purchase tax when buying an apartment?', kw:['purchase tax'],
  a:'A tax calculated as a graduated percentage of the value of the apartment you are buying, with buyers of a single apartment benefiting from favorable tax brackets compared to buyers of an additional apartment.' + GENERIC_CTA },
{ q:'What is the difference between betterment tax and purchase tax?', kw:['betterment tax','purchase tax'],
  a:'Betterment tax is paid by the seller, on the profit generated from selling the property. Purchase tax is paid by the buyer, at the time of making the purchase itself.' },
        { q:'How do I get a tax credit for a donation to a nonprofit?', kw:['tax credit donation','charitable donation credit'],
          a:'A donation to a recognized public institution entitles you to a direct tax credit at a fixed rate of the donation amount, subject to an annual cap and a minimum donation amount.' },
        { q:'How is dividend income I withdraw from my company taxed?', kw:['dividend taxation','company dividend'],
          a:'Dividend withdrawals are taxed at a fixed dividend tax rate, in addition to the corporate tax already paid on the profit at the company level - so in practice there is a double tax layer worth planning for in advance.' + GENERIC_CTA },
        { q:'How can I avoid double taxation on investments I hold abroad?', kw:['double taxation','foreign investments tax'],
          a:'Israel has signed double taxation treaties with many countries, allowing a credit in Israel for tax already paid abroad on the same income.' + GENERIC_CTA },
        { q:'What is a tax treaty for the prevention of double taxation?', kw:['tax treaty'],
          a:'An agreement between two countries determining which of them may tax a certain type of income, so that the same income is not fully taxed twice in both countries.' },
        { q:'How do I file an objection to a tax assessment I received?', kw:['tax objection','tax assessment'],
          a:'You can file a written objection with the tax assessor within the period set by law, and attach documents supporting your position. It is recommended to do this with professional guidance.' + GENERIC_CTA },
        { q:'What happens if I pay tax late?', kw:['late tax payment','interest and linkage'],
          a:'Interest and linkage differentials are added to the debt each month, so the real cost of the delay grows over time rather than staying fixed.' },
        { q:'What is the difference between a deduction and a tax exemption?', kw:['deduction vs exemption'],
          a:'A deduction reduces the taxable income on which tax is calculated. An exemption means certain income or profit is not taxed at all.' },
        { q:'What are income tax advances for the self-employed and how are they calculated?', kw:['self-employed tax advances'],
          a:'Payments toward the expected annual tax, calculated as a percentage of your monthly turnover and transferred to the Tax Authority on an ongoing basis during the year.' },
        { q:'What happens if a self-employed person does not pay tax advances on time?', kw:['missed tax advance payment'],
          a:'Interest and linkage differentials accrue on the unpaid amount, and the Tax Authority may increase the rate of the next advance payments set for the business.' + GENERIC_CTA },
        { q:'What is a withholding file and why does a business need one?', kw:['withholding file'],
          a:'A file opened with the Tax Authority for a business that employs workers or pays suppliers, through which the tax withheld at source from payments is reported and transferred.' },
        { q:'How is income from renting a residential apartment taxed?', kw:['rental income tax','residential apartment'],
          a:'There are several taxation tracks to choose from - partial or full exemption up to a certain ceiling, a fixed reduced tax track, or taxation according to the regular tax brackets after deducting expenses.' + GENERIC_CTA },
        { q:'What is the tax exemption on residential rental income?', kw:['rental income exemption'],
          a:'Up to a certain monthly income ceiling, residential rental income in Israel is fully or partially exempt from income tax.' },
        { q:'How can I check how much tax I actually paid this year?', kw:['how much tax did I pay'],
          a:'You can check this through your pay slips, the annual Form 106 from your employer, or your personal area on the Tax Authority website.' },
        { q:'What is the difference between a tax advisor and an accountant?', kw:['tax advisor vs accountant'],
          a:'A tax advisor specializes in preparing reports and ongoing taxation, while a certified public accountant is also authorized to prepare and sign audited financial statements and conduct audits.' },
        { q:'Can I amend a tax return after it has already been filed?', kw:['amend tax return'],
          a:'Yes, you can file an amended return within the period set by law, if an error or new information not included in the original return is discovered.' },
        { q:'How is a lump-sum withdrawal from a provident fund (not as an annuity) taxed?', kw:['provident fund lump-sum withdrawal tax'],
          a:'A capital withdrawal that does not meet the legal exemption conditions is taxed at your marginal income tax rate, and sometimes tax is also withheld at source already at the time of the withdrawal itself.' + GENERIC_CTA },
        { q:'How does additional income from a second job affect my overall tax rate?', kw:['second job','additional tax'],
          a:'Income from the second job is added to your total income and enters the higher tax brackets you have already reached in your first job, so it is important to arrange tax coordination between the employers.' + GENERIC_CTA },
        { q:'What is the tax credit for paying life insurance premiums?', kw:['tax credit life insurance'],
          a:'In certain cases, paying a premium for life insurance or loss of working capacity insurance entitles you to a tax credit or deduction, subject to the ceilings and conditions set by law.' + GENERIC_CTA },
        { q:'What is value added tax (VAT) and why does an exempt dealer not collect it?', kw:['VAT','exempt dealer'],
          a:'VAT is an indirect tax collected on transactions. An exempt dealer ("osek patur") is exempt from collecting and reporting VAT, subject to an annual turnover ceiling - beyond this ceiling they become a licensed dealer ("osek murshe") who is liable for VAT.' },
        { q:'How is a transfer of funds between pension funds actually carried out in practice?', kw:['pension fund transfer','transfer steps'],
          a:'You approach the new fund with a transfer request form, and it handles the transfer of funds with the old fund - the process does not require you to touch the money yourself.' + GENERIC_CTA },
        { q:'How long does a transfer of funds between pension funds take?', kw:['how long pension transfer'],
          a:'It usually takes a few weeks to about two months, depending on the workload and how properly the submitted forms were filled out.' },
        { q:'What is a qualifying period when moving to a new pension fund?', kw:['pension fund qualifying period'],
          a:'A period of time during which the new insurance coverages (such as disability) are not yet full in the new fund, unless insurance continuity is maintained from the previous fund.' + GENERIC_CTA },
        { q:'What happens to my seniority when I transfer funds between pension funds?', kw:['seniority in transfer'],
          a:'Insurance seniority is usually preserved if the transfer is done continuously and without a break in deposits, but it is worth confirming this with the receiving fund before making the move.' + GENERIC_CTA },
        { q:'Who do I turn to if my pension fund is not handling my request properly?', kw:['complaint about pension fund'],
          a:'You can file a complaint directly with the Commissioner of Capital Market, Insurance and Savings at the Ministry of Finance, who supervises the conduct of insurance companies and pension funds.' },
        { q:'What is the Capital Market Commissioner and how does it protect me as a saver?', kw:['capital market commissioner'],
          a:'The authority that supervises insurance companies, pension funds and provident funds in Israel, and enforces fairness rules toward savers.' },
        { q:'What happens to the amount of my monthly pension if I delay when I start receiving it?', kw:['delaying pension','deferring annuity'],
          a:'As a rule, the later you delay the start of receiving the pension, the higher the monthly pension you will begin to receive - because the same capital is divided over fewer years of expected life.' + GENERIC_CTA },
        { q:'Is it worth delaying my pension payments if I am still working?', kw:['delay pension while working'],
          a:'It depends on your personal situation - sometimes it is better to delay in order to increase the future pension, and sometimes it is actually worth starting to receive it. Tal will examine this against your full income picture.' + GENERIC_CTA },
        { q:'What is the difference in the legal retirement age between men and women in Israel?', kw:['retirement age men women'],
          a:'There is a gap between the legal retirement age for men and that for women in Israel, and the retirement age for women is in a process of gradual increase - it is worth checking with Tal exactly what age applies to you.' + GENERIC_CTA },
        { q:'Can I retire early from a pension fund before the legal retirement age?', kw:['early retirement pension age'],
          a:'Yes, in most funds you can start receiving a pension a few years before the legal retirement age, but the monthly pension will be lower according to the conversion rate at the earlier age.' + GENERIC_CTA },
        { q:'What is the difference between a guaranteed annuity track and a non-guaranteed annuity track?', kw:['guaranteed annuity'],
          a:'A guaranteed annuity ensures payment for a minimum period even if the insured passes away early (to the heirs), while a regular annuity stops completely upon death if there are no eligible survivors.' + GENERIC_CTA },
        { q:'Why has the conversion rate for an annuity become more important in recent years?', kw:['conversion rate importance'],
          a:'The conversion rate determines how much monthly pension you will receive in exchange for each shekel accumulated - and as life expectancy rises, this rate changes, directly affecting your final pension amount.' + GENERIC_CTA },
        { q:'What do I do if my employer is not actually depositing into my pension even though required by law?', kw:['employer not depositing pension'],
          a:'You can first approach the employer with a request to settle the arrears, and if there is no response - file a complaint with the Capital Market Commissioner or take legal action to collect the funds owed to you.' + GENERIC_CTA },
        { q:'How do I identify that my employer is not depositing properly into my pension?', kw:['identify missing pension deposits'],
          a:'Compare the amounts appearing on your pay slip under "employer contributions" with the periodic reports that come directly from the pension fund - if there is a gap, it is worth checking immediately.' },
        { q:'What are designated bonds ("Agach Meyuadot") in a pension fund investment portfolio?', kw:['designated bonds'],
          a:'Dedicated government bonds issued only to veteran pension funds, with a relatively high guaranteed interest rate compared to the market, which reduces the risk on part of your savings.' },
        { q:'Can a pension fund go bankrupt and cause me to lose my money?', kw:['pension fund bankruptcy'],
          a:'The funds in a pension fund are managed separately from the equity of the managing company and are closely supervised, so the collapse of the managing company is not supposed to harm the savers\' own money.' },
        { q:'Who supervises pension funds in Israel?', kw:['pension fund supervision'],
          a:'The Capital Market, Insurance and Savings Authority at the Ministry of Finance, which sets rules and regularly checks the funds\' stability and proper conduct.' },
        { q:'What is the difference between management fees on deposits and management fees on accumulation?', kw:['management fees on deposits','management fees on accumulation'],
          a:'Management fees on deposits are charged on every monthly deposit that comes in, and management fees on accumulation are charged annually on the entire amount already accumulated in the fund - the combination of both types determines your total cost.' + GENERIC_CTA },
        { q:'How do I know if the management fees I am paying in my pension fund are too high?', kw:['management fees too high'],
          a:'Compare your rate against the market average and against what can be achieved through negotiation, taking into account the size of your accumulation and your seniority in the fund.' + GENERIC_CTA },
        { q:'Can I negotiate management fees with my pension fund?', kw:['negotiate management fees'],
          a:'Yes, management fees are subject to negotiation within the ceilings set by law, and Tal manages this negotiation for you with the institutional bodies.' + GENERIC_CTA },
        { q:'What is an age-dependent investment track in a pension fund?', kw:['age-dependent investment track'],
          a:'A default track that automatically moves your money to a lower risk level as you approach retirement age, in order to protect the savings from market volatility.' },
        { q:'Why does the pension fund automatically move me to a more conservative track with age?', kw:['automatic track transition'],
          a:'To reduce the risk that a sharp market decline right around the time of retirement will significantly harm the savings you have accumulated over the years.' },
        { q:'Can I opt out of the age-dependent investment track and stay in an equity track?', kw:['opt out of age-dependent track'],
          a:'Yes, you can choose a different investment track according to your preference even at an older age, but this is a decision worth making with professional guidance that takes your overall financial situation into account.' + GENERIC_CTA },
        { q:'What happens to my pension funds if I work abroad for several years?', kw:['pension while working abroad'],
          a:'The funds already accumulated remain yours and are managed as usual, but if there is no Israeli employer contributing on your behalf, the ongoing deposits stop until you return or until you deposit independently.' + GENERIC_CTA },
        { q:'Do I need to keep depositing into my Israeli pension when working abroad?', kw:['depositing from abroad'],
          a:'It is not mandatory, but it is recommended in order to maintain insurance continuity and not lose disability and survivor coverage - independent deposits can be arranged even by someone working abroad.' + GENERIC_CTA },
        { q:'What is voluntary National Insurance for an Israeli resident working abroad?', kw:['voluntary national insurance'],
          a:'A track that allows Israelis staying abroad to continue paying National Insurance contributions in order to preserve future rights, such as old-age benefits and a medical insurance record.' },
        { q:'What is the difference between early retirement and voluntary retirement (initiated retirement)?', kw:['voluntary retirement'],
          a:'Early retirement is usually an early exit to a pension for personal reasons. Voluntary retirement is usually an arrangement with the employer as part of workforce reductions, generally including improved retirement terms.' + GENERIC_CTA },
        { q:'What is a voluntary retirement grant and how is it taxed?', kw:['voluntary retirement grant'],
          a:'A one-time payment the employer grants as part of a retirement agreement, part of which may be exempt from tax up to the ceiling set by law, with the remainder taxed according to the tax brackets.' + GENERIC_CTA },
        { q:'How do you choose between a monthly annuity track and a lump-sum withdrawal at retirement?', kw:['annuity or lump sum at retirement'],
          a:'The decision depends on your age, health condition, other income and family needs - this is an irreversible decision that requires comprehensive analysis before signing.' + GENERIC_CTA },
        { q:'Can I combine part annuity and part lump sum in the same pension fund retirement?', kw:['combining annuity and lump sum'],
          a:'Yes, subject to the fund\'s bylaws and the tax exemption conditions, it is sometimes possible to withdraw part of the accumulation as a lump sum and the remainder as a monthly annuity.' + GENERIC_CTA },
        { q:'What happens to my pension funds if I switch from being an employee to being self-employed after years as a salaried worker?', kw:['switching from employee to self-employed'],
          a:'The funds accumulated as an employee remain yours unchanged, and from the moment of the switch you are required to keep depositing into a pension as a self-employed person under the Mandatory Pension Law.' + GENERIC_CTA },
        { q:'How does high inflation affect the value of my monthly pension in retirement?', kw:['inflation and pension'],
          a:'In most pension funds the pension is linked to the index and updated accordingly, so it is supposed to preserve its purchasing power even during periods of high inflation.' },
        { q:'What is demographic interest and how does it affect the pension in veteran funds?', kw:['demographic interest'],
          a:'A mechanism in veteran funds that balances the fund\'s income and expenses based on the life expectancy of all members, and may affect the actual amount of pension paid.' + GENERIC_CTA },
        { q:'What do I do if I made a mistake and transferred my pension funds to the wrong place?', kw:['mistake in fund transfer'],
          a:'In most cases it is possible to correct this and transfer again to the appropriate product, but it is worth checking first the effects on seniority, conversion rates and old terms before making an additional correction.' + GENERIC_CTA },
        { q:'How can I check that all the deposits my employer reported actually reached the pension fund?', kw:['verify deposits reached fund'],
          a:'Compare your pay slips with the periodic and annual reports the pension fund sends you directly, and make sure every amount deducted was indeed recorded in your accumulation.' + GENERIC_CTA },
        { q:'What is the difference between an exempt dealer and a licensed dealer?', kw:['exempt dealer vs licensed dealer'],
          a:'An exempt dealer ("osek patur") does not collect or report VAT and is limited to an annual turnover ceiling. A licensed dealer ("osek murshe") collects VAT from customers and reports it to the Tax Authority periodically.' },
        { q:'How does a licensed dealer issue a tax invoice properly?', kw:['tax invoice'],
          a:'The invoice must include the business details, dealer number, description of the service, the amount before VAT, the VAT amount and the total amount, in accordance with the Tax Authority\'s requirements.' },
        { q:'How often does a licensed dealer report VAT?', kw:['periodic VAT reporting'],
          a:'According to business turnover - small businesses report once every two months, and larger businesses report once a month.' },
        { q:'What is input tax and how is it offset?', kw:['input tax'],
          a:'The VAT the business paid on business purchases and expenses, which can be offset against the VAT the business collected from its customers in the periodic report.' },
        { q:'What happens if a licensed dealer exceeds the turnover ceiling and does not report on time?', kw:['exceeding turnover ceiling'],
          a:'They may be fined by the Tax Authority and required to pay retroactive VAT on transactions that were mistakenly reported as tax-exempt.' + GENERIC_CTA },
        { q:'What is a depreciation deduction and how does it reduce tax on an investment property?', kw:['depreciation deduction'],
          a:'Gradual recognition of the decline in value of an asset over time, which is allowed as an expense for tax purposes and reduces the taxable income from it each year.' },
        { q:'Does betterment tax also apply to the sale of a second residential apartment?', kw:['betterment tax second apartment'],
          a:'Yes, the sale of an additional apartment (that is not your only apartment) is subject to betterment tax on the real profit, without the exemption that applies to a single apartment.' + GENERIC_CTA },
        { q:'Can renovation expenses be deducted from betterment tax when selling an apartment?', kw:['deducting renovation expenses from betterment tax'],
          a:'Yes, documented improvement expenses (such as a significant renovation or a building addition) can be deducted from the profit subject to betterment tax, subject to presenting receipts and invoices.' + GENERIC_CTA },
        { q:'What are corporate tax advances and how are they calculated?', kw:['corporate tax advances'],
          a:'Monthly or bi-monthly payments toward the company\'s expected annual corporate tax, calculated as a percentage of the company\'s business turnover.' },
        { q:'What expenses are recognized for a limited company for tax purposes?', kw:['recognized expenses for a company'],
          a:'Expenses incurred for the purpose of generating income - such as employee salaries, office rent, equipment, and business travel - are recognized as deductible from the company\'s taxable income.' },
        { q:'What is the value of use of a company car and how is it taxed?', kw:['company car value of use'],
          a:'A fixed amount added to the taxable income of an employee who received a company car from the employer, reflecting the financial benefit of private use of the company vehicle.' + GENERIC_CTA },
        { q:'Should a self-employed person buy a car under the business\'s name or their personal name?', kw:['car under business name'],
          a:'A car under the business\'s name allows deduction of maintenance and depreciation expenses, but requires reporting a value of use if there is private use. The decision depends on the actual scope of business use.' + GENERIC_CTA },
        { q:'How are restricted stock units (RSUs) taxed at vesting?', kw:['RSU taxation vesting'],
          a:'At the vesting date a tax event is created on the value of the shares that vested, with Section 102 of the Income Tax Ordinance setting the beneficial tax track via a trustee.' + GENERIC_CTA },
        { q:'What is the difference between the capital track and the income track in taxing employee options?', kw:['capital track vs income track'],
          a:'In the capital track, most of the profit is taxed as capital gains at a lower rate. In the income track, the profit is taxed as regular employment income, at a higher marginal tax rate.' + GENERIC_CTA },
        { q:'What is a trustee in the Section 102 taxation track?', kw:['trustee section 102'],
          a:'An external party that holds the shares or options during the lock-up period required by law, as a condition for eligibility for the beneficial tax track.' },
        { q:'How is profit from digital currencies (crypto) taxed in Israel?', kw:['crypto taxation'],
          a:'The Tax Authority treats digital currencies as an asset, so selling them at a profit is subject to capital gains tax, similar to selling stocks or securities.' + GENERIC_CTA },
        { q:'Do I need to report holding digital currencies even if I have not sold them?', kw:['crypto reporting'],
          a:'The reporting obligation to the tax authorities applies at the time the profit is realized (sale or conversion), not merely on holding, but it is recommended to document the purchase dates and costs in advance.' + GENERIC_CTA },
        { q:'How are National Insurance contributions calculated for a self-employed person?', kw:['national insurance self-employed'],
          a:'Calculated as graduated percentages of the self-employed person\'s taxable income, similar to the income tax bracket structure, up to a maximum income ceiling for payment.' },
        { q:'Why do employees and self-employed people pay different percentages for National Insurance?', kw:['different national insurance percentages'],
          a:'The rate for the self-employed also includes the employer\'s share, which for an employee is paid separately by the employer, so the total payment rate for a self-employed person differs from that of an employee.' },
        { q:'What is health tax and why is it separate from National Insurance contributions?', kw:['health tax definition'],
          a:'An additional mandatory payment alongside National Insurance contributions, which funds your public healthcare basket under the National Health Insurance Law.' },
        { q:'How do alimony payments affect my tax liability?', kw:['alimony tax'],
          a:'Alimony payments between spouses are usually not recognized as an expense for the payer and are not taxed for the recipient, but this may vary depending on the wording of the agreement.' + GENERIC_CTA },
        { q:'How are financial assets divided for tax purposes in a divorce?', kw:['asset division divorce tax'],
          a:'Transferring assets between spouses as part of a recognized divorce agreement is usually tax-exempt, but the future realization of those assets (such as selling securities) may create a tax liability.' + GENERIC_CTA },
        { q:'What is the FATCA agreement and how does it affect Israelis with American citizenship?', kw:['FATCA'],
          a:'An agreement between Israel and the US for mutual reporting on financial accounts, which requires American citizens in Israel to report their assets to the American tax authorities as well.' + GENERIC_CTA },
        { q:'Does an American citizen living in Israel need to file a tax return in the US as well?', kw:['US tax return'],
          a:'Yes, American citizens are required to file an annual tax return with US authorities regardless of where they live, even if all their income is generated in Israel.' + GENERIC_CTA },
        { q:'What is CRS and how is it related to bank accounts abroad?', kw:['CRS'],
          a:'An international mechanism for automatically exchanging financial information between countries, which allows the Israeli Tax Authority to receive reports on accounts held by Israeli residents in foreign banks.' },
        { q:'How does tax coordination affect a working student with two jobs?', kw:['tax coordination student'],
          a:'Without tax coordination, each employer withholds tax assuming this is your only income, which can result in excess tax withholding that is only refunded at the end of the year.' + GENERIC_CTA },
        { q:'Can a working child or spouse "transfer" tax credit points to the other spouse?', kw:['transferring tax credit points'],
          a:'In most situations, personal tax credit points cannot be transferred between spouses, but there are special arrangements for certain family situations worth checking with Tal.' + GENERIC_CTA },
        { q:'What is the tax-exempt income ceiling for people aged 60 and above?', kw:['income exemption age 60'],
          a:'There are tax benefits and dedicated exemption ceilings for senior citizens on certain types of income, which change from time to time in legislation.' + GENERIC_CTA },
        { q:'What is offsetting capital losses between tax years?', kw:['offsetting capital losses'],
          a:'A loss from selling one security can be offset against a profit from selling another security in the same year, and can even be carried forward to future years if not fully utilized.' },
        { q:'How do I report profit or loss from independent stock market trading?', kw:['reporting independent trading'],
          a:'A private investor who trades independently (not through a managed product) may be required to file an annual return and pay tax advances themselves, depending on the scope of activity.' + GENERIC_CTA },
        { q:'What is passive income versus earned income for tax purposes?', kw:['passive income vs earned income'],
          a:'Earned income (such as wages) entitles you to certain tax benefits that do not apply to passive income (such as rent or interest), which is usually taxed separately.' },
        { q:'How is interest received from a bank deposit taxed?', kw:['bank deposit interest taxation'],
          a:'Interest from a bank deposit is taxed at a fixed capital gains tax rate, which is usually withheld directly by the bank at source.' },
        { q:'What is the tax on real versus nominal capital gains?', kw:['real vs nominal capital gains'],
          a:'Tax on real profit is calculated after deducting the effect of inflation on the profit, while tax on nominal profit is calculated on the entire increase in value without deducting inflation - making it more expensive for the investor.' },
        { q:'Which savings products are completely exempt from capital gains tax?', kw:['full exemption capital gains'],
          a:'A study fund (after 6 years), an investment provident fund withdrawn as an annuity, and pension funds withdrawn as an annuity - all of these enjoy a full or significant exemption from capital gains tax.' + GENERIC_CTA },
        { q:'What is the difference between income tax and corporate tax in terms of tax rates?', kw:['income tax vs corporate tax'],
          a:'Income tax on an individual is progressive and rises as income grows. Corporate tax is a fixed uniform rate applied to the company\'s profits regardless of their size.' },
        { q:'How is it determined whether income from renting out a property is considered business or passive income?', kw:['rental business or passive'],
          a:'They examine the scope of activity - the number of properties, the frequency of rentals and the active involvement of the property owner in managing it - to determine whether it constitutes a business in every sense.' },
        { q:'What is tax withholding at source on a payment to a supplier?', kw:['withholding at source for supplier'],
          a:'A business paying a certain supplier is sometimes required to withhold a certain percentage of the payment and transfer it directly to the Tax Authority toward the supplier\'s future tax.' },
        { q:'What is a withholding tax exemption certificate and why do suppliers request it?', kw:['withholding exemption certificate'],
          a:'A certificate issued by the Tax Authority, permitting payment to a supplier without withholding at source or at a reduced rate, in order to improve the supplier\'s ongoing cash flow.' },
        { q:'What is betterment tax on the sale of an unbuilt plot of land?', kw:['betterment tax land'],
          a:'The sale of vacant land is also subject to betterment tax on the profit generated, usually without the special exemptions that apply to a single residential apartment.' + GENERIC_CTA },
        { q:'How is tax calculated on inherited real estate sold by the heirs?', kw:['tax on inherited real estate'],
          a:'The heirs "step into the shoes" of the deceased regarding the historical purchase value, so at the time of sale the profit is calculated from the original purchase date, not from the date the inheritance was received.' + GENERIC_CTA },
        { q:'What is the minimum and maximum National Insurance for especially high income?', kw:['national insurance ceiling'],
          a:'There is a monthly income ceiling above which no additional National Insurance contribution is added, so people with very high incomes pay a lower effective percentage of their total income.' },
        { q:'What is the difference in taxation between a self-employed person and a company regarding National Insurance?', kw:['national insurance self-employed vs company'],
          a:'A self-employed person pays National Insurance on their entire taxable income. A controlling shareholder in a company pays National Insurance only on the salary they draw from the company as an employee, not on the company\'s profits themselves.' + GENERIC_CTA },
        { q:'How can I see if I paid too much tax during the year?', kw:['paid too much tax'],
          a:'Compare the total tax actually withheld in pay slips or advances against the tax that should have been paid according to the annual assessment - a positive difference in your favor is refunded as a tax refund.' },
        { q:'What is Form 1301 and who is it for?', kw:['Form 1301'],
          a:'The annual income tax return form for individuals, used to declare all income and expenses for calculating the final tax liability.' },
        { q:'What is the difference between taxable income and gross income?', kw:['taxable income vs gross income'],
          a:'Gross income is the total amount received before any deductions. Taxable income is the amount remaining after deducting recognized expenses and exemptions, and tax is actually calculated on this amount.' },
        { q:'What is a foreign tax credit and when is it relevant?', kw:['foreign tax credit'],
          a:'A credit given for tax paid in a foreign country on certain income, which is offset against the tax due on that same income in Israel, in order to prevent double payment.' + GENERIC_CTA },
        { q:'How is a pension annuity from a foreign company I worked for abroad taxed?', kw:['foreign pension tax','pension abroad taxation'],
          a:'The annuity may be taxable in Israel as a resident, subject to the provisions of the relevant tax treaty between Israel and the country paying the annuity.' + GENERIC_CTA },
        { q:'What is the "personal vs. territorial" principle in international taxation?', kw:['personal vs territorial tax','worldwide income tax'],
          a:'A personal tax system taxes a resident on all income worldwide. A territorial system taxes only income produced within the country itself. Israel operates mainly on the personal system.' },
        { q:'What is a tax refund for exceptional medical expenses?', kw:['tax refund medical expenses','medical expense deduction'],
          a:'Under certain conditions, exceptional medical expenses above a certain percentage of income can qualify for a tax credit. It is recommended to keep all relevant receipts.' + GENERIC_CTA },
        { q:'What is the new immigrant tax credit and how long is it valid?', kw:['new immigrant tax credit','oleh chadash tax benefit'],
          a:'New immigrants are entitled to additional income tax credit points for a limited period set by law from the date of immigration.' + GENERIC_CTA },
        { q:'What is the single-parent tax credit?', kw:['single parent tax credit'],
          a:'An additional credit point granted to a parent raising children alone, on top of the regular credit points given for children.' },
        { q:'What are tax credit points for academic studies?', kw:['tax credit academic degree','education credit points'],
          a:'Graduates of an academic degree or a practical engineer/technician certificate are entitled to additional income tax credit points for several years after completing their studies.' },
        { q:'What is the difference between income tax and National Insurance for a salaried employee with variable pay?', kw:['variable salary national insurance'],
          a:'Both payments are recalculated on every payslip based on actual monthly income, so in months with bonuses or high commissions, both tax and National Insurance increase accordingly.' },
        { q:'What is a linear coefficient in betterment tax on an apartment purchased many years ago?', kw:['linear coefficient betterment tax'],
          a:'A mechanism that divides the profit from selling the apartment between periods with different tax rules that applied over the years the apartment was held, in order to calculate the final tax fairly.' + GENERIC_CTA },
        { q:'What happens to tax if you sell an apartment at a loss?', kw:['selling apartment at a loss'],
          a:'There is no betterment tax liability when there is no profit, but it is important to document the sale transaction and report it to the Tax Authority even when no tax is actually due.' },
        { q:'What is an advance payment (deposit) on betterment tax when signing a sale contract?', kw:['betterment tax advance payment'],
          a:'The seller is required to pay part of the estimated tax within a set time from signing the sale contract, even before the actual transfer of ownership at the Land Registry.' + GENERIC_CTA },
        { q:'How does registering the apartment in both spouses\' names affect the purchase tax calculation?', kw:['joint registration purchase tax'],
          a:'For purchase tax purposes, spouses are considered a single buyer when checking "single apartment" status, even if only one of them is registered as the formal owner.' + GENERIC_CTA },
        { q:'What is tax coordination between a pension annuity and additional employment income?', kw:['tax coordination pension and salary'],
          a:'When you have both a pension annuity and employment income, tax coordination must be done between the two income sources so that excess tax is not withheld from each of them separately.' + GENERIC_CTA },
        { q:'What is a personal deductions file and when do you need to open one?', kw:['personal deductions file'],
          a:'A file with the Tax Authority required for anyone with income from several sources that is not automatically withheld at source, in order to centralize the ongoing reporting and payment of tax.' },
        { q:'What happens if you forget to report income from an additional source to the Tax Authority?', kw:['unreported income','forgot to report income'],
          a:'The Tax Authority may discover the gap by comparing it against third-party reports (such as banks and employers) and issue a supplementary assessment along with fines and late-payment interest.' + GENERIC_CTA },
        { q:'What is the tax credit for a resident of a development area?', kw:['development area tax credit'],
          a:'Residents of localities defined as development areas are entitled to additional income tax credit points, as part of a policy to encourage settlement.' },
        { q:'What is the tax on selling foreign securities compared to Israeli securities?', kw:['tax foreign securities vs local'],
          a:'The tax rate is similar in both cases, but selling foreign securities also requires taking exchange rate effects on the taxable profit into account.' },
        { q:'What is the tax on a swap transaction (simultaneous sale and purchase) of apartments?', kw:['swap transaction apartments','simultaneous exchange sale'],
          a:'A transaction in which two parties exchange assets with each other, which for tax purposes is examined as two separate sale transactions, each with its own tax liability.' + GENERIC_CTA },
        { q:'What is the difference in taxation between receiving an inheritance in cash versus receiving an inheritance in real estate?', kw:['inheritance cash vs real estate'],
          a:'Receiving cash as an inheritance is not itself subject to tax. Real estate received as an inheritance is not taxed at the time of receipt, but will be subject to betterment tax when it is sold in the future.' + GENERIC_CTA },
        { q:'How do I report a significant cash gift I received from my parents to the Tax Authority?', kw:['reporting gift from parents'],
          a:'A gift between family members is not subject to income tax, but for large amounts it is recommended to document the source of the money ahead of a future capital declaration.' + GENERIC_CTA },
        { q:'What is the principle of tax continuity when transitioning between types of income?', kw:['tax continuity principle'],
          a:'A principle by which accrued tax rights and benefits (such as seniority in a study fund) are preserved even when changing employment status, provided the funds were not withdrawn along the way.' },
        { q:'What is a self-assessment compared to an assessment set by the tax assessor?', kw:['self assessment vs tax assessor'],
          a:'A self-assessment is the report you submit and calculate yourself. The tax assessor may review and correct it if discrepancies are found, in which case an assessment is set based on best judgment.' },
        { q:'What is a deficiency penalty in income tax and when is it imposed?', kw:['deficiency penalty income tax'],
          a:'A penalty imposed when the tax actually paid is significantly lower than the tax that should have been paid under the correct assessment, as a result of underreporting.' },
        { q:'What is the difference between late-payment interest and a penalty in income tax?', kw:['late payment interest vs penalty'],
          a:'Late-payment interest is an automatic addition for a delay in payment, regardless of intent. A penalty is an additional sanction imposed in cases of a material violation or false reporting.' },
        { q:'What is an advance tax ruling and when is it worth requesting one?', kw:['advance tax ruling','pre-ruling tax authority'],
          a:'An advance request to the Tax Authority for a binding position on how a complex or unusual transaction will be taxed, before it is actually carried out, in order to avoid future disputes.' + GENERIC_CTA },
        { q:'What is aggressive tax planning and why should it be avoided?', kw:['aggressive tax planning'],
          a:'The use of extreme interpretations of the law to reduce tax, which may be deemed illegitimate and lead to a supplementary assessment, fines, and even criminal proceedings.' + GENERIC_CTA },
        { q:'What is the difference between legitimate tax planning and tax evasion?', kw:['legitimate tax planning vs evasion'],
          a:'Legitimate tax planning makes use of benefits and rights explicitly granted by law. Tax evasion involves concealing income or filing false reports, and it is a criminal offense.' },
        { q:'What is the "economic substance" principle that the Tax Authority uses?', kw:['economic substance principle tax'],
          a:'A principle by which the Tax Authority examines the true economic substance of a transaction, rather than just the legal form in which it was presented, in order to prevent artificial tax planning.' },
        { q:'What is an income tax circular and why is it important for business owners?', kw:['income tax circular'],
          a:'A guidance document published by the Tax Authority that clarifies its position on a particular issue, and helps businesses understand how to apply the law in practice.' },
        { q:'What is the tax on capital gains from selling a business (goodwill)?', kw:['tax goodwill sale of business'],
          a:'Profit from selling a business, including the goodwill component, is taxed as capital gains, subject to specific rules and exemptions relating to the sale of a business asset.' + GENERIC_CTA },
        { q:'What is the difference in taxation between selling shares in a private company versus a public company?', kw:['selling shares private vs public company'],
          a:'The basic principle is similar - capital gains tax on the profit - but selling shares in a private company usually involves additional complexity in determining the fair value of the shares.' + GENERIC_CTA },
        { q:'What is a depreciation deduction on business equipment?', kw:['depreciation deduction business equipment'],
          a:'A business may gradually deduct the cost of equipment (computers, furniture, vehicles) over its useful life, according to the depreciation rates set in the regulations.' },
        { q:'What is a vehicle expense deduction for a self-employed person who uses their private car for work as well?', kw:['vehicle expenses self-employed'],
          a:'A proportional share of fuel, insurance, and maintenance costs can be deducted according to the actual rate of business use, subject to mileage documentation.' + GENERIC_CTA },
        { q:'What is a mixed expense (business and personal) and how is it handled for tax purposes?', kw:['mixed expense business personal'],
          a:'An expense that serves both the business and personal needs, such as a mobile phone or home internet - usually only the proportional part used for the business can be deducted.' },
        { q:'What is the recognized expense reimbursement for a salaried employee who works from home?', kw:['work from home expenses employee'],
          a:'A salaried employee can sometimes claim a deduction or reimbursement for electricity, internet, and furniture expenses related to working from home, subject to employer approval and income tax rules.' + GENERIC_CTA },
        { q:'What is National Insurance for a couple where one spouse does not work?', kw:['national insurance non-working spouse'],
          a:'A spouse who does not work and is not registered as self-employed insured is usually covered through the working spouse, subject to the relevant National Insurance rules.' },
        { q:'What happens to tax if you get married in the middle of the tax year?', kw:['marriage mid-year tax'],
          a:'In the year of marriage, spouses can generally choose between separate reporting and joint reporting, whichever is more beneficial for them.' + GENERIC_CTA },
        { q:'What is joint reporting for spouses to the Tax Authority and when is it worthwhile?', kw:['joint tax reporting spouses'],
          a:'Combining the income of both spouses into a single report, which can be more or less beneficial depending on the income gaps and the credit points of each spouse.' + GENERIC_CTA },
        { q:'What is payroll tax on non-profit organizations and public institutions?', kw:['payroll tax nonprofit organizations'],
          a:'A unique tax paid by non-profit institutions on the salaries paid to their employees, as a substitute for value added tax which does not apply to them.' },
        { q:'What is a tax deduction for a self-employed person who employs a family member in the business?', kw:['employing family member business'],
          a:'Paying a salary to a family member is recognized as an expense only if it matches work actually performed and a reasonable salary, otherwise the Tax Authority may disallow recognition of the expense.' + GENERIC_CTA },
        { q:'What is a venture capital fund in terms of taxation of private investors?', kw:['venture capital fund taxation'],
          a:'Profit from realizing an investment in a venture capital fund is taxed as capital gains, with the timing of profit recognition depending on the specific legal structure of the fund.' + GENERIC_CTA },
        { q:'What is a tax deduction for donating securities instead of cash?', kw:['donating securities tax deduction'],
          a:'Donating tradable securities directly to a recognized public institution may also qualify for an exemption from capital gains tax on the increase in value, in addition to the standard credit for donations.' + GENERIC_CTA },
        { q:'What is an unused tax credit surplus that was not utilized in the same year?', kw:['unused tax credit surplus'],
          a:'Some credits can be carried forward and used in subsequent tax years if not fully utilized this year, while other credits simply expire at the end of the year.' },
        { q:'What is a tax adjustment coefficient when moving from salaried employment to self-employment mid-year?', kw:['switching employee to self-employed mid-year'],
          a:'A tax adjustment must be made between the two employment periods within the year, to ensure that total income is taxed correctly and that no double or insufficient tax is collected.' + GENERIC_CTA },
        { q:'What is tax coordination for someone who received unemployment benefits during the tax year?', kw:['tax coordination unemployment benefits'],
          a:'Unemployment benefits from National Insurance constitute income that must be reported, and must be taken into account when calculating the total tax liability for that year.' },
        { q:'What is the tax credit for supporting a disabled family member?', kw:['tax credit disabled family member'],
          a:'Additional credit points are granted to someone who supports or provides for a family member with recognized disability, subject to presenting appropriate medical and institutional certificates.' + GENERIC_CTA },
        { q:'What is the tax credit for a child with special needs?', kw:['tax credit child special needs'],
          a:'Parents of a child with recognized disability are entitled to additional credit points beyond the regular credits given for children.' + GENERIC_CTA },
        { q:'What is the difference between a tax deduction for mortgage insurance and a mortgage interest deduction?', kw:['mortgage insurance deduction vs interest deduction'],
          a:'In most cases in Israel there is no tax deduction for mortgage interest on a home as there is in certain countries abroad - this is an important difference to be aware of before comparing to foreign sources.' },
        { q:'What is a tax credit for paying especially high tuition fees?', kw:['tax credit tuition fees'],
          a:'There are limited cases in which payment for certain studies (such as professional continuing education) qualifies for a tax benefit, unlike regular tuition.' },
        { q:'What is tax coordination for someone with income from a National Insurance disability benefit together with employment?', kw:['tax coordination disability benefit and work'],
          a:'The mutual effect between the disability benefit and employment income should be checked, to ensure that eligibility for the benefit is not harmed and that tax is calculated correctly on both sources together.' + GENERIC_CTA },
        { q:'What is a legal expense deduction from taxable income?', kw:['legal expense deduction'],
          a:'Legal expenses directly related to producing business income (such as accompanying a business contract) are usually recognized as an expense, while personal legal expenses are not recognized.' },
        { q:'What is an advertising and marketing expense deduction for the self-employed?', kw:['advertising expense deduction'],
          a:'Advertising and marketing expenses incurred to promote the business are fully recognized as an expense, and reduce the business\'s taxable income.' },
        { q:'What is the tax on a cash prize or award I received?', kw:['tax on cash prize'],
          a:'A cash prize or one-time grant may be considered taxable income, depending on the nature of the prize and the circumstances of receiving it - it is worth checking each case individually.' + GENERIC_CTA },
        { q:'What is a tax refund for a couple after one of them retires?', kw:['tax refund after retirement'],
          a:'A decrease in the income of the spouse who retired may justify checking for a tax refund, especially if excess tax was withheld relative to the family\'s reduced total annual income.' + GENERIC_CTA },
        { q:'Who should I approach first on tax matters - Tal or an independent tax advisor?', kw:['who to approach about tax'],
          a:'Tal specializes in the tax aspects of pension, retirement, and investments, and works in cooperation with tax advisors and accountants for ongoing and more complex accounting needs.' + GENERIC_CTA },
        { q:'What is longevity risk in retirement planning?', kw:['longevity risk retirement'],
          a:'The risk that you will live longer than expected and will need to stretch your savings over more years than originally planned - a fixed monthly annuity protects against this risk.' },
        { q:'How does a pension fund handle longevity risk on behalf of all members?', kw:['pension fund longevity risk'],
          a:'The fund insures all members together (mutual insurance), so that the funding of those who live much longer than expected is offset against those who pass away earlier.' },
        { q:'What is a reverse mortgage and how can it serve as an income source in retirement?', kw:['reverse mortgage retirement income'],
          a:'A loan against the value of your home that allows you to draw funds without selling the house and without monthly repayments, with the loan repaid only from the future sale of the apartment.' + GENERIC_CTA },
        { q:'What is the risk of a reverse mortgage compared to selling the apartment and moving to a smaller one?', kw:['reverse mortgage risk'],
          a:'With a reverse mortgage, the debt keeps growing with interest and may significantly erode the inheritance left to the children, whereas moving to a smaller apartment frees up immediate capital without creating debt.' + GENERIC_CTA },
        { q:'Is it worth selling a large apartment and moving to a smaller one to fund retirement?', kw:['selling apartment to fund retirement'],
          a:'This can be an effective way to free up liquid capital for retirement, but the emotional and practical cost of the move should be weighed against the financial benefit.' + GENERIC_CTA },
        { q:'What is correct withdrawal sequencing between income sources in retirement?', kw:['withdrawal sequencing retirement'],
          a:'Determining the optimal order in which to withdraw funds from different sources (pension, provident fund, investment portfolio) in order to minimize tax and extend the life of your savings.' + GENERIC_CTA },
        { q:'Why is it better to withdraw first from taxable sources rather than tax-exempt ones?', kw:['withdrawal order taxation'],
          a:'It is usually preferable to leave tax-exempt funds (such as a study fund) to grow tax-free for as long as possible, and withdraw first from sources that will be taxed anyway.' + GENERIC_CTA },
        { q:'How do you plan retirement when spouses have a significant age gap?', kw:['spouse age gap retirement'],
          a:'The retirement timing of each spouse should be planned separately, along with the survivors\' annuity tracks, so that protection for the younger spouse is maintained for a longer period.' + GENERIC_CTA },
        { q:'What happens to retirement planning if a spouse has a chronic illness?', kw:['retirement chronically ill spouse'],
          a:'Greater weight should be given to securing a survivors\' annuity and supplementary medical coverage, and sometimes a partial lump-sum commutation should be considered for immediate needs.' + GENERIC_CTA },
        { q:'What is retirement planning for teachers and education workers?', kw:['retirement planning teachers'],
          a:'Education workers may be insured under veteran or unique accumulating pension arrangements specific to the education sector, with different tax rules and retirement grants than the private sector.' + GENERIC_CTA },
        { q:'What is the difference in retirement planning between a government employee and a private sector employee?', kw:['retirement planning government employee'],
          a:'Veteran government employees may enjoy a budgetary pension with completely different rules from the accumulating pension common in the private sector, requiring separate planning.' + GENERIC_CTA },
        { q:'What is a deficit-ridden veteran pension fund and what does it mean for members?', kw:['deficit veteran pension fund'],
          a:'A situation in which the fund\'s obligations for future annuity payments exceed its assets, which may lead to government intervention or changes in member rights.' },
        { q:'What is the "0.5250" arrangement in the veteran pension funds?', kw:['veteran pension funds arrangement'],
          a:'A historic government arrangement designed to ensure the financial stability of the deficit-ridden veteran pension funds, through a government guarantee for annuity payments.' },
        { q:'How does an index-tracking investment track affect the return in a pension fund?', kw:['index tracking pension track'],
          a:'A track that follows a certain index usually charges lower management fees, but does not try to "beat the market" - it simply aims to achieve the index\'s own return.' + GENERIC_CTA },
        { q:'What is a Halacha (Sharia-equivalent religious law) investment track in a pension fund?', kw:['halacha track pension fund'],
          a:'An investment track managed according to Jewish religious law rules, avoiding investment in certain types of companies and instruments in accordance with rabbinical rulings.' },
        { q:'Can I choose an investment track in a pension fund focused only on environment and sustainability (ESG)?', kw:['ESG track pension fund'],
          a:'Yes, some pension funds now offer investment tracks focused on companies that meet environmental, social, and governance (ESG) criteria.' + GENERIC_CTA },
        { q:'What is retirement planning for self-employed doctors with variable income?', kw:['retirement planning doctors'],
          a:'Requires flexibility in deposits according to income volatility, alongside a combination of pension fund, executive insurance, and investment provident fund to diversify retirement income sources.' + GENERIC_CTA },
        { q:'What is retirement planning for people with multiple income sources (business, rental, investments)?', kw:['retirement multiple income sources'],
          a:'Requires comprehensive mapping of all expected income sources in retirement and integrated tax planning, so as not to pay excess tax due to a lack of coordination between the sources.' + GENERIC_CTA },
        { q:'What is healthy life expectancy and why is it relevant to retirement planning?', kw:['healthy life expectancy'],
          a:'The expected length of time a person lives in good health and not merely alive - important for planning because it affects the preference for an annuity versus a lump sum and the need for long-term care insurance.' },
        { q:'How does combining freelance consulting work after retirement affect the annuity?', kw:['freelance work after retirement'],
          a:'Self-employed income after retirement generally does not harm eligibility for the pension annuity itself, but may affect the amount of the old-age benefit from National Insurance if you have not yet reached full eligibility age.' + GENERIC_CTA },
        { q:'What is a "gradual retirement" plan (working part-time)?', kw:['gradual retirement plan'],
          a:'An arrangement in which the scope of employment is gradually reduced before full retirement, to ease the financial and emotional transition to retirement life.' + GENERIC_CTA },
        { q:'What is the financial "identity crisis" that people experience in the first year of retirement?', kw:['first year retirement crisis'],
          a:'An adjustment period in which one moves away from the habit of a fixed salary to managing an independent cash flow from annuities and savings - organized advance planning greatly eases this transition.' + GENERIC_CTA },
        { q:'What is a retirement budget and why should one be prepared before actually retiring?', kw:['retirement budget'],
          a:'A mapping of all expected expenses against all monthly income sources in retirement, to make sure in advance that cash flow is indeed sufficient for the desired lifestyle.' + GENERIC_CTA },
        { q:'What is a liquid "safety cushion" that should be kept at the start of retirement?', kw:['retirement safety cushion'],
          a:'A liquid sum kept separate from the invested portfolio, so as not to be forced to sell assets at a loss during a market downturn close to the start of retirement.' + GENERIC_CTA },
        { q:'How does the timing of retirement during a capital market crisis affect my savings?', kw:['retirement timing market crisis'],
          a:'Retiring exactly during a period of sharp market declines can significantly reduce the ability of savings to last for years - this is known as "sequence of returns risk."' + GENERIC_CTA },
        { q:'What is sequence of returns risk?', kw:['sequence of returns risk'],
          a:'The risk that the order of returns in the first years of retirement (good or bad) affects how long the savings last far more than the average return over the entire period.' + GENERIC_CTA },
        { q:'What is tax planning for a retiree who is still working part-time?', kw:['tax retiree working part time'],
          a:'Coordination is needed between the tax withheld from the annuity and the tax withheld from the partial salary, so that the total tax correctly reflects both income sources together.' + GENERIC_CTA },
        { q:'What is retirement planning for a couple where one is self-employed and the other is a salaried employee?', kw:['retirement self-employed and employee'],
          a:'Requires coordination between two completely different savings tracks (employer contributions versus self-employed deposits), so the family reaches retirement with balanced coverage for both spouses.' + GENERIC_CTA },
        { q:'What is the "pension gap" between men and women and why does it exist?', kw:['gender pension gap'],
          a:'A gap in the level of pension savings resulting, among other things, from career breaks for raising children, wage gaps, and longer life expectancy for women - which requires dedicated planning.' + GENERIC_CTA },
        { q:'How can the pension gap created by maternity leave be reduced?', kw:['pension maternity leave'],
          a:'It is possible to arrange with the employer to continue pension contributions during maternity leave as well, so as not to harm the continuity and level of long-term savings.' + GENERIC_CTA },
        { q:'What are pension rights during extended reserve duty (miluim)?', kw:['pension reserve duty miluim'],
          a:'There are provisions ensuring the continuation of insurance rights in the pension fund even during extended reserve duty, in accordance with the Discharged Soldiers Law and the fund\'s regulations.' },
        { q:'What are the pension rights of a pregnant employee who was dismissed?', kw:['pension pregnancy dismissal'],
          a:'Dismissing a pregnant employee is almost entirely prohibited by law, and even if it happened, her pension rights accrued up to the date of dismissal remain protected for her.' + GENERIC_CTA },
        { q:'What is annuity planning for a single retiree with no children or spouse?', kw:['retirement single no family'],
          a:'Without the need for survivors\' protection, it is usually possible to choose an annuity track that maximizes the monthly amount for yourself, without additional allocation for a spouse or children.' + GENERIC_CTA },
        { q:'What is protection against "retiring incorrectly" - common mistakes at the moment of retirement?', kw:['common retirement mistakes'],
          a:'Common mistakes include not filing a rights-fixing (kibua zchuyot) form, choosing an unsuitable annuity track, and not fully utilizing the exemptions on severance grants - all of which are irreversible.' + GENERIC_CTA },
        { q:'What is a "financial health check" before retirement and what does it include?', kw:['financial health check retirement'],
          a:'A comprehensive review of all savings, insurance policies, debts, and expected income, designed to make sure you are financially prepared for the transition to retirement life.' + GENERIC_CTA },
        { q:'What is retirement planning for a couple with adult children who are financially dependent?', kw:['adult dependent children retirement'],
          a:'Ongoing financial support should be factored into retirement cash flow planning, and sometimes lump-sum withdrawals should be deferred to preserve long-term budget flexibility.' + GENERIC_CTA },
        { q:'What is "hi-tech early retirement" and how does it differ from regular retirement?', kw:['hi-tech early retirement'],
          a:'Many hi-tech employees accumulate significant wealth in stocks and options and want to retire well before the official retirement age - this requires separate planning to bridge until the age at which pension annuities can be realized.' + GENERIC_CTA },
        { q:'What is a financial bridge between early retirement and the official pension eligibility age?', kw:['bridge early retirement'],
          a:'Planning temporary income sources (investment portfolio, investment provident funds) to cover expenses until the age at which pension annuity withdrawal can begin under optimal terms.' + GENERIC_CTA },
        { q:'What is the 4% rule for withdrawing from an investment portfolio in retirement?', kw:['4 percent rule retirement'],
          a:'A common rule of thumb stating that an annual withdrawal of about 4% of the invested portfolio allows the portfolio to last for decades of retirement, but it is a general rule and not personalized.' + GENERIC_CTA },
        { q:'Why doesn\'t the 4% rule always fit the Israeli situation?', kw:['4 percent rule not suitable'],
          a:'The rule was developed in the US and is based on American market and tax data, whereas in Israel there are pension funds with a guaranteed annuity that significantly change the correct planning.' + GENERIC_CTA },
        { q:'What is the "bucket strategy" in managing retirement money?', kw:['bucket strategy retirement'],
          a:'Dividing savings into three groups by time horizon - liquid for the short term, balanced for the medium term, and growth-oriented for the long term - to balance security against return.' + GENERIC_CTA },
        { q:'What is retirement planning for someone whose main income source is an income-producing asset (a rental apartment)?', kw:['retirement rental property income'],
          a:'The stability of rental income should be weighed against the risks (vacancy periods, repairs), and it should not be the only income source without additional backup.' + GENERIC_CTA },
        { q:'What is investment portfolio rebalancing during the retirement years?', kw:['rebalancing retirement portfolio'],
          a:'A periodic adjustment of the portfolio\'s composition between stocks and bonds, to maintain the desired risk level even as markets change the relative weight between the assets.' + GENERIC_CTA },
        { q:'What is inheritance planning as part of retirement planning itself?', kw:['inheritance as part of retirement'],
          a:'Combining a response to your ongoing needs in retirement with a desire to leave an inheritance for the children, which can affect the choice between an annuity track and a lump-sum withdrawal.' + GENERIC_CTA },
        { q:'What are the "golden years" in terms of cash flow planning in retirement (higher expenses at the start of retirement)?', kw:['golden years cash flow'],
          a:'The phenomenon in which retirees spend more in the first, active years of retirement (travel, hobbies) compared to later years with less activity but higher medical expenses.' + GENERIC_CTA },
        { q:'What is the "portability" right of benefits between executive insurance and a pension fund?', kw:['portability benefits executive insurance to pension'],
          a:'The option to transfer the benefits component accrued in executive insurance to a pension fund (or vice versa), subject to checking the impact on old terms such as a guaranteed conversion rate.' + GENERIC_CTA },
        { q:'What is the difference between the "benefits" component and the "severance" component in executive insurance?', kw:['benefits vs severance executive insurance'],
          a:'The benefits component is intended for your future pension savings. The severance component corresponds to the severance pay that the employer sets aside for you by law.' },
        { q:'What happens to the severance component in executive insurance if you resign (rather than being dismissed)?', kw:['severance upon resignation'],
          a:'Upon regular resignation (not under circumstances entitling severance pay), the severance component remains in the fund until retirement, unless the employer releases it with special approval.' + GENERIC_CTA },
        { q:'What are "severance continuity" and "annuity continuity" and when should each be chosen?', kw:['severance continuity annuity continuity'],
          a:'Two tracks for deferring tax on severance funds when leaving a job - severance continuity preserves the exemption for a later date, while annuity continuity converts the entitlement into an annuity track.' + GENERIC_CTA },
        { q:'What is a tax assessor\'s approval for a tax exemption on a retirement grant?', kw:['tax assessor approval retirement grant'],
          a:'An official document determining how much of the grant received at the end of employment is tax-exempt and how much is taxable, according to seniority and the updated exemption ceilings.' + GENERIC_CTA },
        { q:'What happens if I changed several jobs and never ported severance funds?', kw:['scattered severance funds'],
          a:'You may have several small funds scattered from different jobs - it is worth consolidating them and checking the terms of each before merging or withdrawing.' + GENERIC_CTA },
        { q:'How do you locate "lost" pension funds from old jobs?', kw:['lost pension funds old jobs'],
          a:'You can use the pension clearinghouse or the Ministry of Finance\'s "Har HaBituach" website to locate all the policies and funds registered in your name.' + GENERIC_CTA },
        { q:'What is the pension clearinghouse and what is its role?', kw:['pension clearinghouse role'],
          a:'A central government system that consolidates information on all pension products of every citizen, and enables you to receive a consolidated report of all your savings in one place.' },
        { q:'What is the annual data summary report from the pension clearinghouse?', kw:['annual clearinghouse report'],
          a:'A report sent every year that consolidates all the provident funds, pension funds, and executive insurance policies registered in your name, including management fees and accumulation in each of them.' },
        { q:'What is the right to review my pension file at the insurance company?', kw:['right to review pension file'],
          a:'The right to receive from the insurance company or pension fund a full copy of the policy, the regulations, and the history of your accumulation and deposits at any time.' },
        { q:'What is the new "employee form" filled out at every workplace regarding pension?', kw:['employee form pension'],
          a:'A form in which the employee chooses the pension fund or executive insurance to which their contributions at the new workplace will be directed, if they do not have a previous fund to continue with.' },
        { q:'What happens if you don\'t fill out a pension fund selection form at a new workplace?', kw:['did not choose pension fund'],
          a:'The employer is required to contribute on your behalf to a default fund set in a collective agreement or by law, until you choose a different fund yourself.' + GENERIC_CTA },
        { q:'What is a default fund in mandatory pension?', kw:['default pension fund'],
          a:'A pension fund selected through a government tender to offer the lowest management fees, and serves as the default for employees who did not choose their own fund.' },
        { q:'What is joint family retirement planning for a family with a family business?', kw:['retirement planning family business'],
          a:'Requires coordination between the next generation continuing to run the business and ensuring a stable, independent income source for the older generation retiring from it.' + GENERIC_CTA },
        { q:'What is "projected pension" versus the "actual pension" paid by the fund?', kw:['projected pension vs actual'],
          a:'The theoretical forecast shown to you in the annual reports before retirement may change in practice according to returns, management fees, and the conversion rate at the time of actual retirement.' + GENERIC_CTA },
        { q:'Is it worth requesting a retirement simulation several years before actually retiring?', kw:['retirement simulation'],
          a:'Definitely yes - an early simulation allows gaps to be identified and corrected (such as increasing contributions) while there is still time to influence the final outcome.' + GENERIC_CTA },
        { q:'What is the "cash flow gap" that is only discovered after actually retiring, and how is it avoided?', kw:['cash flow gap after retirement'],
          a:'A gap between the income you expected to receive and the income you actually receive, which is avoided through an accurate retirement simulation and checking all sources in advance with professional guidance.' + GENERIC_CTA },
        { q:'What is independent retirement advice compared to advice from the pension fund itself?', kw:['independent retirement advice'],
          a:'Independent advice examines all the options on the market with no affiliation to a particular product, while a representative of the fund may be limited to recommending the products of the entity they represent.' + GENERIC_CTA },
        { q:'What is a marketing commission that pension funds may pay to an agent?', kw:['pension marketing commission'],
          a:'A commission paid by the fund to the agent for managing the client, subject to ceilings set by the regulator, and it is not added to your cost beyond the regular management fees.' },
        { q:'What is retirement planning for people with debts (such as loans or an outstanding mortgage)?', kw:['retirement planning with debts'],
          a:'It is worth examining whether it is better to pay off the debt before retirement using existing capital, or to continue paying it from the monthly annuity - it depends on the loan interest rate versus the alternative investment return.' + GENERIC_CTA },
        { q:'What is variable interest on a loan taken against a provident fund?', kw:['variable interest provident fund loan'],
          a:'The interest on a loan against a provident fund may be linked to the prime rate or fixed in advance, depending on the specific policy of the fund from which the loan is taken.' },
        { q:'What is the right to withdraw funds from a provident fund for purchasing a first apartment?', kw:['withdrawing provident fund first apartment'],
          a:'Certain dedicated plans allow a tax-advantaged withdrawal of savings for the purchase of a first apartment, subject to conditions and the type of fund.' + GENERIC_CTA },
        { q:'What is pension savings for children (a pension fund for a child) and from what age can one be opened?', kw:['pension savings for children'],
          a:'A pension savings plan can be opened for a minor child, preserving accumulation and insurance rights that build up even before the child begins working.' + GENERIC_CTA },
        { q:'What is the "savings for every child" program and how is it related to the child\'s future retirement planning?', kw:['savings for every child retirement'],
          a:'A government savings program automatically opened for every child in Israel, which can serve as an initial basis for long-term savings as the child grows up.' },
        { q:'What is compound interest over 40 years of pension savings?', kw:['compound interest pension'],
          a:'An effect whereby the returns on your savings themselves earn additional returns over the years, making early-career contributions far more significant than later contributions.' },
        { q:'What is retirement planning for someone who immigrated to Israel at an older age and has no local pension seniority?', kw:['retirement planning older immigrant'],
          a:'Requires focused planning to build up pension savings in a relatively short time frame, usually while incorporating pension rights accrued in the country of origin if a relevant treaty exists.' + GENERIC_CTA },
        { q:'What is recognition of pension rights accrued abroad for the purpose of an Israeli pension?', kw:['recognizing pension rights from abroad'],
          a:'Depends on the existence of a social security treaty between Israel and the foreign country, which can allow combining insurance periods for eligibility for benefits in both countries.' + GENERIC_CTA },
        { q:'What is retirement planning for families with a child with special needs who will remain financially dependent for life?', kw:['retirement child dependent for life'],
          a:'Requires especially long-term planning, usually combined with a trust or a dedicated legal arrangement that ensures continued financial support even beyond the parents\' lifetime.' + GENERIC_CTA },
        { q:'What is a central severance provident fund and why do employers use it?', kw:['central severance provident fund'],
          a:'A fund in which an employer deposits severance funds for several employees in one place, managed separately from each employee\'s personal pension savings.' },
        { q:'What is an employee\'s right to know how much money is being contributed to their pension on each payslip?', kw:['payslip pension contribution transparency'],
          a:'The law requires the employer to detail on the payslip the amounts contributed for benefits and severance each month separately, so the employee can track their rights.' },
        { q:'What is a different "conversion rate" between men and women and why?', kw:['different conversion rate by gender'],
          a:'In the past, different conversion rates were set for men and women based on life expectancy gaps, but regulation today is pushing toward unifying and equalizing rates between the sexes.' + GENERIC_CTA },
        { q:'What is a "general pension fund" versus a "comprehensive pension fund"?', kw:['general vs comprehensive pension fund'],
          a:'A comprehensive pension fund includes a guaranteed designated bond component and is limited by a deposit ceiling. A general pension fund does not include this benefit but is open to higher deposits.' + GENERIC_CTA },
        { q:'When is it worth combining a comprehensive pension fund and a general pension fund during the same period?', kw:['combining comprehensive and general pension'],
          a:'When your monthly deposit exceeds the ceiling eligible for the comprehensive track, the balance can be directed to the general track so as not to lose the tax benefit.' + GENERIC_CTA },
        { q:'What is a "self-employed member" in a pension fund compared to a "salaried member"?', kw:['self-employed vs salaried member pension'],
          a:'A self-employed member deposits directly and independently into the fund with no employer, while a salaried member benefits from a combined deposit from themselves and the employer through the payslip.' },
        { q:'What happens to insurance rights in a pension fund if you stop making deposits for a long period?', kw:['stopping deposits long period'],
          a:'After a period of stopped deposits (usually a few months), disability and survivors insurance coverage may lapse, unless "temporary risk" coverage is paid for separately.' + GENERIC_CTA },
        { q:'What is a "temporary risk policy" for preserving rights in a pension fund?', kw:['temporary risk policy preserving rights'],
          a:'A relatively low payment that allows you to continue enjoying the pension fund\'s insurance coverage (disability and survivors) even during a period without ongoing deposits.' + GENERIC_CTA },
        { q:'What is an "actuary" and their role in the pension fund?', kw:['actuary pension fund role'],
          a:'A professional who calculates and balances the fund\'s future obligations for annuity payments against its assets, and ensures its long-term financial stability.' },
        { q:'What is an "actuarial balance sheet" in a pension fund and why is it important to savers?', kw:['actuarial balance sheet'],
          a:'A periodic report examining the fund\'s financial balance, which can affect the future level of annuities paid to members if an ongoing deficit is found.' },
        { q:'What is an "actuarial surplus" in a pension fund and to whom is it distributed?', kw:['actuarial surplus pension fund'],
          a:'A situation in which the fund has more assets than required to cover its obligations, which may be distributed among members as an addition to their accumulation or annuity.' },
        { q:'What is retirement planning for someone who worked most of their career abroad and returned to Israel only shortly before retirement?', kw:['retirement returning from abroad before retirement'],
          a:'Requires a thorough check of rights accrued abroad, relevant treaties, and eligibility for an old-age benefit from Israeli National Insurance according to the limited seniority in Israel.' + GENERIC_CTA },
        { q:'What is retirement planning for athletes or artists with a short career but high income?', kw:['retirement planning short career'],
          a:'Requires maximum use of the high-income years for intensive saving, to compensate for a savings period significantly shorter than usual.' + GENERIC_CTA },
        { q:'What is "commutation of a low annuity" (an annuity below a minimum amount) and why does it happen?', kw:['commutation of low annuity'],
          a:'When the calculated monthly annuity is lower than a minimum amount set by the regulator, the full amount can usually be commuted and received as a one-time lump sum instead of a negligible annuity.' + GENERIC_CTA },
        { q:'What is retirement planning when there are several small pension funds from different jobs?', kw:['several small pension funds'],
          a:'It is usually preferable to consolidate the small funds into one fund to save on duplicate management fees and simplify management, but old terms should be checked before merging.' + GENERIC_CTA },
        { q:'What is the right to "review a retirement simulation" several times a year with the pension fund?', kw:['retirement simulation multiple times a year'],
          a:'You can request an updated simulation of the expected annuity from the pension fund several times a year, at no cost, to track progress toward retirement.' },
        { q:'What is retirement planning for someone planning to move abroad after retiring?', kw:['retirement planning moving abroad'],
          a:'It should be checked how Israeli annuities will be taxed in the new country of residence, and whether a tax treaty regulating this exists between Israel and that country.' + GENERIC_CTA },
        { q:'Does an Israeli pension annuity continue to be paid to someone who leaves Israel permanently?', kw:['pension for someone leaving Israel'],
          a:'Yes, the pension annuity continues to be paid to your bank account even if you live permanently abroad, but the tax aspects may change depending on the country of residence.' + GENERIC_CTA },
        { q:'What is retirement planning that also includes arranging a durable power of attorney?', kw:['durable power of attorney retirement'],
          a:'A legal document that appoints in advance a person to manage your financial and medical affairs if in the future you are not competent to do so yourself - important to incorporate into overall retirement planning.' + GENERIC_CTA },
        { q:'What is the difference between a durable power of attorney and guardianship?', kw:['durable power of attorney vs guardianship'],
          a:'A durable power of attorney is signed in advance by you while you are competent and expresses your wishes. Guardianship is determined by a court after a person is no longer competent, sometimes without a prior expression of wishes.' },
        { q:'What is a financial "letter of intent" for family members ahead of retirement?', kw:['financial letter of intent'],
          a:'A legally non-binding document that explains to family members where all the important savings, insurance policies, and documents are located, to make things easier for them if needed.' },
        { q:'What is retirement planning for someone who manages assets jointly with business partners?', kw:['retirement joint assets business partners'],
          a:'Requires a clear partnership agreement in advance regarding the exit mechanism, valuation, and payment arrangements when one of the partners reaches retirement.' + GENERIC_CTA },
        { q:'What is "quiet retirement" and why are more people choosing it?', kw:['quiet retirement'],
          a:'A trend of gradually reducing work pace instead of a sharp, one-time retirement, allowing a softer transition to retirement life both financially and emotionally.' + GENERIC_CTA },
        { q:'What is "working in retirement" (part-time work not for financial reasons) and how does it affect planning?', kw:['working in retirement by choice'],
          a:'Even if the income is not essential, it should be taken into account in tax planning and in examining the effect on eligibility for income-tested benefits.' + GENERIC_CTA },
        { q:'What is re-planning retirement several years after you have already retired?', kw:['re-planning after retirement'],
          a:'It is recommended to redo a review every few years, since changes in health, the capital market, and family needs may justify adjustments to cash flow and investment tracks.' + GENERIC_CTA },
        { q:'What are signs that my retirement cash flow is not sustainable in the long term?', kw:['unsustainable retirement cash flow'],
          a:'Consistent withdrawal beyond the portfolio\'s return, a steady decline in the total accumulated amount, or full dependence on a single annuity with no additional safety cushion - all are warning signs worth checking with me sooner rather than later.' + GENERIC_CTA },
        { q:'What is the periodic retirement check-up service that Tal offers?', kw:['periodic retirement check-up'],
          a:'A repeated review of your entire retirement plan every few years, to make sure it still fits changes in life, in the law, and in the capital market.' + GENERIC_CTA }
      ]},
      { key:'insure', label:'🛡️ Insurance Review & Savings', items:[
        { q:'How do I know if I have duplicate insurance policies?', kw:['duplicate insurance','overlapping policies'],
          a:'A comprehensive check through "Har HaBituach" (the Israeli Finance Ministry\'s insurance policy database) identifies duplicate, redundant, or overpriced policies - clients save an average of hundreds of NIS per month.' + GENERIC_CTA },
        { q:'What is the difference between private health insurance and health fund (Kupat Cholim) coverage?', kw:['private health insurance','health fund HMO'],
          a:'Private insurance covers cases not included in the state health basket (life-saving medications, transplants, complex surgeries abroad) and lets you choose your doctor and timing.' + GENERIC_CTA },
        { q:'Why is loss of working capacity/disability insurance important?', kw:['loss of working capacity','disability insurance'],
          a:'It protects the family\'s financial stability in the event of a crisis - financial compensation that maintains your standard of living without depleting your savings.' + GENERIC_CTA },
        { q:'What is the "Frenkel clause" (premium waiver on disability)?', kw:['premium waiver clause','waiver of premium'],
          a:'A protection clause under which, if the insured loses their working capacity, the insurance company pays the premiums on their behalf - so the savings or coverage continue to grow even during a crisis.' },
        // TRANSLATOR NOTE: source calls this "סעיף פרנטל" ("Frenkel clause") - could not confirm this is a standard industry name in English; translated literally as a premium-waiver clause and flagged the name for verification.
        { q:'What is the difference between occupational and professional loss of working capacity?', kw:['occupational vs professional','loss of capacity types'],
          a:'Occupational: compensation if you cannot work in your specific profession. Professional: compensation only if you cannot work in any occupation suited to your education - occupational coverage is recommended for people in liberal/independent professions.' + GENERIC_CTA },
        { q:'Does mortgage life insurance cover my children?', kw:['mortgage life insurance','children'],
          a:'No - it is intended for the bank only; it settles the debt but does not leave liquid cash for the family. It is worth adding standard (term) life insurance as well.' + GENERIC_CTA },
        { q:'Is long-term care insurance through my health fund enough?', kw:['long-term care health fund','is it enough'],
          a:'This is basic coverage but is limited to only 5 years, and usually does not cover the full actual cost of long-term care - it may be worth considering a supplement.' + GENERIC_CTA },
        { q:'What is a qualifying period in health insurance?', kw:['qualifying period','waiting period health insurance'],
          a:'The time that must pass from signing the policy until you can file a claim on it (usually 30 days to 3 months) - designed to prevent people from buying insurance only after discovering an illness.' },
        { q:'When do I need to update my health declaration?', kw:['health declaration update'],
          a:'When joining a new policy or expanding an existing one - full disclosure prevents claim denials in the future.' + GENERIC_CTA },
        { q:'What is the difference between life insurance and personal accident insurance?', kw:['life insurance vs personal accident'],
          a:'Term life insurance: a one-time payout to the family in the event of death from any cause. Personal accident insurance: compensation for fractures, burns, or hospitalization resulting from an accident only.' + GENERIC_CTA },
        { q:'What is underinsurance?', kw:['underinsurance','insufficient coverage'],
          a:'Declaring an asset value lower than its real worth - in the event of damage you will receive only a reduced, proportional payout, even for minor damage.' + GENERIC_CTA },
        { q:'What is the difference between third-party and comprehensive car insurance?', kw:['third-party insurance','comprehensive car insurance'],
          a:'Third-party: covers only damage you cause to others. Comprehensive: also covers damage to your own car (accident, theft, total loss).' },
        { q:'What insurance is a small business required to have?', kw:['business insurance','small business'],
          a:'At minimum, employers\' liability insurance (if you have employees) and third-party liability; for those in liberal/independent professions, professional liability insurance as well.' + GENERIC_CTA },
        { q:'What is critical illness insurance and who is it suited for?', kw:['critical illness insurance'],
          a:'This is insurance that pays a one-time lump sum upon diagnosis of a critical illness, to help the family cope financially during this difficult period.' + GENERIC_CTA },
        { q:'I have loss of working capacity coverage through my employer - is that enough?', kw:['employer disability coverage','is it enough'],
          a:'Not always. You need to verify the coverage is "occupational" (protects your specific profession) and that it covers up to 75% of your actual salary, including benefits.' + GENERIC_CTA },
        { q:'Is it worth getting life insurance (term) if I have no children or spouse?', kw:['life insurance','no dependents'],
          a:'If no one depends on you financially and you have no debts or a mortgage, you usually do not need life insurance.' + GENERIC_CTA },
        { q:'The insurance company denied my claim - what do I do?', kw:['claim denied','rejected claim'],
          a:'Do not give up. Insurance companies deny many claims at the initial stage. It is recommended to contact us so we can examine the reason for the denial and act on your behalf professionally.' },
        { q:'Why does my life insurance premium go up every year?', kw:['life insurance premium rising'],
          a:'Life insurance is priced on actuarial risk, which increases with age. There are tracks with fixed or variable premiums, and it is worth reviewing which is right for you.' + GENERIC_CTA },
        { q:'What is the difference between long-term care insurance through a health fund and a private policy?', kw:['long-term care health fund vs private'],
          a:'New private long-term care policies are closed to new sales. Today the only way to get long-term care coverage is through the health funds, and it is very important to join it.' },
        { q:'Can I cancel an insurance policy and get my money back?', kw:['cancel insurance','get money back'],
          a:'Pure protection policies (such as health, life, or accident) are the purchase of protection - if no event occurred, there is no refund. Only in savings-type vehicles does the money accumulate for you.' },
        { q:'What is an exclusion in an insurance policy?', kw:['policy exclusion'],
          a:'A pre-existing medical condition you had before joining the insurance, which the insurance company declares in advance it will not cover in the event of a claim.' },
        { q:'How can I cancel unnecessary insurance policies that keep charging my credit card?', kw:['cancel unnecessary insurance','credit card charges'],
          a:'The first step is producing a "Har HaBituach" report. Tal will go over it with you, mark exactly what is redundant or duplicated, and help you cancel them safely.' },
        { q:'I have duplicate health insurance - will I get double compensation if I get sick?', kw:['double compensation','duplicate health insurance'],
          a:'With medical expense insurance (such as surgeries or medications), there is no double compensation - you only get reimbursed for the actual expense. So this kind of duplicate insurance is simply throwing money away.' },
        { q:'What is the difference between personal accident insurance and critical illness insurance?', kw:['personal accident vs critical illness'],
          a:'Personal accident insurance covers physical injuries resulting from a sudden event (fracture, burn, hospitalization). Critical illness insurance pays a cash sum upon diagnosis of a serious internal illness (such as cancer).' },
        { q:'How does the medical underwriting process work when joining an insurance policy?', kw:['medical underwriting'],
          a:'This is a questionnaire in which you declare your health condition. The company decides whether to accept you on standard terms, add a price loading, or exclude existing conditions.' },
        { q:'The insurer wants a medical loading because of my weight or smoking - does that make sense?', kw:['medical loading','smoking weight surcharge'],
          a:'Yes. Insurance companies price actuarial risk. Smokers or people who are overweight are at statistically higher risk, so their premium is more expensive.' },
        { q:'I paid for insurance for years, so why do I run into problems when I file a claim?', kw:['claim problems','claim issues'],
          a:'Denials often stem from misunderstanding the policy terms or inaccurately completing the health declaration. Tal accompanies clients in dealing with insurance companies to prevent this.' },
        { q:'Is it worth keeping my health fund long-term care insurance?', kw:['long-term care health fund','keep it'],
          a:'You must keep it. Since private long-term care policies are closed to new sales, this is currently the only and most important protection you have against high long-term care costs.' + GENERIC_CTA },
        { q:'What is a variable premium in insurance, and when does it jump?', kw:['variable premium','increasing premium'],
          a:'This is a premium that increases every set number of years (usually every 5 years, or annually) according to your age bracket. It is important to track it so it does not become too expensive at an older age.' + GENERIC_CTA },
        { q:'I want to get mortgage life insurance - should I do it through you or the bank?', kw:['mortgage life insurance','bank vs independent'],
          a:'At the bank, policies are usually generic and do not get updated. Tal can find you a customized mortgage policy, often at a much more competitive price and with broader coverage.' + GENERIC_CTA },
        { q:'What is loss of working capacity insurance for the self-employed, and why is it more expensive than for salaried employees?', kw:['self-employed disability insurance'],
          a:'Self-employed people do not receive sick days from the state the way salaried employees do. This insurance is your only safety net if you cannot work, and Tal will tailor an occupational protection policy for you.' + GENERIC_CTA },
        { q:'Can the insurance company cancel my health insurance if I develop a serious illness?', kw:['cancel health insurance','fell ill'],
          a:'Absolutely not. Once you have been accepted into private health insurance, the company is obligated to renew it automatically every year and cannot cancel it due to a change in your medical condition.' },
        { q:'What happens to mortgage life insurance if one spouse passes away?', kw:['mortgage life insurance','spouse passed away'],
          a:'The insurance company pays the remaining debt directly to the bank, and the mortgage is fully closed. The surviving spouse is released from any further payments to the bank.' },
        { q:'My spouse has become dependent on long-term care - how do we claim benefits from the health fund\'s long-term care insurance?', kw:['long-term care claim','ADL assessment'],
          a:'You need to file a claim and present a functional assessment (ADL) showing difficulty performing daily activities (getting up, dressing, bathing, etc.). We accompany clients through these claims.' + GENERIC_CTA },
        { q:'How important is loss of working capacity insurance for someone who just started working and earns little?', kw:['just started working','disability insurance'],
          a:'Your body and your ability to work are your greatest financial asset right now. If something were to happen, this insurance guarantees you a fixed monthly income for years to come.' + GENERIC_CTA },
        { q:'From what age is it recommended to get private health insurance?', kw:['what age private health insurance'],
          a:'It is recommended to join as early as possible, while you are healthy and have no medical history. This ensures acceptance without exclusions and at a relatively low price.' },
        { q:'What happens if my savings run out and I live to 100?', kw:['live to 100','savings run out'],
          a:'The pension fund is built exactly for this - your pension annuity is paid for the rest of your life, no matter how long you live, even if the funds you accumulated physically "run out" in the fund.' },
        { q:'How does a health fund long-term care policy help me if I become dependent on care?', kw:['long-term care annuity','monthly stipend'],
          a:'It provides a fixed monthly annuity for up to 5 years (usually around NIS 3,500 to 5,500 per month, depending on whether care is at home or in an institution), to help the family fund a caregiver.' + GENERIC_CTA },
        { q:'What is the difference between the benefit period and the waiting period in long-term care insurance?', kw:['benefit period','waiting period long-term care'],
          a:'The waiting period is the time from when you become dependent on long-term care until the insurance starts paying (usually two months with the health funds). The benefit period is the length of time they will pay you (5 years).' },
        { q:'Is it worth buying private health insurance even after age 60, when the price jumps?', kw:['health insurance after 60','price increase'],
          a:'The price does indeed rise significantly, but this is exactly the age when health risk increases. Tal should run a comprehensive review and keep only the critical coverages (such as medications and transplants) to reduce costs.' + GENERIC_CTA },
        { q:'What is an incomplete health declaration, and how can it ruin an insurance claim?', kw:['incomplete health declaration'],
          a:'If you forgot (or concealed) a pre-existing medical condition when joining, the insurance company may deny your future claim on grounds of "non-disclosure." Tal makes sure everything is filled out accurately and lawfully.' + GENERIC_CTA },
        { q:'What is SHARAP (private medical services), and is it included in health insurance?', kw:['private medical services','SHARAP'],
          a:'This is a mechanism that lets you choose the specific surgeon or specialist who will treat you in a private hospital. Many health insurance policies include a SHARAP or surgery-in-Israel rider.' },
        { q:'If I have collective (group) long-term care insurance through my employer, what happens when I retire?', kw:['collective long-term care','retirement'],
          a:'Most old collective long-term care policies have been canceled or changed. It is very important to check with Tal what the status of your coverage is, so you do not end up unprotected at an older age.' + GENERIC_CTA },
        { q:'How does the latest health insurance reform affect my policy?', kw:['health insurance reform'],
          a:'The reforms are designed to simplify policies, prevent duplication, and allow easy switching between companies. Tal is on top of all these structural changes and knows how to navigate your portfolio accordingly.' + GENERIC_CTA },
        { q:'What is the out-of-basket medications rider, and who is it for?', kw:['out-of-basket medications rider'],
          a:'This is the most important coverage in health insurance. It funds life-saving medications or genetically personalized medications that cost tens of thousands of shekels a month and are not covered by the state.' + GENERIC_CTA },
        { q:'Is a monthly pension annuity exempt from National Insurance and health tax?', kw:['pension exempt national insurance','health tax'],
          a:'Yes. National Insurance contributions are not deducted from a pension annuity (old-age annuity from the fund), and only a minimal, reduced health tax is deducted, unlike regular employment income.' },
        { q:'Is it worth it for parents to buy life insurance naming their young children as beneficiaries?', kw:['life insurance','children as beneficiaries'],
          a:'Yes, this is a basic tool for securing the children\'s financial future. Tal will tailor the payout amount to the children\'s living, education, and housing needs until they grow up and become independent.' + GENERIC_CTA },
        { q:'What is the ambulatory rider in health insurance, and why is it so useful day to day?', kw:['ambulatory rider','outpatient coverage'],
          a:'This is coverage for medical services that do not require hospitalization, such as consultations with specialists, CT/MRI scans, physiotherapy, and diagnostic tests. It saves thousands of shekels a year on private medicine.' + GENERIC_CTA },
        { q:'Is there insurance that covers sports injuries from extreme sports or diving on a regular basis?', kw:['extreme sports coverage','diving insurance'],
          a:'Yes, in health and personal accident insurance you can add dedicated riders for extreme sports. If you engage in this regularly, it is important to update Tal so there is no problem on the day of a claim.' + GENERIC_CTA },
        { q:'What is the difference between collective health insurance through an employer and a private policy?', kw:['collective health insurance','private policy'],
          a:'Employer-provided insurance is very cheap, but its terms change every few years (the agreement is renewed), and if you leave the job it may become difficult to keep. A private policy is a fixed personal contract for life.' + GENERIC_CTA },
        { q:'What is a settlement agreement with an insurance company in a loss of working capacity claim?', kw:['settlement agreement','disability claim'],
          a:'This is a situation where the company offers you a large one-time sum in exchange for closing the claim and waiving future benefits. Do not sign such an agreement without a financial and professional analysis from Tal.' + GENERIC_CTA },
        { q:'Is it worth getting private health insurance for a newborn baby?', kw:['health insurance newborn baby'],
          a:'Yes, it is highly recommended to join in the first months of life. This ensures a completely smooth entry with no medical exclusions whatsoever, and gives parents peace of mind against medical catastrophes.' },
        { q:'What is personalized medicine (genetic profiling), and does insurance pay for it?', kw:['personalized medicine','genetic profile'],
          a:'This is an advanced coverage in modern health insurance policies that funds complex genetic tests to match the most precise medication to the patient\'s type of illness, dramatically increasing the chances of recovery.' },
        { q:'Why does the insurance company ask me to waive medical confidentiality when I join?', kw:['waiver of medical confidentiality'],
          a:'So that, in the future (in the event of a claim), it can review your medical file at the health fund and verify that the health declaration you filled out when joining was true and complete.' },
        { q:'What is fracture and accident insurance, and who is it especially suited for?', kw:['fractures and accidents insurance'],
          a:'This is insurance that provides quick financial compensation in the event of fractures, burns, or hospitalization resulting from an accident. It is especially suited for children, athletes, or people who do physical work.' + GENERIC_CTA },
        { q:'How does Tal help me update my mortgage life insurance if I moved apartments and the debt grew?', kw:['update mortgage life insurance','moved apartments'],
          a:'Tal simply updates the coverage amount on your existing policy or opens a new one tailored to the new debt, while running a price comparison between companies so you do not pay a single unnecessary shekel.' + GENERIC_CTA },
        { q:'What is the medical concierge service some insurance companies offer?', kw:['medical concierge service'],
          a:'This is a personal case-management service provided by the company, which helps you get quick appointments with specialists and tests, and navigates the bureaucracy for you during an illness.' },
        { q:'What is loss of working capacity insurance?', kw:['what is disability insurance'],
          a:'A policy designed to replace your monthly income, up to 75% of it, in the event that, due to an accident or illness, the insured is unable to work in their profession.' },
        { q:'What is the difference between general and occupational loss of working capacity?', kw:['occupational vs general disability'],
          a:'Occupational loss-of-working-capacity coverage protects the insured if they cannot work in their specific profession. General loss-of-working-capacity coverage only protects them if they are unable to work in any reasonable occupation.' + GENERIC_CTA },
        { q:'Why do doctors need a special professional rider for loss of working capacity insurance?', kw:['professional rider for doctors'],
          a:'Doctors are exposed to functional injuries (for example, to the hands) or occupational illnesses, and a professional rider ensures compensation even in functional situations specific to their profession.' + GENERIC_CTA },
        { q:'What is full occupational disability coverage for high-tech employees?', kw:['full occupational coverage high-tech'],
          a:'Coverage that precisely defines roles such as programmer or engineer, and compensates them if they fall ill or are injured and prevented from performing their occupation, without the insurance company being able to redirect them to work in another field.' + GENERIC_CTA },
        { q:'What is partial loss of working capacity coverage?', kw:['partial disability coverage'],
          a:'A policy rider that allows partial payment of the benefit, for example 25% or 50%, if the insured is able to return to work at a reduced capacity.' },
        { q:'Does a self-employed person in a physical profession need special loss of working capacity coverage?', kw:['self-employed physical profession'],
          a:'Yes, self-employed people in physical professions need a precise occupation definition that covers physical injury, to joints or muscles, that prevents them from performing their job.' + GENERIC_CTA },
        { q:'Can you receive loss of working capacity payments from both National Insurance and the insurance company?', kw:['national insurance and private insurer'],
          a:'Yes, there is nothing preventing you from receiving an annuity from National Insurance (general disability or work-injury benefits) and compensation from the private insurance company at the same time.' },
        { q:'What is the waiting period in loss of working capacity insurance?', kw:['waiting period disability insurance'],
          a:'A period set in advance in the policy, usually between 30 and 90 days, from the start of incapacity until the insurance begins paying the monthly benefit.' },
        { q:'How do you choose the right waiting period for loss of working capacity insurance?', kw:['choosing waiting period'],
          a:'A short waiting period, like 30 days, suits someone with no accumulated sick days. A longer waiting period comes with a significantly cheaper premium.' + GENERIC_CTA },
        { q:'Does a loss of working capacity policy cover illnesses that existed before purchase?', kw:['pre-existing conditions'],
          a:'Usually not. Insurance companies exclude pre-existing conditions that were known at the time of joining the policy.' },
        { q:'What is the difference between a premium-waiver savings rider and a standard loss of working capacity policy?', kw:['premium waiver savings rider'],
          a:'A premium-waiver savings rider ensures the insurance company continues depositing into your pension savings (contributions) while you are receiving the monthly benefit, so your pension is not harmed.' + GENERIC_CTA },
        { q:'What is increased compensation in loss of working capacity insurance?', kw:['increased compensation disability'],
          a:'A rider that allows you to receive a monthly benefit higher than 75% of average income, available in some specific policies.' },
        { q:'What is the difference between disability coverage through the pension fund and a private policy?', kw:['pension disability coverage vs private'],
          a:'Coverage through the pension fund is usually more limited, while a private policy allows specific adjustments to your occupation and an optimal definition of income, especially for doctors and high-tech employees.' + GENERIC_CTA },
        { q:'How much does loss of working capacity insurance cost?', kw:['cost of disability insurance'],
          a:'The cost is derived from your occupation, your age, the benefit amount purchased, the profession definition, and additional extensions such as the premium-waiver rider.' + GENERIC_CTA },
        { q:'Does loss of working capacity insurance cover dismissal due to a health condition?', kw:['dismissal due to health condition'],
          a:'No, loss of working capacity insurance only covers being prevented from working due to a medical problem, not a state of unemployment.' },
        { q:'Do loss of working capacity policies update automatically according to the insured\'s salary?', kw:['automatic update by salary'],
          a:'No, the insured must update the coverage amount themselves to avoid creating "underinsurance" - a situation where the insurance company pays less than the current salary.' + GENERIC_CTA },
        { q:'Do you need an occupational physician to file a loss of working capacity claim?', kw:['occupational physician'],
          a:'Yes, an opinion from an occupational physician or specialist is an essential component for proving inability to work to the insurance company.' },
        { q:'What is the maximum benefit period in a loss of working capacity policy?', kw:['maximum benefit period'],
          a:'The length of time during which the insurance company will pay the benefit, usually until retirement age (65, 67, or 70, depending on the policy).' },
        { q:'Does loss of working capacity insurance cover a high-tech employee\'s period of unpaid leave?', kw:['unpaid leave disability insurance'],
          a:'Most policies do not pay a benefit during a period in which the insured is on unpaid leave and not actually working, even if they have a medical problem.' },
        { q:'Do loss of working capacity policies cover cases of depression or burnout?', kw:['depression','burnout coverage'],
          a:'Yes, but under strict limitations, and sometimes approval from an occupational psychiatrist is required to prove total inability to work.' + GENERIC_CTA },
        { q:'What happens to a self-employed insured who can only work partially after a medical event?', kw:['partial ability to work after medical event'],
          a:'If they purchased a partial loss-of-working-capacity rider, they will receive proportional compensation from the insurance company based on the decrease in income.' },
        { q:'Are there loss of working capacity policies that pay out for car accidents?', kw:['car accident disability insurance'],
          a:'Yes, but the compensation is weighed against possible payouts under the Road Accident Victims Compensation Law, and Tal will make sure there is no unnecessary overlap between the coverages.' + GENERIC_CTA },
        { q:'Can an insurance company require the insured to undergo professional retraining before paying a benefit?', kw:['professional retraining requirement'],
          a:'If the insured has a policy with a full occupational definition, the insurance company cannot require them to retrain for another profession as a condition for payment.' + GENERIC_CTA },
        { q:'How is a loss of working capacity benefit taxed?', kw:['taxation of disability benefit'],
          a:'The monthly benefit is exempt from income tax, up to a certain ceiling that is updated from time to time under the Income Tax Ordinance.' },
        { q:'What is a critical illness rider added to loss of working capacity insurance?', kw:['critical illness rider addition'],
          a:'A rider that provides a one-time sum or additional compensation upon diagnosis of a critical illness, helping to cover expenses during a challenging medical period.' + GENERIC_CTA },
        { q:'Does loss of working capacity insurance cover cosmetic surgery?', kw:['cosmetic surgery coverage'],
          a:'No, the policy does not cover absence from work resulting from elective or cosmetic surgeries that are not medical in nature.' },
        { q:'When should a self-employed person in a physical profession activate their loss of working capacity policy?', kw:['when to activate policy'],
          a:'Immediately upon completion of the waiting period set in the policy, for example 30 or 90 days from the start of incapacity.' },
        { q:'Do pension management fees affect the size of a loss of working capacity benefit?', kw:['pension management fees and disability benefit'],
          a:'No, the benefit amount does not depend on management fees; it is derived from the insured\'s salary and the amount purchased in the rider.' },
        { q:'How is the income of a high-tech employee who combines stock compensation and salary counted in loss of working capacity insurance?', kw:['stock compensation and base salary'],
          a:'Insurance companies usually refer to the fixed monthly salary as it appears on the payslip, and do not include bonuses or stock in calculating insured income, unless defined otherwise in advance.' + GENERIC_CTA },
        { q:'Do basic loss of working capacity policies for doctors include coverage for illnesses like cancer?', kw:['cancer coverage for doctors'],
          a:'Yes, critical illness and ongoing disability due to illness are covered as part of the standard policy, not just functional injury.' },
        { q:'What is a dual claim against personal accident insurance and loss of working capacity insurance?', kw:['dual claim personal accident and disability'],
          a:'An insured can hold both personal accident insurance, which pays for hospitalization days, and also activate loss of working capacity insurance after the waiting period ends - the two coverages do not contradict each other.' },
        { q:'What is the 75% limit in loss of working capacity insurance?', kw:['75 percent limit'],
          a:'Insurance companies will not compensate beyond 75% of monthly income, in order to maintain an incentive for the insured to return to work when able.' },
        { q:'What unique riders do entrepreneurs and high-tech employees need in loss of working capacity insurance?', kw:['unique riders for high-tech'],
          a:'A precise professional definition for project managers and software engineers, and a premium-waiver rider ensuring continued contributions to their study fund (Keren Hishtalmut) and pension while receiving a benefit.' + GENERIC_CTA },
        { q:'Can students get loss of working capacity insurance?', kw:['students disability insurance'],
          a:'Usually basic policies or personal accident insurance can be purchased to protect against accidents during studies, but full compensation for future loss of income is limited at this stage.' },
        { q:'Does loss of working capacity insurance cover absence due to fertility treatments?', kw:['fertility treatments coverage'],
          a:'Absence resulting from fertility treatments or a normal pregnancy is not covered by loss of working capacity insurance, unless it involves an unusual medical complication that completely prevents work.' },
        { q:'Does a high-tech employee\'s loss of working capacity policy cover a situation where they cannot work even from home?', kw:['working from home coverage'],
          a:'Yes, if their medical condition prevents them from working entirely, even from home, they are entitled to full compensation according to the policy terms.' },
        { q:'What is long-term care insurance, and is it part of loss of working capacity insurance?', kw:['long-term care vs disability insurance'],
          a:'No, these are two completely different coverages. Long-term care insurance covers a situation where a person cannot perform basic daily activities, while loss of working capacity insurance relates to the ability to earn and work.' + GENERIC_CTA },
        { q:'Can I check whether I have duplicate loss of working capacity insurance?', kw:['duplicate disability insurance'],
          a:'Yes, you can check this through the Finance Ministry\'s "Har HaBituach" website or with the help of a pension agent - Tal would be glad to go over this with you and make sure there is no unnecessary duplication between your policies.' + GENERIC_CTA },
        { q:'Do doctors need to be insured for death as well, not just loss of working capacity?', kw:['death coverage for doctors','life insurance'],
          a:'Yes, loss of working capacity insurance does not cover death. Like any salaried or self-employed person, doctors also need separate life (term) insurance to financially protect their family.' + GENERIC_CTA },
        { q:'Is a high-tech employee\'s loss of working capacity insurance valid while staying abroad?', kw:['valid abroad'],
          a:'In most cases yes, but this requires proper approval and medical follow-up in accordance with the terms of the specific policy.' },
        { q:'What is the definition of "reasonable occupation" for a self-employed person in a physical profession?', kw:['reasonable occupation definition'],
          a:'Work suited to the insured\'s education, training, and experience, which they are able to return to despite the injury they experienced.' },
        { q:'How does a loss of working capacity claim work for a self-employed person?', kw:['self-employed disability claim'],
          a:'The self-employed person submits medical documents, a claim form, and profit-and-loss reports or tax assessments, to prove the extent of the income decline resulting from the injury.' + GENERIC_CTA },
        { q:'What is a fixed-expenses rider for a self-employed person\'s business in loss of working capacity insurance?', kw:['fixed expenses rider business'],
          a:'Dedicated coverage for self-employed business owners, compensating the business for fixed expenses like rent and property tax in the event of the business owner\'s loss of working capacity.' + GENERIC_CTA },
        { q:'Do disability insurance policies for doctors get more expensive with age?', kw:['premium increases with age','cost rises with age'],
          a:'Yes, the cost of the insurance coverage increases gradually as you get older, and in line with any updates to your health status.' },
        { q:'Does disability insurance cover syndromes like fibromyalgia?', kw:['fibromyalgia'],
          a:'Yes, but these are complex claims requiring continuous medical monitoring and sufficient professional documentation to prove the inability to work.' + GENERIC_CTA },
        { q:'Why is it important to combine disability insurance with your pension fund?', kw:['combine with pension'],
          a:'The pension fund provides only basic, partial disability coverage, while private insurance supplements it up to 75% of your salary and provides protection tailored to your specific profession.' + GENERIC_CTA },
        { q:'What role does the insurance agent play during a disability claim?', kw:["agent's role in a claim"],
          a:'The agent accompanies the insured party in dealings with the insurance company, helps submit the required documents, and ensures full realization of their medical rights.' + GENERIC_CTA },
        { q:'Is a doctor appointed by the insurance company required in a disability claim?', kw:["company's doctor","insurer's doctor"],
          a:"Sometimes yes, insurance companies send the insured for an additional assessment with a doctor of their own choosing as part of reviewing the claim." },
        { q:'Can a self-employed person in a physical profession continue depositing into managers insurance while receiving disability benefits?', kw:['deposits while receiving benefits'],
          a:'Yes, if they purchased a premium waiver rider, the insurance company will continue making the deposits on their behalf, to maintain continuity of the pension savings.' + GENERIC_CTA },
        { q:'What is a medical questionnaire in life insurance and why is it important to fill it out honestly?', kw:['medical questionnaire'],
          a:'A document in which you report your health condition before purchasing the policy. Filling it out dishonestly can cause the insurance company to cancel the policy or deny a future claim.' + GENERIC_CTA },
        { q:'What happens if you conceal medical information on the questionnaire when purchasing insurance?', kw:['concealing medical information'],
          a:'The insurance company may cancel the policy retroactively or deny a claim related to the concealed information, even years after the policy was purchased.' },
        { q:'What is the medical underwriting period and why does it take time?', kw:['medical underwriting'],
          a:'The process in which the insurance company reviews the medical questionnaire (and sometimes requires additional tests) before approving the policy and its final terms.' },
        { q:'Can you cancel an insurance policy shortly after purchase without penalty?', kw:['cancel policy without penalty'],
          a:"Yes, there's usually a short cancellation period from receipt of the policy during which you can cancel and receive a full refund of the premium paid, with no penalty." + GENERIC_CTA },
        { q:'How long does the penalty-free cancellation period last for life and health insurance?', kw:['how long to cancel policy'],
          a:"The length of the period is set by regulation and varies between types of insurance - Tal will tell you exactly how much time you have for the specific policy you're considering." + GENERIC_CTA },
        { q:"What's the difference between group and private health insurance regarding the medical questionnaire?", kw:['group vs private questionnaire'],
          a:"In group insurance through the workplace, the medical questionnaire is usually shortened or doesn't exist at all. In individual private insurance, a more detailed questionnaire is required that affects the policy terms." },
        { q:'What is a medical exclusion in a health insurance policy?', kw:['medical exclusion'],
          a:'A clause in the policy stating that a certain medical condition that existed before joining will not be covered, even if the rest of the policy is in full effect.' },
        { q:'Can a medical exclusion be removed from an existing policy after a few years?', kw:['remove exclusion'],
          a:'In some cases, and after a period without new medical events, you can approach the insurance company and request a review of the exclusion. Tal can guide you through this request.' + GENERIC_CTA },
        { q:"What's the difference between structure-only home insurance and structure-plus-contents insurance?", kw:['structure and contents'],
          a:"Structure insurance covers the apartment's walls and fixed systems. Contents insurance covers the furniture, appliances, and personal belongings inside the home." },
        { q:'What should you check before renewing home insurance every year?', kw:['check before renewing home insurance'],
          a:'Make sure the insured sum still matches the actual value of the home and its contents, and check whether terms have changed or better price quotes are available in the market.' + GENERIC_CTA },
        { q:'Does home insurance cover water damage from a burst water heater?', kw:['water heater damage'],
          a:'In most policies, yes - sudden and unexpected water damage (like a burst water heater) is covered, but you should verify this against your specific policy.' + GENERIC_CTA },
        { q:"What's the difference between mandatory car insurance and comprehensive car insurance?", kw:['mandatory vs comprehensive car insurance'],
          a:'Mandatory insurance is legally required and covers bodily injury only. Comprehensive insurance is private insurance that adds coverage for property damage, theft, and damage to your own vehicle.' },
        { q:'Does comprehensive car insurance cover car theft?', kw:['car theft coverage'],
          a:'Yes, this is one of the main coverages in comprehensive insurance, usually subject to installation of standard anti-theft security devices in the vehicle.' },
        { q:'What is a young driver rate in car insurance and why is it more expensive?', kw:['young driver car insurance'],
          a:'An increased rate that applies to young drivers due to higher accident statistics at these ages, which significantly raises the insurance premium.' },
        { q:'What is professional liability insurance and who needs it?', kw:['professional liability insurance'],
          a:'Insurance that protects self-employed professionals (like accountants, consultants, designers) against a claim from a client alleging they suffered damage as a result of faulty advice or service.' + GENERIC_CTA },
        { q:"What's the difference between employer's liability insurance and third-party insurance?", kw:["employer's liability vs third-party"],
          a:"Employer's liability covers bodily injury to your employee during work. Third-party insurance covers bodily injury or property damage caused to a stranger who is not an employee or customer." },
        { q:'Is a self-employed person legally required to have professional liability insurance?', kw:['required professional liability'],
          a:"For most professions, it's not a blanket legal requirement, but in certain professions (like lawyers and accountants) there is a requirement from the regulating professional body." + GENERIC_CTA },
        { q:"What happens if a client sues a business owner who doesn't have professional liability insurance?", kw:['sued without liability insurance'],
          a:'The business owner is exposed to paying compensation out of their own pocket, including legal costs, with no backing from an insurance company.' },
        { q:'What is an independent insurance agent compared to a single-company agent?', kw:['independent agent'],
          a:"An independent agent works with all insurance companies in the market and chooses the most cost-effective solution for you. An agent tied to one company can only offer that company's products." },
        { q:"How does an insurance agent make money if I don't pay them directly?", kw:['how agents earn money'],
          a:"The agent receives a commission from the insurance company for managing your policy, and doesn't charge you any additional payment beyond the premium you already pay." },
        { q:'Is there a price difference between buying a policy through an agent versus directly from the company?', kw:['agent price vs direct'],
          a:"Usually there's no difference in the base price, since the agent's commission is paid by the insurance company and isn't added to your premium. However, going through an agent gets you personal guidance with claims and choosing the right plan." + GENERIC_CTA },
        { q:'What is a loan against a life insurance policy with cash value?', kw:['loan against policy'],
          a:'The option to receive a loan from the insurance company against money already accumulated in a savings policy, at a predetermined interest rate, without redeeming the policy itself.' + GENERIC_CTA },
        { q:"What happens if you don't repay a loan taken against an insurance policy?", kw:['not repaying policy loan'],
          a:"The accrued interest is deducted from the policy's own cash value, and without actual repayment of the loan it can significantly erode the amount remaining in your policy." },
        { q:'Can a pregnant woman purchase new health insurance during pregnancy?', kw:['insurance while pregnant'],
          a:"In most cases yes, but the pregnancy itself and related complications usually won't be covered in a new policy purchased during it, since it's considered a known pre-existing condition." + GENERIC_CTA },
        { q:'Does health insurance cover pregnancy or childbirth complications?', kw:['pregnancy complications coverage'],
          a:'A policy purchased before the pregnancy usually does cover complications, but a new policy purchased during an existing pregnancy usually does not.' },
        { q:'What is umbrella insurance for business owners and how is it different from regular insurance?', kw:['umbrella insurance for business'],
          a:'An additional layer of insurance that provides coverage beyond the limits of regular policies (like professional liability or third-party), for claims involving unusually large amounts.' + GENERIC_CTA },
        { q:'How do you update the insured sum after renovating or expanding your home?', kw:['update insurance after renovation'],
          a:'Contact your insurance agent and update the value of the renovated structure, so the insured sum reflects the true cost to rebuild the home in case of damage.' + GENERIC_CTA },
        { q:'What happens if you forget to notify the insurance company about a home renovation?', kw:['forgot to report renovation'],
          a:'In the event of damage, the insurance company may pay only partial compensation, based on the ratio between the old insured sum and the actual updated value of the structure (underinsurance).' + GENERIC_CTA },
        { q:'Is there dedicated insurance for jewelry or valuable items at home?', kw:['jewelry insurance'],
          a:'Yes, you can add a dedicated rider to your home policy for valuables above a certain amount, sometimes subject to a valuation and storage conditions.' + GENERIC_CTA },
        { q:'What is group insurance through the workplace and what happens to it when you leave?', kw:['group insurance leaving job'],
          a:'Insurance purchased at discounted rates for a group of employees at a workplace, which usually ends or becomes significantly more expensive the moment the employee leaves the workplace.' },
        { q:'Can you continue group health insurance as private insurance after leaving your job?', kw:['convert group to private'],
          a:'Sometimes yes, subject to a conversion right granted by the policy within a limited time from the date of leaving, though the terms and price may change.' + GENERIC_CTA },
        { q:"What's the difference between private long-term care insurance and long-term care insurance through the health fund?", kw:['private vs health fund long-term care'],
          a:'Long-term care insurance through the health fund is usually cheaper but has lower compensation caps and terms that renew every few years. Private insurance is more expensive but guarantees fixed terms for life.' + GENERIC_CTA },
        { q:'Does long-term care insurance cover home care or only institutional care?', kw:['home care coverage'],
          a:'Most policies cover both home-based long-term care and institutional hospitalization, based on the level of dependency in daily activities determined by the medical assessment.' },
        { q:'What is the qualifying period in long-term care insurance and why is it relatively long?', kw:['qualifying period long-term care'],
          a:"A period from the date of purchasing the policy during which a long-term care condition resulting from a pre-existing illness is still not covered - it's relatively long to prevent people from buying insurance only after discovering an illness." },
        { q:'How do you choose between several insurance quotes I received from multiple agents?', kw:['comparing insurance quotes'],
          a:"Don't look only at the monthly price - compare the scope of coverage, exclusions, waiting periods, and the financial stability of the insurer. Tal checks all of these together for you before making a recommendation." + GENERIC_CTA },
        { q:'What is cyber insurance for a small business and who needs it?', kw:['cyber insurance'],
          a:'Insurance that covers businesses against damages from computer break-ins, data theft, or ransomware attacks, including data recovery costs and notifying affected customers.' + GENERIC_CTA },
        { q:'Does a small business that runs a website need cyber insurance?', kw:['cyber insurance small business website'],
          a:'Yes, even small businesses are exposed to cyberattacks and customer data leaks, and dedicated insurance can cover the costs of handling the incident and the accompanying legal exposure.' + GENERIC_CTA },
        { q:'What is pet insurance (veterinary insurance) and what does it cover?', kw:['pet insurance'],
          a:'A policy that covers veterinary treatment costs, surgeries, and hospitalizations for your pet, similar to private health insurance but for pets.' },
        { q:'What is event insurance (wedding, bar mitzvah) and what does it cover?', kw:['event insurance'],
          a:'Insurance that covers damages or cancellation of a planned event due to unforeseen reasons, such as extreme weather, illness of the hosts, or damage to the venue.' + GENERIC_CTA },
        { q:'What is flight or trip cancellation insurance for travel abroad?', kw:['trip cancellation insurance'],
          a:'Coverage that compensates for non-refundable costs (flights, hotels) if you have to cancel a planned trip for a justified reason such as sudden illness.' + GENERIC_CTA },
        { q:'What is Directors and Officers (D&O) insurance?', kw:['directors and officers insurance','D&O insurance'],
          a:'Insurance that protects executives and senior officeholders in a company against personal lawsuits over decisions they made in their managerial role.' + GENERIC_CTA },
        { q:'Who needs directors and officers insurance?', kw:['who needs D&O'],
          a:'Mainly executives and officeholders at public companies or large private companies, but nonprofits and startups may also need this coverage as they grow.' + GENERIC_CTA },
        { q:'What is marine cargo insurance for import/export business owners?', kw:['marine cargo insurance'],
          a:'Insurance that covers damage or loss of goods during sea, air, or land transport, from the point of origin to the final destination.' + GENERIC_CTA },
        { q:'What is product liability insurance and who needs it?', kw:['product liability insurance'],
          a:'Insurance that protects manufacturers and distributors against claims for damage caused to a customer as a result of a defect in a product they sold or manufactured.' + GENERIC_CTA },
        { q:'What is business interruption insurance (loss of profits) and when is it relevant?', kw:['business interruption insurance'],
          a:'Insurance that compensates for the business\'s lost income during a period when it cannot operate due to covered damage, such as a fire that damaged the business premises.' + GENERIC_CTA },
        { q:"What's the difference between business property insurance and business interruption insurance?", kw:['business property vs interruption'],
          a:"Property insurance covers the physical damage to the equipment and the structure itself. Business interruption insurance covers the loss of income caused by that same damage while the business is closed for repairs." },
        { q:'What is motorcycle and scooter insurance and how is it different from regular car insurance?', kw:['motorcycle insurance'],
          a:'Dedicated insurance for two-wheeled vehicles, with rates that vary based on engine size and the higher accident statistics among motorcycle riders.' + GENERIC_CTA },
        { q:'What is boat insurance (boat, yacht)?', kw:['boat insurance','yacht insurance'],
          a:'Coverage for physical damage to the vessel itself, as well as liability for damage caused to third parties while using it.' },
        { q:"How do you verify that the insurance company I'm considering is financially stable?", kw:['insurer financial stability'],
          a:'You can check credit ratings from international and local rating agencies, and also verify that the company is supervised by the Capital Market, Insurance and Savings Authority.' + GENERIC_CTA },
        { q:'What happens to my policy if the insurance company runs into financial trouble?', kw:['insurer in financial trouble'],
          a:"The regulator's close supervision of insurance companies is designed to prevent such a situation, but regulatory protection mechanisms also exist to safeguard policyholders' rights in extreme cases." },
        { q:'Can you switch between health insurance companies without losing continuity of coverage?', kw:['switching companies without losing continuity'],
          a:'Yes, in most cases you can switch to another company while keeping similar terms, provided you present proof of continuous coverage from the previous policy.' + GENERIC_CTA },
        { q:'What is a certificate of insurance continuity and why is it important to keep it?', kw:['certificate of insurance continuity'],
          a:'A document proving there was no significant gap in your insurance coverage, which avoids the need to fill out a new medical questionnaire or serve an additional qualifying period with a new insurer.' },
        { q:'What is travel insurance abroad for extreme sports like skiing or diving?', kw:['travel insurance extreme sports'],
          a:'A dedicated extension to standard travel insurance, covering higher-risk activities not automatically included in a standard travel policy.' + GENERIC_CTA },
        { q:'What is travel insurance abroad for someone with a pre-existing medical condition?', kw:['travel insurance pre-existing condition'],
          a:'You can usually purchase a dedicated extension that also covers worsening of an existing medical condition, in exchange for a higher premium and after filling out a detailed medical questionnaire.' + GENERIC_CTA },
        { q:"What happens if I get sick abroad and don't have travel insurance?", kw:['sick abroad without insurance'],
          a:"You're required to pay the full cost of medical treatment in the foreign country out of pocket, which can reach very high amounts, and sometimes you won't even be allowed to leave until payment is arranged." },
        { q:'What is medical evacuation insurance when traveling abroad?', kw:['medical evacuation insurance'],
          a:'Coverage for the very high cost of a special air evacuation and return to Israel for continued medical treatment, in the event of a serious incident abroad.' },
        { q:'What is health insurance for Israeli students studying abroad?', kw:['student insurance abroad'],
          a:'A dedicated policy for extended stays abroad, different from short-term travel insurance, and sometimes required as a condition of admission by the educational institutions themselves.' + GENERIC_CTA },
        { q:'What is insurance for volunteers or temporary workers abroad?', kw:['volunteer insurance abroad'],
          a:'Dedicated coverage tailored to extended stays under non-routine conditions, usually including coverage for medical evacuation and cancellation of planned activities.' + GENERIC_CTA },
        { q:'What is mortgage insurance compared to regular life insurance?', kw:['mortgage insurance vs regular life insurance'],
          a:'Mortgage insurance only pays off the remaining loan balance to the bank in the event of death. Regular life insurance pays a sum to the beneficiaries you chose, regardless of any debt.' },
        { q:'What is decreasing term mortgage insurance and why does it suit a mortgage?', kw:['decreasing term mortgage insurance'],
          a:'A type of insurance where the coverage amount decreases over time in parallel with the declining mortgage balance, which lowers the monthly premium cost over the life of the loan.' },
        { q:'Is life insurance legally required as a condition for getting a mortgage?', kw:['mandatory life insurance mortgage'],
          a:'Yes, banks require life insurance (and mortgage structure insurance) as a condition for mortgage approval, but you are entitled to choose the insurance company independently rather than only through the bank.' + GENERIC_CTA },
        { q:'Is it better to get mortgage insurance through the bank or through an outside agent?', kw:['mortgage insurance bank or agent'],
          a:"You can usually get better terms and price through an outside agent than through the insurance the bank itself offers, since the bank doesn't always compete for the best price." + GENERIC_CTA },
        { q:'What is mandatory mortgage structure insurance and how is it different from regular home insurance?', kw:['mandatory mortgage structure insurance'],
          a:'This is basic coverage for the apartment structure required by the bank as a condition for the mortgage, while comprehensive home insurance also includes coverage for contents and third-party liability.' },
        { q:'How do you choose the right life insurance amount if I have a mortgage and children?', kw:['insurance amount mortgage and children'],
          a:'The amount should cover the remaining mortgage balance plus an amount that will let your family maintain a reasonable standard of living for years, not just pay off the bank debt.' + GENERIC_CTA },
        { q:'What is joint life insurance for couples compared to two separate policies?', kw:['joint life insurance'],
          a:'A joint policy pays compensation the first time one spouse passes away and then ends, while two separate policies guarantee separate, full coverage for each of them.' + GENERIC_CTA },
        { q:'Which is better - joint life insurance or two separate policies for a couple?', kw:['joint vs separate policies'],
          a:'Two separate policies are usually preferable, since they continue to protect the surviving spouse even after the first death event.' + GENERIC_CTA },
        { q:'What is an accidental death rider (car accident) in life insurance?', kw:['accidental death rider'],
          a:'An extension that doubles or increases the compensation amount if death occurred as a result of a car accident rather than a natural cause or illness.' + GENERIC_CTA },
        { q:'What is an accidental disability rider in a life insurance policy?', kw:['accidental disability rider'],
          a:'An extension that provides a one-time cash payment also in the case of permanent disability resulting from an accident, not only in the case of death.' },
        { q:'What is term life insurance compared to whole life insurance?', kw:['term life vs whole life'],
          a:'Term insurance is cheaper and covers a predefined number of years. Whole life insurance is more expensive but guarantees a certain payout eventually, usually with a savings component.' + GENERIC_CTA },
        { q:'Are most insurance policies in Israel whole life or term?', kw:['common insurance type in Israel'],
          a:'In most cases in Israel, renewable term (risk) insurance is customary (cheap but gets more expensive with age), while whole life insurance with a savings component is less common and significantly more expensive.' },
        { q:'What is health insurance for tourists and foreign workers in Israel?', kw:['tourist and foreign worker insurance'],
          a:'Dedicated health insurance legally required for those not eligible for national health insurance, such as foreign workers and tourists staying in Israel for an extended period.' },
        { q:'What is Israeli academic student insurance and what does it include?', kw:['Israeli student insurance'],
          a:'A discounted policy offered through student associations, providing basic coverage for medications, tests, and private medical care during the study period.' + GENERIC_CTA },
        { q:"What is private dental insurance and what does it cover that the health fund doesn't?", kw:['private dental insurance'],
          a:'Coverage for significant dental treatments like crowns, implants, and orthodontics, most of which are not included in the basic national health basket.' + GENERIC_CTA },
        { q:'Should I buy separate dental insurance or save on my own for future treatments?', kw:['saving instead of dental insurance'],
          a:'It depends on your family history and current dental condition - in cases of high risk for expensive treatments, dedicated insurance can save a lot of money in the long run.' + GENERIC_CTA },
        { q:'What is vision and laser eye surgery insurance?', kw:['vision laser insurance'],
          a:'Some private policies include a contribution toward the cost of laser vision correction surgery or contact lenses and glasses, beyond the basic coverage from the health fund.' },
        { q:'What is private fertility insurance and what does it add beyond what the health fund covers?', kw:['private fertility insurance'],
          a:'Extended coverage for fertility treatments beyond the quota provided by the health fund, including complementary treatments or additional treatment cycles.' + GENERIC_CTA },
        { q:'What is health insurance for children born with a birth defect?', kw:['birth defect insurance'],
          a:'Insurance purchased before birth (during pregnancy) may include coverage for birth defects discovered after birth, unlike insurance purchased only after the defect is already known.' + GENERIC_CTA },
        { q:"What is health insurance for a child before they're born (during pregnancy)?", kw:['insuring a child before birth'],
          a:'You can purchase a policy for the future baby already during the pregnancy stage, which ensures broader coverage and better terms compared to purchasing after birth.' + GENERIC_CTA },
        { q:'What is long-term care insurance for children or young family members?', kw:['long-term care insurance for children'],
          a:'Long-term care insurance is not common for young people since the long-term care risk is very low at a young age, but dedicated policies exist for exceptional cases of serious congenital illnesses.' },
        { q:'What is critical illness insurance and how is it different from regular health insurance?', kw:['critical illness insurance different'],
          a:'Critical illness insurance pays a one-time sum upon diagnosis of an illness from a closed list of illnesses, regardless of the actual treatment cost - unlike health insurance, which reimburses actual expenses.' + GENERIC_CTA },
        { q:'What is the list of critical illnesses covered under a critical illness policy?', kw:['critical illness list'],
          a:'A closed list defined in advance in the policy (such as cancer, heart attack, stroke), and any illness not on the list does not qualify for compensation under this coverage.' },
        { q:'What is organ transplant insurance and what does it add beyond the health basket?', kw:['organ transplant insurance'],
          a:"Most private insurance policies include funding for transplants abroad and coverage for medications in cases where the public health basket doesn't provide an adequate or fast enough response." + GENERIC_CTA },
        { q:'What is insurance for medications outside the health basket?', kw:['medication insurance outside health basket'],
          a:'Coverage for innovative or expensive medications not yet included in the national health basket, which can save very large sums in the event of an illness requiring expensive drug treatment.' + GENERIC_CTA },
        { q:'What are surgeries abroad under private health insurance?', kw:['surgery abroad insurance'],
          a:"Coverage for funding surgery and medical treatment outside Israel, usually in cases where the needed treatment isn't available in the country or involves too long a wait." + GENERIC_CTA },
        { q:'What is a second medical opinion that private insurance offers?', kw:['second opinion'],
          a:'A service that lets you consult an additional specialist doctor, sometimes international, before making a decision about significant medical treatment, funded by the insurance company.' },
        { q:'What is health insurance for seniors and why is it more expensive?', kw:['senior health insurance'],
          a:'As age increases, so does the statistical medical risk, which is why the insurance premium for seniors is higher and sometimes includes entry restrictions.' + GENERIC_CTA },
        { q:'Is there a maximum age for purchasing new private health insurance?', kw:['maximum age health insurance'],
          a:'Yes, most insurance companies have an age cap for initial enrollment in a new policy, but someone already insured can continue their existing policy beyond that age.' },
        { q:'What is group long-term care insurance through the health fund compared to individual private long-term care insurance?', kw:['group vs individual long-term care'],
          a:'Group insurance through the health fund is cheaper at first but renews every few years and may become significantly more expensive or be discontinued. Private insurance is more expensive but has guaranteed fixed terms.' + GENERIC_CTA },
        { q:"What happens to group long-term care insurance through the health fund if it's discontinued?", kw:['group long-term care discontinued'],
          a:'If the health fund decides to discontinue the group arrangement, insured members may be left with no long-term care coverage at all, unless they arrange supplementary private insurance in advance.' + GENERIC_CTA },
        { q:'What is the monthly long-term care insurance amount and how is it set correctly?', kw:['long-term care insurance amount'],
          a:"The monthly amount you'll receive if recognized as needing long-term care, which should be set according to the actual cost of long-term care at home or in an institution in your area." + GENERIC_CTA },
        { q:'What is the ADL (activities of daily living) test for determining long-term care status?', kw:['ADL test long-term care'],
          a:"A medical test that checks a person's ability to perform basic activities like bathing, dressing, and eating, and determines eligibility for long-term care benefits based on the results." },
        { q:'How many daily activities must a person be unable to perform to be considered in need of long-term care?', kw:['how many ADL activities'],
          a:'Policies generally require the inability to perform a certain number out of six defined daily activities, as a condition for recognition of long-term care status and payment of benefits.' },
        { q:'What is long-term care insurance with premium refund if unused?', kw:['premium refund long-term care'],
          a:'A more expensive type of policy that guarantees a refund of part of the premiums paid if the insured never reaches a long-term care condition by the end of the insurance period.' + GENERIC_CTA },
        { q:'What is supplementary mental health insurance?', kw:['mental health insurance'],
          a:'Coverage that extends psychological and psychiatric treatment beyond what the health fund covers, including a larger number of subsidized therapy sessions.' + GENERIC_CTA },
        { q:'What is health insurance that also covers complementary medicine (homeopathy, acupuncture)?', kw:['complementary medicine insurance','alternative medicine coverage'],
          a:'Some policies include limited reimbursement for complementary medicine treatments, in addition to conventional medicine, subject to an annual cap.' + GENERIC_CTA },
        { q:'What is private insurance for screening and preventive tests (annual checkup)?', kw:['annual checkup insurance','screening tests coverage'],
          a:'Coverage that funds blood tests, imaging, and periodic screening tests for prevention and early detection of diseases, beyond what is offered in the basic health basket.' + GENERIC_CTA },
        { q:'What is health insurance for professional athletes?', kw:['professional athlete insurance','sports injury coverage'],
          a:'Dedicated insurance that accounts for the high risk of recurring sports injuries, usually at a higher price and with terms specific to the sport.' + GENERIC_CTA },
        { q:'What is separate work accident insurance beyond National Insurance?', kw:['additional work accident insurance','workplace injury coverage'],
          a:'Supplementary coverage to the compensation provided by National Insurance for a workplace injury, which can provide higher and faster compensation than the state alone offers.' + GENERIC_CTA },
        { q:'What is insurance for self-employed people who work at heights or in hazardous jobs?', kw:['hazardous work insurance','high-risk occupation coverage'],
          a:'For high-risk occupations, the policy needs to be tailored specifically, sometimes at a higher premium or with specific exclusions for the hazardous activity.' + GENERIC_CTA },
        { q:'What is insurance for freelancers working with several clients at once?', kw:['freelancer insurance','self-employed coverage'],
          a:'A freelancer typically needs a combination of professional liability insurance, loss of working capacity insurance, and private health insurance - since there is no employer handling this on their behalf.' + GENERIC_CTA },
        { q:'What is insurance for people working from home (home office) covering equipment and data?', kw:['home office insurance','work from home equipment coverage'],
          a:'Insurance covering expensive work equipment (computers, monitors) kept at home rather than the office, which is sometimes not automatically covered under a standard home insurance policy.' + GENERIC_CTA },
        { q:'Does standard home insurance cover an employer\'s work equipment kept at home?', kw:['home insurance employer equipment','work equipment at home coverage'],
          a:'Not necessarily - if there is valuable equipment belonging to the employer at home, the policy should be checked and explicitly updated to make sure it is covered in case of damage or theft.' + GENERIC_CTA },
        { q:'What is contents insurance for a business run from home?', kw:['home business contents insurance','business equipment at home'],
          a:'A dedicated extension to standard home insurance that covers equipment and merchandise belonging to a business run from home, which are not covered under the standard household contents insurance.' + GENERIC_CTA },
        { q:'What is identity theft insurance?', kw:['identity theft insurance','identity fraud coverage'],
          a:'Coverage that helps pay legal costs and financial recovery expenses if someone uses your personal details to commit financial fraud.' + GENERIC_CTA },
        { q:'What is insurance against online credit card fraud?', kw:['online credit card fraud insurance','credit fraud coverage'],
          a:'Liability for fraudulent credit card transactions usually falls on the credit card company or bank, but insurance extensions exist that provide an extra layer of protection for exceptional cases.' },
        { q:'What is business travel insurance purchased by an employer for trips abroad?', kw:['business travel insurance','employer travel coverage'],
          a:'Insurance that an employer purchases for employees traveling abroad for work purposes, which usually also includes coverage for work equipment and medical evacuation if needed.' },
        { q:'Is an employee injured on a work trip abroad also covered by National Insurance?', kw:['injured on work trip abroad','overseas work injury'],
          a:'Yes, an injury during a work trip on the employer\'s behalf may be considered a workplace accident even if it occurred abroad, subject to a review of the exact circumstances.' + GENERIC_CTA },
        { q:'What is rental car insurance abroad, and why is it worth checking the coverage in advance?', kw:['rental car insurance abroad','car rental coverage'],
          a:'Credit card companies and travel cards sometimes offer partial coverage for rental cars, but it is important to confirm the deductible amount and full scope before the trip.' + GENERIC_CTA },
        { q:'What is a deductible in insurance, and how does it affect the premium?', kw:['insurance deductible premium','how deductible affects cost'],
          a:'The higher the deductible (the amount you pay yourself when filing a claim), the lower your monthly insurance premium, and vice versa.' + GENERIC_CTA },
        { q:'Should I choose a high deductible to save on the premium?', kw:['choosing high deductible','save money on premium'],
          a:'It depends on your ability to absorb that amount if an event occurs - if you have a financial safety cushion, a high deductible can save you significantly over the years.' + GENERIC_CTA },
        { q:'What is group insurance for employees of a large organization compared to individual private insurance?', kw:['group insurance large organization','employer group coverage'],
          a:'Large group insurance benefits from bargaining power and lower prices thanks to the large number of insured members, but the terms depend on the organization\'s decisions and may change over time.' },
        { q:'What is insurance for kibbutz or moshav members regarding health and life insurance?', kw:['kibbutz moshav insurance','cooperative settlement coverage'],
          a:'Members of kibbutzim and moshavim may have unique group insurance arrangements through the cooperative association, which are worth checking before purchasing a separate private policy.' + GENERIC_CTA },
        { q:'What is insurance for someone who only works seasonal or temporary jobs?', kw:['seasonal work insurance','temporary job coverage'],
          a:'A seasonal worker needs to ensure continuous insurance coverage between periods of employment, since long gaps can cause a loss of coverage or the need to fill out a new health declaration.' + GENERIC_CTA },
        { q:'What is insurance for someone working several part-time jobs at once?', kw:['multiple part-time jobs insurance','several jobs coverage'],
          a:'You should make sure the contributions and insurance coverage from two (or more) workplaces are consolidated into a single fund, so coverage is not scattered and full protection is not missed.' + GENERIC_CTA },
        { q:'What is supplementary employer-employee insurance for full disability in a hazardous job?', kw:['hazardous work disability insurance','employer supplementary disability coverage'],
          a:'Employers in hazardous industries (such as construction) may purchase additional insurance for their employees beyond National Insurance, to protect them in case of severe injury.' + GENERIC_CTA },
        { q:'What is contractors\' insurance (construction works insurance), and who is it for?', kw:['contractors insurance','construction works coverage'],
          a:'Insurance that covers damage to a construction project while it is underway, including damage to third parties resulting from the construction work itself.' + GENERIC_CTA },
        { q:'What is third-party insurance for renovation work in a private home?', kw:['third party insurance renovation','home renovation liability coverage'],
          a:'Coverage for damage that might be caused to neighbors or passersby as a result of renovation work being done in the home, which the contractor or homeowner should make sure to hold.' + GENERIC_CTA },
        { q:'Who is responsible for insurance during a renovation - the homeowner or the contractor?', kw:['who is responsible for renovation insurance','homeowner contractor insurance'],
          a:'Usually the contractor holds their own construction works insurance, but it is recommended that the homeowner confirm this in writing and also consider additional coverage of their own.' + GENERIC_CTA },
        { q:'What is insurance for private daycare centers and preschools?', kw:['daycare preschool insurance','childcare facility liability'],
          a:'Liability insurance that protects owners of private educational facilities against claims for injury or harm suffered by a child at their facility.' + GENERIC_CTA },
        { q:'What is insurance for private tutors or personal coaches (self-employed professions)?', kw:['private tutor insurance','personal coach liability'],
          a:'Self-employed people who provide direct personal service to clients (tutoring, coaching) typically need professional and third-party liability insurance tailored to the nature of their work.' + GENERIC_CTA },
        { q:'What is insurance for studio owners (yoga, Pilates, fitness)?', kw:['fitness studio insurance','yoga pilates studio coverage'],
          a:'Insurance combining professional and third-party liability, covering trainee injuries during classes as well as damage to the studio\'s equipment and premises.' + GENERIC_CTA },
        { q:'What is insurance for businesses hosting large crowds (restaurants, event halls)?', kw:['business insurance for public venues','restaurant event hall coverage'],
          a:'Insurance combining property coverage, liability toward customers injured on the premises, and loss-of-profits insurance if the business is forced to close due to damage.' + GENERIC_CTA },
        { q:'What is insurance for valuable photography or music equipment owned by artists and creators?', kw:['photography equipment insurance','musical instrument coverage'],
          a:'Dedicated coverage for valuable professional equipment (cameras, musical instruments) against theft, breakage, or damage, whether it is kept at home or taken out for work in the field.' + GENERIC_CTA },
        { q:'Does standard home insurance cover expensive professional photography equipment kept at home?', kw:['home insurance photography equipment','does home policy cover camera gear'],
          a:'Usually not in full - a dedicated rider for valuable professional items should be added, especially if the equipment leaves the house for shoots in the field.' + GENERIC_CTA },
        { q:'What is insurance against electronic equipment damage from sun exposure or natural disasters?', kw:['natural disaster electronics insurance','weather damage to appliances'],
          a:'Most contents policies include coverage for natural disaster damage (lightning, flooding) that causes electronic devices in the home to malfunction, subject to the specific policy terms.' },
        { q:'What is earthquake damage insurance in Israel, and who is it relevant for?', kw:['earthquake insurance Israel','seismic damage coverage'],
          a:'An extension to home insurance that covers structural damage caused by an earthquake, especially relevant for residents in areas of Israel with elevated seismic risk.' + GENERIC_CTA },
        { q:'What is war and hostile action damage insurance for private property?', kw:['war damage insurance','hostile action property coverage'],
          a:'In most cases in Israel, war and hostile action damage is covered by the Property Tax Fund (Mas Rechush, Israel\'s government compensation authority) rather than by the private insurance company itself.' },
// TRANSLATOR NOTE: "מס רכוש" refers to Israel's statutory Property Tax and Compensation Fund (a government war/terror-damage compensation body under the Tax Authority), not a US-style municipal property tax - translated with clarifying parenthetical to avoid confusion.
        { q:'How do you file a claim with the Property Tax Fund for war damage?', kw:['property tax fund claim','war damage claim Israel'],
          a:'The claim is filed directly with the Tax Authority (Property Tax Fund), not with the private insurance company, within a limited time period from the date of damage.' + GENERIC_CTA },
        { q:'What is insurance for jewelry and diamonds kept in a home safe?', kw:['jewelry safe insurance','diamond home insurance'],
          a:'A dedicated rider for valuable jewelry can be added to a home policy, sometimes conditional on the items being stored in an approved safe when not in use.' + GENERIC_CTA },
        { q:'What is collectibles insurance (art, coins, stamps)?', kw:['collectibles insurance','art coin stamp coverage'],
          a:'Dedicated insurance for collectors that covers damage, theft, or loss of significant-value collectible items, usually subject to a professional appraisal.' + GENERIC_CTA },
        { q:'What is supplementary personal accident insurance for children at school?', kw:['school accident insurance for children','student accident coverage'],
          a:'Group insurance that schools purchase for students, providing basic compensation for injury or an accident that occurred during school activity.' },
        { q:'What is supplementary insurance for children\'s sports clubs and summer camps?', kw:['sports club summer camp insurance','kids extracurricular coverage'],
          a:'Coverage similar to student insurance but dedicated to extracurricular activities, like clubs and summer camps, which are sometimes not covered by regular school insurance.' },
        { q:'What is bar/bat mitzvah or large family event cancellation insurance?', kw:['bar mitzvah cancellation insurance','family event cancellation coverage'],
          a:'Coverage similar to general event insurance, compensating for non-refundable costs if the event is cancelled for a justified reason such as illness or bereavement.' + GENERIC_CTA },
        { q:'What is insurance for gifts and valuable items purchased for an event (like an engagement ring)?', kw:['engagement ring insurance','valuable gift coverage'],
          a:'A single valuable item like a diamond ring can be insured under a separate rider, covering loss, theft, or damage even outside the home.' + GENERIC_CTA },
        { q:'How do I know if I have duplicate insurance across several policies I have purchased over the years?', kw:['duplicate insurance check','overlapping policies review'],
          a:'Tal conducts a comprehensive review of all your existing policies to identify overlapping coverage you are paying for twice, and make sure every premium shekel serves a unique purpose.' + GENERIC_CTA }
      ]},
      { key:'about', label:'🤖 Questions about Tuli & the Service', items:[
        { q:'What\'s your purpose?', kw:['what is your purpose','why are you here'],
          a:'My purpose is to help you get an initial handle on your money, insurance, and retirement plans. I\'m here to make complex information accessible and clear, answer pressing questions, and help you prepare in the best possible way for your professional meeting with Tal. I don\'t replace personalized human advice - I\'m your first step toward financial security.' },
        { q:'Does your service cost money?', kw:['does this cost money','is there a fee'],
          a:'The initial portfolio review and product matching is usually done at no direct cost to you, since we\'re compensated by the financial institutions. Complex retirement planning may involve a professional fee.' },
        { q:'Which insurance companies and investment houses do you work with?', kw:['which companies do you work with','insurance companies you work with'],
          a:'Tal works with all the leading insurance companies and investment houses in Israel. This allows him to stay objective and choose the best product for you.' },
        { q:'Are you a pension advisor or a pension agent?', kw:['advisor or agent','pension advisor vs agent'],
          a:'Tal is a licensed pension insurance agent and financial planner. That means he has an affiliation with the various companies\' products, but his professional duty is to match you with the most worthwhile solution.' },
        { q:'Is the information I share here secure?', kw:['is my information secure','privacy'],
          a:'Tuli itself doesn\'t store or collect any personal details - it only directs you to Tal\'s WhatsApp to continue there directly, just like any regular WhatsApp chat.' },
        { q:'How do I schedule an in-person or Zoom meeting with you?', kw:['schedule a meeting','book an appointment','zoom meeting'],
          a:'The simplest way is to click the button in the chat to go straight to WhatsApp, and arrange a time and meeting type that suits you there (in person or via Zoom).' },
        { q:'Can you tell me when I\'ll be able to retire?', kw:['when can I retire','retirement age'],
          a:'I can tell you that the official retirement age today is 67 for men and 62-65 for women (depending on birth year). To know whether you can afford to retire earlier, you\'ll need a comprehensive calculation with Tal.' },
        { q:'Are you an AI-based bot?', kw:['are you AI','artificial intelligence'],
          a:'No - I\'m a bot based on pre-set fixed rules, not artificial intelligence. I answer from a bank of answers that Tal prepared in advance, and I don\'t "make up" new answers.' },
        { q:'Can you give me a discount on management fees right now in the chat?', kw:['discount right now','lower my fees now'],
          a:'I can\'t change management fees directly from the chat, but Tal knows exactly what negotiating power we have with the companies and would be happy to do that for you.' },
        { q:'Do you give recommendations for buying specific stocks like Tesla or Nvidia?', kw:['stock recommendations','buy Tesla stock'],
          a:'No, I don\'t provide individual investment advice or recommendations for specific stocks. Management is done through diverse, regulated investment tracks matched to your risk profile.' },
        { q:'What\'s the next step I should take after talking with you?', kw:['next step','what now'],
          a:'The smartest step is to move to WhatsApp (there\'s a button for that in the chat) and schedule a no-obligation organizing meeting.' },
        { q:'Where is Tal\'s office, or is everything done over Zoom?', kw:['where is the office','in person or zoom'],
          a:'Tal offers flexible service - you can meet in person at the office in Rehovot, or hold convenient Zoom meetings from anywhere in the country at times that suit you.' },
        { q:'How do you stay in touch with me after I open a product?', kw:['stay in touch','ongoing follow-up'],
          a:'We don\'t disappear. Tal and the team perform periodic follow-ups on your portfolio, send updates, and are here for any change in your life or employment status.' },
        { q:'How long does an initial financial planning meeting take?', kw:['how long is the first meeting','initial meeting length'],
          a:'The first meeting usually lasts between 45 and 60 minutes, during which we map out your current situation in full and define your financial goals.' },
        { q:'Can the bot recommend a stock that will go up tomorrow morning?', kw:['stock tip for tomorrow','guess a winning stock'],
          a:'Definitely not. Nobody has a crystal ball, and as a bot I don\'t deal in guesswork or day trading. Tal focuses on a stable, long-term wealth-building strategy.' },
        { q:'Why shouldn\'t I manage my own insurance directly with the insurance companies?', kw:['manage my own insurance','handle it myself'],
          a:'Insurance companies are huge organizations with complicated language. When you work with Tal, you have a strong professional on your side who knows the system, represents you, and fights for your rights.' },
        { q:'Why pay a financial planner if everything is available online for free?', kw:['information is free online','why pay a planner'],
          a:'The information does exist, but tailoring it to your specific tax, family, and health situation requires expertise. One small mistake on an income tax form can cost you tens of thousands of shekels.' },
        { q:'How can I be sure you\'re objective and not recommending a company that pays you a higher commission?', kw:['are you objective','commission bias'],
          a:'Tal works with all the financial institutions in Israel and is legally and professionally obligated to act in the client\'s best interest. The various companies offer agents almost identical terms, so Tal\'s only real interest is for you to be satisfied and remain a client for years to come.' },
        { q:'What real-world experience does Tal actually have?', kw:['Tal\'s experience','how experienced is Tal'],
          a:'Tal is a financial planner, licensed pension insurance agent, and licensed retirement planner, with extensive experience guiding hundreds of clients, managing complex portfolios, and achieving significant cost reductions.' },
        { q:'What happens if Tal recommends an investment track and I lose money?', kw:['what if I lose money','investment loss'],
          a:'Investing in the capital market involves volatility. Tal doesn\'t promise short-term profits - he builds a long-term strategy matched to the risk level you approved, aiming to achieve a representative return over time.' },
        { q:'I\'d rather keep my money in real estate, why do I need the stock market?', kw:['real estate vs stock market','why not just real estate'],
          a:'Real estate is an excellent asset class, but it requires a large amount of capital, isn\'t liquid, and involves maintenance costs and varying taxation. Proper diversification includes both real estate and the liquid capital market.' },
        { q:'I\'ve heard about agents who disappear after you sign the policy with them, how do I know that won\'t happen with you?', kw:['agent disappears after signing','ongoing service guarantee'],
          a:'Tal\'s business model is based on long-term service and support. We hold periodic service meetings and are available to our clients at every decision point or claims event.' },
        { q:'Why won\'t the bank do this financial management for me for free?', kw:['why not use my bank','bank advisor free'],
          a:'A bank advisor doesn\'t have a holistic view - they don\'t see your insurance policies, pensions from previous workplaces, or your full retirement needs. In addition, they\'re limited to only the products the bank works with.' },
        { q:'If the bot knows everything, why do I need to schedule a meeting with Tal?', kw:['why meet Tal if bot knows everything','why not just chat'],
          a:'I (the bot) can provide general information and legal definitions. I can\'t analyze your medical condition, family needs, or perform complex tax planning - for that, you need Tal\'s expertise.' },
        { q:'A friend told me that savings policies are a bad product with double management fees, is that true?', kw:['double management fees','savings policy fees myth'],
          a:'Not at all. Savings policies don\'t have double management fees, and they offer huge advantages such as free switching between investment tracks without paying capital gains tax at that moment (tax deferral).' },
        { q:'Who guarantees that my money won\'t disappear or that the insurance company won\'t get hacked?', kw:['is my money safe','insurance company hacked'],
          a:'Your money isn\'t held by us - it\'s deposited directly into the trust accounts of the leading insurance and investment companies. These institutions are regulated by the state and secured at the highest levels.' },
        { q:'How do you get my data from the pension clearinghouse, do you need a password?', kw:['pension clearinghouse','do I need a password'],
          a:'No password needed. You sign a one-time, secure digital power of attorney, and the government system pulls all the information registered under your name within a few business days.' },
        { q:'How long does it take to see the money in my account after requesting a redemption from a savings policy?', kw:['withdraw savings policy','how long for redemption'],
          a:'According to Ministry of Finance regulations, insurance companies have up to 4 business days (excluding the start of the month) to transfer the funds to your bank account from the moment valid forms are received.' },
        { q:'Can Tal also help organize my car and home insurance?', kw:['car insurance','home insurance'],
          a:'Tal focuses on the financial core: pensions, finances, retirement planning, and personal insurance (health and life). We\'d be happy to refer you to professional partners who handle property and casualty insurance (car and home).' },
        { q:'I live in Eilat or up north, does Tal come to meetings anywhere in the country?', kw:['Eilat','northern Israel','anywhere in the country'],
          a:'Thanks to Zoom technology, Tal provides full advisory and planning services to clients anywhere in the country (and even to Israelis abroad) with a high level of availability and quality.' },
        { q:'What is a quarterly report and what am I supposed to do with it when it arrives by email?', kw:['quarterly report','what to do with report'],
          a:'It\'s a summary of the last three months of your savings (deposits, returns, and management fees). There\'s no need to worry or take action - Tal monitors this data for you on an ongoing basis.' },
        { q:'Can I schedule a meeting with you on Fridays or in the late evening?', kw:['Friday appointments','evening meetings'],
          a:'We try to accommodate working clients. You can schedule meetings in the evenings or on weekends too - just tell us what\'s most convenient for you on WhatsApp.' },
        { q:'What\'s the difference between beneficiaries and legal heirs in life insurance?', kw:['beneficiaries vs legal heirs','life insurance beneficiary'],
          a:'The beneficiaries you explicitly listed on the policy receive the money immediately, regardless of any will. If you haven\'t listed beneficiaries, the money will pass to your legal heirs according to an inheritance order.' },
        { q:'How do I update you if I\'ve changed jobs or my salary has gone up?', kw:['changed jobs','update my salary'],
          a:'Very simple - send a short message on WhatsApp or email with your new pay slip, and Tal will make sure to update your deposits and insurance coverage with the companies accordingly.' },
        { q:'Can the bot send me the Har HaBituach forms right now?', kw:['send insurance forms now','Har HaBituach'],
          a:'I can\'t generate official reports directly from the chat for data security reasons, but if you move to WhatsApp, Tal\'s team will produce the full report for you from the government system at no charge.' },
        { q:'What\'s the bottom line, why should I take this step specifically right now?', kw:['bottom line','why act now'],
          a:'Every day your money isn\'t managed properly, you\'re losing returns or paying for unnecessary insurance. Financial order brings peace of mind and immediate savings.' },
        { q:'The bot is stuck, how do I reach a human representative quickly?', kw:['bot is stuck','talk to a human fast'],
          a:'Oh, sorry about that! Just click the button to switch to WhatsApp in the chat, and Tal\'s human team will get back to you as soon as possible.' },
        { q:'Where can I read client testimonials about Tal?', kw:['client testimonials','reviews'],
          a:'We have a testimonials and success stories page right here on the site! You\'re also welcome to search for us on Google and read our clients\' reviews.' },
        { q:'I\'m trying to upload a Har HaBituach file and the chat won\'t let me, what do I do?', kw:['upload a file','file upload not working'],
          a:'No problem - you can send the file directly to the office\'s WhatsApp (there\'s a button for that in the chat) or by email, and we\'ll be happy to review it.' },
        // TRANSLATOR NOTE: this item may describe a capability Tuli doesn't actually have - flag for Tal to review (implies a file-upload attempt in the chat interface; per project context, document uploads are disabled site-wide)
        { q:'Is the meeting with Tal free, or does it commit me to something?', kw:['is the meeting free','no obligation'],
          a:'The initial meeting is free of charge and doesn\'t commit you to anything. The goal is to get acquainted, get organized, and show you where you can improve and save.' },
        { q:'Bot, can you send me a link to the pension clearinghouse?', kw:['link to pension clearinghouse','send me a link'],
          a:'As a bot I don\'t send direct external links, but if you move to WhatsApp, we\'ll be happy to guide you exactly how to get the information, or produce it for you securely.' },
        { q:'What\'s the difference between you and the big insurance companies\' bots?', kw:['other insurance company bots','how are you different'],
          a:'Insurance company bots only know how to sell their own company\'s products. I\'m Tal\'s assistant, and Tal works with all the companies, so our only interest is what\'s good for you.' },
        { q:'Can you also answer me in English or Russian?', kw:['English','Russian','other languages'],
          a:'I mainly understand and speak Hebrew (there\'s a full English version of me on the site too), but Tal and the office team would be happy to speak with you in any relevant language.' },
        { q:'How do I know my financial data won\'t be exposed to others?', kw:['data privacy','financial data exposed'],
          a:'We operate under the Privacy Protection Law and strict security standards. Any information you provide directly to Tal (for example, on WhatsApp) is handled with full confidentiality and isn\'t stored publicly.' },
        { q:'I want to cancel the meeting I scheduled with Tal, how do I do that?', kw:['cancel my meeting','cancel appointment'],
          a:'We\'re sorry to hear that, but it\'s completely fine. Just message Tal on WhatsApp to let him know, and he\'ll take care of updating the appointment.' },
        { q:'Is Tal also a tax advisor, or just an insurance agent?', kw:['tax advisor','insurance agent only'],
          a:'Tal is a pension insurance agent and financial planner. He has very deep knowledge of pension and retirement taxation (such as fixing tax benefit rights), and works closely with accountants and tax advisors when needed.' },
        { q:'What is Tal\'s professional motto in guiding his clients?', kw:['professional motto','philosophy'],
          a:'Tal\'s motto is: "Smart planning today - peace of mind tomorrow." The goal is to bring every client to maximum financial security through personal tailoring, uncompromising professionalism, and full availability along the way.' },
        { q:'How much money do I have?', kw:['how much money do I have','my balance'],
          a:'I (the bot) can\'t see your account for security reasons, but if you move to WhatsApp, Tal will generate a comprehensive report from the clearinghouse for you, and you\'ll know exactly how much you have.' },
        { q:'Are you cheap or expensive?', kw:['cheap or expensive','how much does it cost'],
          a:'Tal\'s service saves clients thousands of shekels in insurance and management fees and maximizes returns. The initial check-up is free, so at the end of the day you only gain.' },
        { q:'Why should I trust you at all?', kw:['why should I trust you','trust'],
          a:'Tal operates under an official, regulated license from the Israel Capital Market, Insurance and Savings Authority, and is legally obligated to act solely for your financial and personal benefit.' },
        { q:'What\'s your phone number?', kw:['phone number','your phone'],
          a:'Click the WhatsApp button on the site, and Tal\'s team will get back to you shortly!' },
        { q:'Are you real?', kw:['are you real','are you a human'],
          a:'I\'m Tal\'s digital assistant - a bot based on fixed pre-set rules, not a human and not artificial intelligence. I\'m here to answer quick questions, but the one who manages your portfolio and does the real financial magic is Tal himself, in a meeting.' },
        { q:'Can I get a loan?', kw:['can I get a loan','loan'],
          a:'We\'re not a lending institution, but Tal knows how to secure clients very cheap loans at excellent interest rates against their existing study funds or pension funds.' },
        { q:'Where is the office?', kw:['where is the office','office location'],
          a:'Tal\'s office is located in Rehovot, and full digital service via Zoom is also available throughout the country.' },
        { q:'Are there any penalties here?', kw:['penalties','exit fees'],
          a:'Absolutely not. Modern financial products (savings policies, provident funds) don\'t have withdrawal penalties or exit fees. Your money remains entirely yours.' },
        { q:'When will we be rich?', kw:['when will I be rich','get rich'],
          a:'Real wealth is built with patience, smart planning, and the effect of compound interest. The first step is to get your existing portfolio in order with Tal.' },
        { q:'Bye', kw:['bye','goodbye'],
          a:'Glad I could help! If you need anything else, you can always message me here or move to WhatsApp to chat with Tal. Have a great day!' },
        { q:'Does Tal also handle old veteran pension funds (like Mivtachim HaVatika)?', kw:['old pension funds','Mivtachim'],
          a:'Yes, absolutely. Veteran pension funds are very complex products with unique rules. Tal has extensive expertise managing and planning retirement that includes these veteran funds.' },
        { q:'How long until Tal gets back to me after I leave my details here?', kw:['how long to hear back','response time'],
          a:'Tal\'s team makes an effort to respond to every inquiry within 24 to 48 hours at most (on business days), in order to schedule the most convenient meeting time for you.' },
        { q:'Do you have an app I can use to track my portfolio\'s performance?', kw:['tracking app','app to monitor portfolio'],
          a:'Every insurance company and investment house has its own app and personal area where you can track your data. Tal consolidates the full picture for you during service meetings.' },
        { q:'Does Tal work together with lawyers or accountants?', kw:['lawyers','accountants','work with attorneys'],
          a:'Yes. For complex retirement or tax planning (such as family wealth transfer or executive retirement), Tal works in full cooperation with the client\'s accountants and attorneys.' },
        { q:'What happens if I have a financial product with a company Tal doesn\'t work with?', kw:['company Tal doesn\'t work with','other company product'],
          a:'Tal works with all the leading financial institutions and investment houses in Israel, so there\'s almost no product on the market that Tal can\'t analyze, manage, or improve for you.' },
        { q:'Does your financial check-up also include a review of my children\'s savings?', kw:['children\'s savings','kids savings accounts'],
          a:'Absolutely, yes. Tal takes a holistic, family-wide view - we examine all the household\'s assets, including programs like the Child Savings Plan and children\'s provident funds.' },
        { q:'Bot, can you tell me what the average management fees are in the market today?', kw:['average management fees','typical fees'],
          a:'Management fees vary a lot depending on the size of your accumulated savings. For pensions, the average is around 0.15%-0.25% of the balance, and for savings policies around 0.7%-1%. Tal always aims to get you below the average.' },
        { q:'How do I know Tal is really updating my portfolio over the years and not forgetting about me?', kw:['does Tal forget clients','ongoing monitoring'],
          a:'We work with advanced monitoring systems that alert us to changes in your investment tracks, sharp drops or rises, or changes in your status, and we hold proactive service meetings.' },
        { q:'Does the Har HaBituach report also show collective car insurance from work?', kw:['collective car insurance from work','Har HaBituach report'],
          a:'Usually not. Har HaBituach focuses on personal insurance (health, life, long-term care) and personal property insurance. Tal will help you manually map your workplace insurance against your pay slip.' },
        { q:'Why does the pension clearinghouse cost money, and who pays for it - me or Tal?', kw:['clearinghouse cost','who pays the fee'],
          a:'The clearinghouse is a government system that charges a small fee for pulling the data. As part of our service, we absorb this cost, and the check-up is performed for you at no direct cost.' },
        { q:'How can I find out if I have lost pension funds with an employer I worked for 15 years ago?', kw:['lost pension funds','old employer money'],
          a:'The power of attorney you sign allows Tal to run a comprehensive query using your ID number against all the management companies in the country, and locate even "dormant" funds from decades ago.' + GENERIC_CTA },
        { q:'How long after signing the digital forms does the new insurance take effect?', kw:['when does new policy start','how long to activate'],
          a:'It depends on the medical underwriting process. If you\'re completely healthy, the policy can be issued within a few days. If medical documents are required, it can take two to three weeks.' },
        { q:'What happens if the insurance company made a mistake and charged me more than what Tal promised me?', kw:['overcharged by insurance','billing error'],
          a:'No need to worry. Tal and the team keep a copy of the signed quote. We contact the company\'s billing department directly, make sure the error is corrected, and refund every extra shekel charged.' },
        { q:'Do you have a WhatsApp reminder service before a policy or management fee discount is about to expire?', kw:['reminders before discount expires','WhatsApp alerts'],
          a:'Yes! The office\'s computer systems automatically alert us two months before management fee discounts or variable premiums are set to expire, and Tal works to renew them for you in advance.' },
        { q:'What\'s the difference between a policy copy and a consolidated annual report, and why does Tal need both?', kw:['policy copy vs annual report','why need both documents'],
          a:'A policy copy shows the exact contract terms and coverage of your insurance. An annual report shows the financial status and returns as of year-end. Tal cross-references both to get the full picture.' },
        { q:'How do I cancel a Zoom meeting I scheduled with you if I have a work emergency?', kw:['cancel Zoom meeting','work emergency'],
          a:'It\'s all fine, we understand. Just send us a quick message here in the chat or on WhatsApp, and we\'ll offer you new times.' },
        { q:'Does Tal also serve foreign workers or non-residents who have assets in Israel?', kw:['foreign residents','non-resident assets in Israel'],
          a:'Tal specializes in Israeli tax and pension law. If you\'re a non-resident with funds accumulated in Israel in the past or local assets, Tal definitely knows how to handle them and get things in order.' },
        { q:'What\'s the first step the bot recommends I take right now to stop wasting money?', kw:['first step to stop wasting money','where to start'],
          a:'The smartest, simplest step is to move to WhatsApp (there\'s a button for that in the chat). Tal\'s team will get in touch with you, generate the official government reports for you, and we\'ll start getting your finances in order.' },
        { q:'I want to compare my pension fund against three other companies, can the bot do that?', kw:['compare pension funds','fund comparison'],
          a:'I (the bot) can give you general data, but a real, professional comparison (return metrics and management fees) is done through Tal\'s simulation systems during a meeting.' },
        { q:'Do you have physical branches, or is everything handled online and by phone?', kw:['physical branches','online only'],
          a:'We believe in digital efficiency. The service is handled quickly and securely via Zoom, phone, and WhatsApp, saving you valuable time and travel, without compromising the quality of advice.' },
        { q:'How do I sign the forms Tal sends me? Do I need to print and scan them?', kw:['digital signature','print and scan forms'],
          a:'Not at all! All our signatures are fully digital. You get a secure link on your phone, sign with your finger on the screen in one second, and the forms come back to us automatically.' },
        { q:'What happens if I have an urgent question on Friday afternoon or on Shabbat?', kw:['urgent question on weekend','Friday afternoon'],
          a:'You can always message me (the bot) here on the site 24/7! If the question requires a human answer from Tal or the team, we\'ll get back to you as soon as the office reopens.' },
        { q:'Does Tal charge money for producing the pension clearinghouse and Har HaBituach report?', kw:['charge for the report','clearinghouse report fee'],
          a:'No, this service is provided to our clients completely free of charge as part of the initial review and mapping of your financial and insurance portfolio.' },
        { q:'What\'s the difference between you and an insurance agent tied to a specific company?', kw:['tied agent','company-specific agent'],
          a:'An agent tied to a specific company is obligated to sell only their products. Tal is an independent agent who works with every company on the market, and his only interest is finding the best and cheapest product for you.' },
        { q:'Is the medical information I share when talking with Tal kept safely with you?', kw:['medical information','kept confidential'],
          a:'Absolutely. We\'re bound by the Privacy Protection Law and the strictest medical confidentiality regulations. The information is used solely for submitting your application to insurance companies and is not passed on to any other party.' },
        { q:'How do I schedule a follow-up meeting with Tal if I\'m already an existing client of the office?', kw:['existing client','follow-up meeting'],
          a:'Very simple - message us on WhatsApp or leave a message here saying "I\'m an existing client and would like a meeting," and the team will schedule a quick slot in Tal\'s calendar with no bureaucracy.' },
        { q:'Can the bot explain what the Sharpe ratio shown in investment portfolio reports means?', kw:['Sharpe ratio','what is Sharpe ratio'],
          a:'The Sharpe ratio measures how much return a portfolio generated relative to the level of risk taken. The higher the Sharpe ratio, the smarter and more stable the return the investment manager achieved.' },
        { q:'What happens if I decide to stop the service with Tal and switch to another agent?', kw:['leaving Tal','switch to another agent'],
          a:'The money and policies remain yours and with the insurance companies no matter what! There are no penalties, lock-in, or obligations. Tal\'s aim is to give such good service that you\'ll never want to leave.' },
        { q:'What is Tal\'s greatest success in retirement planning for his clients?', kw:['greatest success story','biggest achievement'],
          a:'The greatest success is seeing a client who arrived worried and confused, and retires with a clear roadmap, financial security, after we saved them tens or hundreds of thousands of shekels in unnecessary tax payments.' }
      ]},
      { key:'install', label:'📲 Install the App', items:[] },
      { key:'feedback', label:'💬 Help Us Improve', items:[] }
    ];

    document.head.insertAdjacentHTML('beforeend',
      '<style>.tuli-widget{direction:ltr} .tuli-chip{text-align:left}</style>'
    );

    document.body.insertAdjacentHTML('beforeend',
      '<div class="tuli-widget" id="tuli-widget">' +
        '<button class="tuli-fab" id="tuli-fab" aria-label="Open Tuli - the virtual assistant" aria-expanded="false">' +
          '<img src="../tuli-bot.png" alt="" />' +
        '</button>' +
        '<div class="tuli-panel" id="tuli-panel" role="dialog" aria-label="Chat with Tuli" aria-hidden="true">' +
          '<div class="tuli-panel-head">' +
            '<div class="tuli-who">' +
              '<div class="tuli-avatar"><img src="../tuli-bot.png" alt="" /></div>' +
              '<div>' +
                '<div class="tuli-name">Tuli</div>' +
                '<div class="tuli-status">Tal\'s virtual assistant</div>' +
              '</div>' +
            '</div>' +
            '<button id="tuli-close" aria-label="Close chat">&times;</button>' +
          '</div>' +
          '<div class="tuli-scroll">' +
            '<div class="tuli-msgs" id="tuli-msgs"></div>' +
            '<div class="tuli-chips" id="tuli-chips"></div>' +
          '</div>' +
          '<div class="tuli-input-row">' +
            '<input id="tuli-input" type="text" placeholder="Type a question..." aria-label="Type a question for Tuli" />' +
            '<button id="tuli-send">Send</button>' +
          '</div>' +
          '<div class="tuli-foot">Based on a fixed Q&A bank · not AI</div>' +
        '</div>' +
      '</div>'
    );

    var widget = document.getElementById('tuli-widget');
    var scrollEl = document.querySelector('.tuli-scroll');
    var msgsEl = document.getElementById('tuli-msgs');
    var chipsEl = document.getElementById('tuli-chips');
    var fab = document.getElementById('tuli-fab');
    var panel = document.getElementById('tuli-panel');
    var closeBtn = document.getElementById('tuli-close');
    var input = document.getElementById('tuli-input');
    var sendBtn = document.getElementById('tuli-send');

    var stage = 'greet1';
    var currentCat = null;
    var greetTimer = null;
    var started = false;

    function scrollToBottom(){
      requestAnimationFrame(function(){
        requestAnimationFrame(function(){
          scrollEl.scrollTop = scrollEl.scrollHeight;
        });
      });
    }
    function addMsg(text, who){
      var d = document.createElement('div');
      d.className = 'tuli-msg ' + who;
      d.textContent = text;
      msgsEl.appendChild(d);
      scrollToBottom();
    }
    function showTyping(cb){
      var d = document.createElement('div');
      d.className = 'tuli-msg bot tuli-typing';
      d.innerHTML = '<span></span><span></span><span></span>';
      msgsEl.appendChild(d);
      scrollToBottom();
      setTimeout(function(){ d.remove(); cb(); }, 250);
    }
    function botSay(text, cb){ showTyping(function(){ addMsg(text, 'bot'); if (cb) cb(); }); }
    function clearChips(){ chipsEl.innerHTML = ''; }
    function addChip(label, onClick, cls){
      var c = document.createElement('button');
      c.className = 'tuli-chip' + (cls ? ' ' + cls : '');
      c.type = 'button';
      c.textContent = label;
      c.addEventListener('click', onClick);
      chipsEl.appendChild(c);
      scrollToBottom();
    }
    function openWhatsapp(){
      window.open('https://wa.me/972528000556', '_blank', 'noopener');
    }
    function startGreeting(){
      stage = 'greet1';
      botSay('Hi there!');
      greetTimer = setTimeout(function(){ botSay('How\'s it going?'); }, 5000);
    }
    function introSelf(cb){
      showTyping(function(){
        var d = document.createElement('div');
        d.className = 'tuli-msg bot';
        var line1 = document.createElement('div');
        line1.textContent = 'I\'m Tuli';
        var line2 = document.createElement('div');
        line2.textContent = 'Tal\'s bot';
        var img = document.createElement('img');
        img.src = '../tuli-bot.png';
        img.alt = '';
        img.style.cssText = 'width:64px;height:64px;object-fit:contain;display:block;margin-top:.4rem';
        img.onload = scrollToBottom;
        d.appendChild(line1);
        d.appendChild(line2);
        d.appendChild(img);
        msgsEl.appendChild(d);
        scrollToBottom();
        if (cb) cb();
      });
    }
    function armTopicWait(){
      stage = 'greet3';
      greetTimer = setTimeout(function(){ startTopicStage(); }, 5000);
    }
    function startTopicStage(){
      stage = 'question';
      clearChips();
      currentCat = null;
      botSay('How can I help you?', function(){
        botSay('Pick a category, or type a free-form question:', function(){
          categories.forEach(function(cat){
            addChip(cat.label, function(){ chooseCategory(cat); });
          });
        });
      });
    }
    function chooseCategory(cat){
      addMsg(cat.label, 'user');
      clearChips();
      currentCat = cat;
      if (cat.key === 'feedback'){ startFeedbackStage(); return; }
      if (cat.key === 'install'){ startInstallStage(); return; }
      botSay('Here are some common questions on this topic - you can click one, or type your own question (there are many more beyond what\'s shown):', function(){
        var shown = cat.items.slice(0, 5);
        var rest = cat.items.slice(5);
        function renderShown(){
          clearChips();
          shown.forEach(function(item){
            addChip(item.q, function(){ askItem(item); });
          });
          if (rest.length){
            addChip('More questions on this topic (' + rest.length + ')', function(){
              shown = shown.concat(rest.splice(0, 5));
              renderShown();
            });
          }
          addChip('Back to categories', function(){ startTopicStage(); }, 'tuli-back');
        }
        renderShown();
      });
    }
    function askItem(item){
      addMsg(item.q, 'user');
      clearChips();
      botSay(item.a, function(){
        addChip('Want Tal to look into this personally?', function(){ startLeadStage(); });
        if (currentCat){
          addChip('Another question from this category', function(){ chooseCategory(currentCat); });
        }
      });
    }
    function matchAll(text){
      var lower = text.toLowerCase();
      var best = null, bestScore = 0;
      categories.forEach(function(cat){
        cat.items.forEach(function(item){
          var score = 0;
          item.kw.forEach(function(k){ if (lower.indexOf(k) !== -1) score++; });
          if (score > bestScore){ bestScore = score; best = item; }
        });
      });
      return bestScore > 0 ? best : null;
    }
    function handleQuestion(text){
      var found = matchAll(text);
      if (found) askItem(found);
      else botSay('I couldn\'t find an exact answer for that... should I pass it on to Tal?', function(){
        clearChips();
        addChip('Yes, pass it on', function(){
          addMsg('Yes, pass it on', 'user');
          startLeadStage();
        });
        addChip('No thanks', function(){
          addMsg('No thanks', 'user');
          botSay('No problem. You can also go back to categories any time.', function(){
            clearChips();
            addChip('Back to categories', function(){ startTopicStage(); });
          });
        });
      });
    }
    function notifyTal(){
      var fd = new FormData();
      fd.append('_subject', 'Tuli: a visitor opened a chat with the bot (English site)');
      fd.append('Page', location.href);
      fd.append('Time', new Date().toLocaleString('en-US'));
      fetch('https://formspree.io/f/maqrwedd', { method: 'POST', headers: { 'Accept': 'application/json' }, body: fd }).catch(function(){});
    }
    function startLeadStage(){
      var catToResume = currentCat;
      clearChips();
      botSay('Happy to help - I\'m transferring you to Tal\'s WhatsApp now to continue there directly.', function(){
        openWhatsapp();
        if (catToResume){
          botSay('In the meantime, here are all the questions on this topic - feel free to keep browsing:', function(){
            chooseCategory(catToResume);
          });
        } else {
          startTopicStage();
        }
      });
    }

    var feedbackQuestions = [
      { key:'opinion', q:'What do you think of the website?', type:'text' },
      { key:'improve', q:'How would you improve it? What would you add or remove?', type:'text' },
      { key:'rating', q:'From 1 to 10, how would you rate your overall experience on the site?', type:'scale' },
      { key:'nps', q:'From 1 to 10, how likely are you to recommend the site to a friend?', type:'scale' }
    ];
    function startInstallStage(){
      botSay('Great! Installing the site as an app on your phone gives you fast, one-tap access right from your home screen.', function(){
        addChip('📲 Install now', function(){
          if (window.pwaInstall) window.pwaInstall();
        });
        addChip('Back to categories', function(){ startTopicStage(); });
      });
    }
    var feedbackAnswers = {};
    var feedbackStep = 0;
    function startFeedbackStage(){
      stage = 'feedback';
      feedbackAnswers = {};
      feedbackStep = 0;
      clearChips();
      botSay('Great to have you here! I want to help Tal improve the site, and I\'d really love to hear from you - the feedback is completely anonymous, we won\'t ask for your name or details.', askFeedbackQuestion);
    }
    function askFeedbackQuestion(){
      if (feedbackStep >= feedbackQuestions.length){ finishFeedback(); return; }
      var q = feedbackQuestions[feedbackStep];
      clearChips();
      botSay(q.q, function(){
        if (q.type === 'scale'){
          for (var i = 1; i <= 10; i++){
            (function(n){
              addChip(String(n), function(){
                addMsg(String(n), 'user');
                feedbackAnswers[q.key] = n;
                feedbackStep++;
                askFeedbackQuestion();
              }, 'tuli-chip-num');
            })(i);
          }
        }
        addChip('Skip', function(){
          addMsg('Skip', 'user');
          feedbackStep++;
          askFeedbackQuestion();
        }, 'tuli-back');
      });
    }
    function submitFeedbackAnswer(val){
      var q = feedbackQuestions[feedbackStep];
      feedbackAnswers[q.key] = val;
      feedbackStep++;
      askFeedbackQuestion();
    }
    function submitFeedback(){
      var fd = new FormData();
      fd.append('_subject', 'Tuli: anonymous website feedback (English site)');
      fd.append('General opinion', feedbackAnswers.opinion || '(skipped)');
      fd.append('Improvement suggestions', feedbackAnswers.improve || '(skipped)');
      fd.append('Experience rating (1-10)', feedbackAnswers.rating != null ? feedbackAnswers.rating : '(skipped)');
      fd.append('Recommendation likelihood (1-10)', feedbackAnswers.nps != null ? feedbackAnswers.nps : '(skipped)');
      fd.append('Page', location.href);
      fd.append('Time', new Date().toLocaleString('en-US'));
      fetch('https://formspree.io/f/maqrwedd', { method: 'POST', headers: { 'Accept': 'application/json' }, body: fd }).catch(function(){});
    }
    function finishFeedback(){
      clearChips();
      submitFeedback();
      botSay('Thank you so much for the feedback! It really helps Tal improve the site.', function(){
        offerShare();
      });
    }
    function offerShare(){
      var shareMsg = 'I found a really good site for retirement, insurance, and investment planning - Tal Gabay. Worth checking out: https://procapital.co.il';
      botSay('Glad to hear it! Has a friend of yours been weighing pension or insurance decisions lately? Here\'s a ready-made message you can send with one click:', function(){
        if (navigator.share){
          addChip('📤 Share', function(){
            navigator.share({ text: shareMsg, url: 'https://procapital.co.il' }).catch(function(){});
          });
        } else {
          addChip('📤 Share on WhatsApp', function(){
            window.open('https://wa.me/?text=' + encodeURIComponent(shareMsg), '_blank', 'noopener');
          });
        }
        addChip('📋 Copy link', function(){
          if (navigator.clipboard && navigator.clipboard.writeText){
            navigator.clipboard.writeText('https://procapital.co.il').then(function(){
              addMsg('Link copied!', 'bot');
            }).catch(function(){});
          }
        });
        addChip('Back to categories', function(){ startTopicStage(); }, 'tuli-back');
      });
    }

    function handleSend(){
      var val = input.value.trim();
      if (!val || input.disabled) return;
      addMsg(val, 'user');
      input.value = '';
      if (stage === 'greet1'){
        clearTimeout(greetTimer);
        stage = 'greet2';
        botSay('Great to hear from you 👋🏼');
        greetTimer = setTimeout(function(){ stage = 'greet3'; introSelf(function(){ armTopicWait(); }); }, 7000);
      } else if (stage === 'greet2'){
        clearTimeout(greetTimer);
        stage = 'greet3';
        introSelf(function(){ armTopicWait(); });
      } else if (stage === 'greet3'){
        clearTimeout(greetTimer);
        startTopicStage();
      } else if (stage === 'question') handleQuestion(val);
      else if (stage === 'feedback') submitFeedbackAnswer(val);
    }

    function closePanel(){
      panel.classList.remove('open');
      fab.setAttribute('aria-expanded','false');
      panel.setAttribute('aria-hidden','true');
    }
    fab.addEventListener('click', function(){
      var open = panel.classList.toggle('open');
      fab.setAttribute('aria-expanded', open);
      panel.setAttribute('aria-hidden', !open);
      if (open && !started){ started = true; notifyTal(); startGreeting(); }
      if (open) input.focus();
    });
    closeBtn.addEventListener('click', closePanel);
    sendBtn.addEventListener('click', handleSend);
    input.addEventListener('keydown', function(e){ if(e.key==='Enter'){ handleSend(); } });
    document.addEventListener('click', function(e){
      var path = e.composedPath ? e.composedPath() : [e.target];
      if (path.indexOf(widget) === -1) closePanel();
    });
    document.addEventListener('keydown', function(e){ if(e.key==='Escape' && panel.classList.contains('open')){ closePanel(); fab.focus(); } });
  })();
